cat > src/lang/types.ts <<'EOF'
export type Mode = "2d" | "3d";
export type Vec3 = [number, number, number];

export interface Segment {
  from: Vec3;
  to: Vec3;
  color: string;
  width: number;
}

export interface LogoError {
  message: string;
  line: number;
  column: number;
}

export interface RunResult {
  segments: Segment[];
  error: LogoError | null;
}
EOF
cat > src/lang/lexer.ts <<'EOF'
export type TokenKind = "word" | "number";

export interface Token {
  kind: TokenKind;
  text: string;
  /** Lower-cased text for words. */
  lower: string;
  value: number;
  line: number;
  column: number;
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let col = 1;
  while (i < source.length) {
    const ch = source[i];
    if (ch === "\n") { i++; line++; col = 1; continue; }
    if (/\s/.test(ch)) { i++; col++; continue; }
    const start = i;
    const startCol = col;
    if (/\d/.test(ch)) {
      while (i < source.length && /\d/.test(source[i])) { i++; col++; }
      const text = source.slice(start, i);
      tokens.push({ kind: "number", text, lower: text, value: Number(text), line, column: startCol });
      continue;
    }
    while (i < source.length && /[\p{L}\p{N}_]/u.test(source[i])) { i++; col++; }
    const text = source.slice(start, i);
    tokens.push({ kind: "word", text, lower: text.toLowerCase(), value: NaN, line, column: startCol });
  }
  return tokens;
}
EOF
cat > src/lang/index.ts <<'EOF'
import { tokenize } from "./lexer";
import type { Mode, RunResult, Segment, Vec3 } from "./types";

export type { Mode, RunResult, Segment, LogoError, Vec3 } from "./types";

export function run(source: string, _mode: Mode): RunResult {
  const tokens = tokenize(source);
  const segments: Segment[] = [];
  let pos: Vec3 = [0, 0, 0];
  for (let i = 0; i < tokens.length; i++) {
    if (tokens[i].lower === "np") {
      const d = tokens[++i].value;
      const to: Vec3 = [pos[0], pos[1] + d, pos[2]];
      segments.push({ from: pos, to, color: "#16866a", width: 3 });
      pos = to;
    }
  }
  return { segments, error: null };
}
EOF
