import type { Vec3 } from "./types";

/** sin/cos in degrees, exact for whole multiples of 90°. */
export function sinCos(deg: number): [number, number] {
  const r = deg % 360;
  const q = r / 90;
  if (Number.isInteger(q)) {
    const k = ((q % 4) + 4) % 4;
    return [[0, 1, 0, -1][k], [1, 0, -1, 0][k]];
  }
  const rad = (r * Math.PI) / 180;
  return [Math.sin(rad), Math.cos(rad)];
}

const add = (a: Vec3, b: Vec3, k: number): Vec3 => [a[0] + b[0] * k, a[1] + b[1] * k, a[2] + b[2] * k];

/** Rotates `a` towards `b` by `deg`; returns [a', b'] keeping the pair orthonormal. */
function rotatePair(a: Vec3, b: Vec3, deg: number): [Vec3, Vec3] {
  const [s, c] = sinCos(deg);
  const a2: Vec3 = [a[0] * c + b[0] * s, a[1] * c + b[1] * s, a[2] * c + b[2] * s];
  const b2: Vec3 = [b[0] * c - a[0] * s, b[1] * c - a[1] * s, b[2] * c - a[2] * s];
  return [a2, b2];
