export type TokenKind =
  | "word"
  | "param" // :name
  | "label" // name: (as in "ma:")
  | "number"
  | "string"
  | "lbracket"
  | "rbracket"
  | "lparen"
  | "rparen"
  | "op" // + - * /
  | "cmp" // < > = <= >= <>
  | "comma"
  | "error"
  | "eof";

export interface Token {
  kind: TokenKind;
  /** Source text of the token. */
  text: string;
  /** Lower-cased, NFC-normalised name for words, params and labels; the string body for strings. */
  lower: string;
  value: number;
  line: number;
  column: number;
  offset: number;
  end: number;
  spaceBefore: boolean;
  spaceAfter: boolean;
  firstOnLine: boolean;
  lastOnLine: boolean;
  /** For error tokens: the Polish message. */
  message?: string;
}

export const MAX_SOURCE = 50_000;
export const MAX_TOKENS = 10_000;

const LETTER = /[\p{L}\p{M}_]/u;
const WORD_CHAR = /[\p{L}\p{M}\p{N}_]/u;
const DIGIT = /[0-9]/;
const SPACE = /\s/;

export function normalizeName(text: string): string {
  return text.normalize("NFC").toLowerCase();
}

/**
 * Splits source into tokens. Never throws: lexical problems become "error"
 * tokens so the parser reports the earliest problem in source order.
 * The returned list always ends with an "eof" token.
 */
export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  const n = source.length;
  let i = 0;
  let line = 1;
  let lineStart = 0;

  const push = (kind: TokenKind, start: number, end: number, extra: Partial<Token> = {}) => {
    const text = source.slice(start, end);
    tokens.push({
      kind,
      text,
      lower: extra.lower ?? text,
      value: extra.value ?? NaN,
      line,
      column: start - lineStart + 1,
      offset: start,
      end,
      spaceBefore: start === 0 || SPACE.test(source[start - 1]),
      spaceAfter: end >= n || SPACE.test(source[end]),
      firstOnLine: false,
      lastOnLine: false,
      message: extra.message,
    });
  };

  while (i < n) {
    const ch = source[i];
    if (ch === "\n") {
      i++;
      line++;
      lineStart = i;
      continue;
    }
    if (SPACE.test(ch)) {
      i++;
      continue;
    }
    if (ch === ";") {
      while (i < n && source[i] !== "\n") i++;
      continue;
    }
    const start = i;
    if (DIGIT.test(ch) || (ch === "." && DIGIT.test(source[i + 1] ?? ""))) {
      while (i < n && DIGIT.test(source[i])) i++;
      if (source[i] === "." && DIGIT.test(source[i + 1] ?? "")) {
        i++;
        while (i < n && DIGIT.test(source[i])) i++;
      }
      if (i < n && (WORD_CHAR.test(source[i]) || source[i] === ".")) {
        while (i < n && (WORD_CHAR.test(source[i]) || source[i] === ".")) i++;
        const text = source.slice(start, i);
        push("error", start, i, {
          message: `„${text}” nie jest poprawną liczbą. Liczby zapisuje się cyframi, z kropką przed częścią ułamkową, np. 80, 12.5 albo .5.`,
        });
        continue;
      }
      push("number", start, i, { value: Number(source.slice(start, i)) });
      continue;
    }
    if (LETTER.test(ch)) {
      while (i < n && WORD_CHAR.test(source[i])) i++;
      const name = normalizeName(source.slice(start, i));
      if (source[i] === ":") {
        i++;
        push("label", start, i, { lower: name });
      } else {
        push("word", start, i, { lower: name });
      }
      continue;
    }
    if (ch === ":") {
      i++;
      if (i < n && LETTER.test(source[i])) {
        const nameStart = i;
        while (i < n && WORD_CHAR.test(source[i])) i++;
        push("param", start, i, { lower: normalizeName(source.slice(nameStart, i)) });
      } else {
        push("error", start, i, { message: "Po dwukropku powinna stać nazwa, np. :bok." });
      }
      continue;
    }
    if (ch === '"') {
      let j = i + 1;
      while (j < n && source[j] !== '"' && source[j] !== "\n") j++;
      if (source[j] === '"') {
        i = j + 1;
        push("string", start, i, { lower: source.slice(start + 1, j) });
      } else {
        i = j;
        push("error", start, i, {
          message: 'Brakuje cudzysłowu zamykającego. Kolor zapisuje się w cudzysłowie, np. "#16866a".',
        });
      }
      continue;
    }
    i++;
    switch (ch) {
      case "[":
        push("lbracket", start, i);
        break;
      case "]":
        push("rbracket", start, i);
        break;
      case "(":
        push("lparen", start, i);
        break;
      case ")":
        push("rparen", start, i);
        break;
      case ",":
        push("comma", start, i);
        break;
      case "+":
      case "-":
      case "*":
      case "/":
        push("op", start, i);
        break;
      case "<":
        if (source[i] === "=" || source[i] === ">") i++;
        push("cmp", start, i);
        break;
      case ">":
        if (source[i] === "=") i++;
        push("cmp", start, i);
        break;
      case "=":
        push("cmp", start, i);
        break;
      default: {
        // Keep surrogate pairs (emoji) together in the message.
        const cp = source.codePointAt(start)!;
        if (cp > 0xffff) i++;
        push("error", start, i, { message: `Nieznany znak „${source.slice(start, i)}”.` });
      }
    }
  }

  for (let k = 0; k < tokens.length; k++) {
    tokens[k].firstOnLine = k === 0 || tokens[k - 1].line !== tokens[k].line;
    tokens[k].lastOnLine = k === tokens.length - 1 || tokens[k + 1].line !== tokens[k].line;
  }
  tokens.push({
    kind: "eof",
    text: "",
    lower: "",
    value: NaN,
    line,
    column: n - lineStart + 1,
    offset: n,
    end: n,
    spaceBefore: true,
    spaceAfter: true,
    firstOnLine: true,
    lastOnLine: true,
  });
  return tokens;
}

