export type TokenKind = "word" | "number";

export interface Token {
  kind: TokenKind;
  text: string;
  /** Lower-cased text for words. */
  lower: string;
  value: number;
  line: number;
  column: number;
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let col = 1;
  while (i < source.length) {
    const ch = source[i];
    if (ch === "\n") { i++; line++; col = 1; continue; }
    if (/\s/.test(ch)) { i++; col++; continue; }
    const start = i;
    const startCol = col;
    if (/\d/.test(ch)) {
      while (i < source.length && /\d/.test(source[i])) { i++; col++; }
      const text = source.slice(start, i);
      tokens.push({ kind: "number", text, lower: text, value: Number(text), line, column: startCol });
      continue;
    }
    while (i < source.length && /[\p{L}\p{N}_]/u.test(source[i])) { i++; col++; }
    const text = source.slice(start, i);
    tokens.push({ kind: "word", text, lower: text.toLowerCase(), value: NaN, line, column: startCol });
  }
  return tokens;
}

