import type { Token } from "./lexer";

export type Expr =
  | { k: "num"; v: number }
  | { k: "var"; name: string; tok: Token }
  | { k: "repcount" }
  | { k: "neg"; e: Expr }
  | { k: "bin"; op: "+" | "-" | "*" | "/"; l: Expr; r: Expr };

/** An argument: an expression plus the first token it was written with. */
export interface Arg {
  expr: Expr;
  tok: Token;
  hasNames: boolean;
}

export type CmpOp = "<" | ">" | "=" | "<=" | ">=" | "<>";

export interface Cond {
  l: Expr;
  op: CmpOp;
  r: Expr;
  tok: Token;
}

export type Stmt =
  | { k: "move"; sign: 1 | -1; arg: Arg; tok: Token }
  | { k: "turn"; axis: "yaw" | "pitch" | "roll"; sign: 1 | -1; arg: Arg; tok: Token }
  | { k: "pen"; down: boolean; tok: Token }
  | { k: "color"; color: string; tok: Token }
  | { k: "width"; arg: Arg; tok: Token }
  | { k: "repeat"; count: Arg; body: Stmt[]; tok: Token }
  | { k: "let"; name: string; arg: Arg; tok: Token }
  | { k: "if"; cond: Cond; then: Stmt[]; else: Stmt[] | null; tok: Token }
  | { k: "stop"; tok: Token }
  | { k: "home"; tok: Token }
  | { k: "clear"; tok: Token }
  | { k: "call"; proc: Procedure; args: Arg[]; tok: Token };

export interface Procedure {
  name: string;
  displayName: string;
  params: string[];
  body: Stmt[];
  tok: Token;
}

export interface Program {
  body: Stmt[];
  procedures: Map<string, Procedure>;
}

