import type { Arg, Expr, Stmt } from "./ast";
import type { Token } from "./lexer";
import { forwardTarget, initialTurtle, pitchUp, rollRight, turnRight, goHome, type TurtleState } from "./turtle";
import type { Segment, Vec3 } from "./types";

export class LogoRuntimeError extends Error {
  constructor(
    message: string,
    public tok: Token,
  ) {
    super(message);
  }
}

/** Yielded after every executed drawing or state command. */
export interface StepEvent {
  tok: Token;
}

export class Machine {
  turtle: TurtleState = initialTurtle();
  segments: Segment[] = [];

  constructor(private program: { body: Stmt[] }) {}

  *execute(): Generator<StepEvent, void, void> {
    yield* this.block(this.program.body);
  }

  private *block(body: Stmt[]): Generator<StepEvent, void, void> {
    for (const s of body) yield* this.stmt(s);
  }

  private *stmt(s: Stmt): Generator<StepEvent, void, void> {
    const t = this.turtle;
    switch (s.k) {
      case "move": {
        const to = forwardTarget(t, s.sign * this.arg(s.arg));
        this.moveTo(to);
        break;
      }
      case "turn": {
        const deg = s.sign * this.arg(s.arg);
        if (s.axis === "yaw") turnRight(t, deg);
        else if (s.axis === "pitch") pitchUp(t, deg);
        else rollRight(t, deg);
        break;
      }
      case "pen":
        t.penDown = s.down;
        break;
      case "color":
        t.color = s.color;
        break;
      case "width":
        t.width = this.arg(s.arg);
        break;
      case "home":
        this.moveTo([0, 0, 0]);
        goHome(t);
        break;
      case "clear":
        this.segments = [];
        break;
      case "repeat": {
        const n = this.arg(s.count);
        for (let i = 1; i <= n; i++) yield* this.block(s.body);
        return;
      }
      default:
        return;
    }
    yield { tok: s.tok };
  }

  private moveTo(to: Vec3): void {
    const t = this.turtle;
    const from = t.pos;
    if (t.penDown && (from[0] !== to[0] || from[1] !== to[1] || from[2] !== to[2])) {
      this.segments.push({ from, to, color: t.color, width: t.width });
    }
    t.pos = to;
  }

  private arg(a: Arg): number {
    return this.eval(a.expr);
  }

  private eval(e: Expr): number {
    switch (e.k) {
      case "num":
        return e.v;
      default:
        return NaN;
    }
  }
}

