import { tokenize } from "./lexer";
import { forwardTarget, initialTurtle, turnRight } from "./turtle";
import type { Mode, RunResult, Segment } from "./types";

export type { Mode, RunResult, Segment, LogoError, Vec3 } from "./types";

export function run(source: string, _mode: Mode): RunResult {
  const tokens = tokenize(source);
  const segments: Segment[] = [];
  const t = initialTurtle();
  for (let i = 0; i < tokens.length; i++) {
    const w = tokens[i].lower;
    if (w === "np") {
      const to = forwardTarget(t, tokens[++i].value);
      segments.push({ from: t.pos, to, color: t.color, width: t.width });
      t.pos = to;
    } else if (w === "pw") turnRight(t, tokens[++i].value);
    else if (w === "lw") turnRight(t, -tokens[++i].value);
  }
  return { segments, error: null };
}

