import type { Arg, CmpOp, Cond, Expr, Procedure, Program, Stmt } from "./ast";
import { COMMANDS, DEFINE_WORDS, END_WORDS, REPCOUNT_WORDS, RESERVED, type CommandId } from "./commands";
import { tokenize, type Token } from "./lexer";
import type { Mode } from "./types";

export class LogoSyntaxError extends Error {
  constructor(
    message: string,
    public tok: Token,
  ) {
    super(message);
  }
}

interface ProcInfo {
  proc: Procedure;
  /** Names assigned by niech somewhere in this procedure's body. */
  locals: Set<string>;
  /** The header token ("oto") of the first definition with this name. */
  header: Token;
}

const isWord = (t: Token, words: string[]) => t.kind === "word" && words.includes(t.lower);

class Parser {
  private i = 0;
  private procs = new Map<string, ProcInfo>();
  /** First token of the most recently parsed statement (for hints). */
  private lastStmt: Token | null = null;
  /** Names assigned by niech anywhere at top level. */
  private globals = new Set<string>();
  /** The procedure whose body is being parsed, or null at top level. */
  private current: ProcInfo | null = null;
  /** Lexical repeat nesting inside the current procedure (or top level). */
  private repeatDepth = 0;

  constructor(
    private source: string,
    private tokens: Token[],
    private mode: Mode,
  ) {}

  private peek(): Token {
    return this.tokens[this.i];
  }

  private next(): Token {
    return this.tokens[this.i++];
  }

  /**
   * Collects procedure headers (so calls may precede definitions and parse
   * with the right number of arguments) and every name assigned with niech,
   * per region, so uses may precede the assignment. Lenient: the main pass
   * reports malformed headers.
   */
  private prescan(): void {
    const t = this.tokens;
    let region: Set<string> = this.globals;
    let inProc = false;
    for (let k = 0; k < t.length - 1; k++) {
      const tok = t[k];
      if (!inProc && isWord(tok, DEFINE_WORDS) && tok.firstOnLine) {
        inProc = true;
        region = new Set();
        const nameTok = t[k + 1];
        if (nameTok.kind === "word" && nameTok.line === tok.line && !RESERVED.has(nameTok.lower) && !this.procs.has(nameTok.lower)) {
          const params: string[] = [];
          for (let j = k + 2; t[j].line === tok.line && t[j].kind !== "eof"; j++) {
            const p = t[j];
            if (p.kind === "param" || (p.kind === "word" && j > k + 2)) params.push(p.lower);
          }
          this.procs.set(nameTok.lower, {
            proc: { name: nameTok.lower, displayName: nameTok.text, params, body: [], tok: nameTok },
            locals: region,
            header: tok,
          });
        }
        continue;
      }
      if (inProc && isWord(tok, END_WORDS) && tok.firstOnLine && tok.lastOnLine) {
        inProc = false;
        region = this.globals;
        continue;
      }
      if (tok.kind === "word" && COMMANDS.get(tok.lower) === "let" && (t[k + 1].kind === "word" || t[k + 1].kind === "param")) {
        region.add(t[k + 1].lower);
      }
    }
  }

  parseProgram(): Program {
    this.prescan();
    const body: Stmt[] = [];
    while (this.peek().kind !== "eof") {
      if (isWord(this.peek(), DEFINE_WORDS)) this.parseDefinition();
      else body.push(this.parseStatement());
    }
    const procedures = new Map<string, Procedure>();
    for (const [name, info] of this.procs) procedures.set(name, info.proc);
    return { body, procedures };
  }

  private parseDefinition(): void {
    const oto = this.next();
    if (!oto.firstOnLine) {
      throw new LogoSyntaxError(`Definicja procedury („${oto.text}”) musi zaczynać się na początku wiersza.`, oto);
    }
    const nameTok = this.peek();
    if (nameTok.kind !== "word" || nameTok.line !== oto.line) {
      throw new LogoSyntaxError(
        `Po „${oto.text}” podaj w tym samym wierszu nazwę procedury, np. ${oto.text} kwadrat.`,
        nameTok.kind === "eof" || nameTok.line !== oto.line ? oto : nameTok,
      );
    }
    this.next();
    if (RESERVED.has(nameTok.lower)) {
      throw new LogoSyntaxError(`„${nameTok.text}” to słowo języka — nie może być nazwą procedury.`, nameTok);
    }
    const info = this.procs.get(nameTok.lower)!;
    if (info.header !== oto) {
      throw new LogoSyntaxError(
        `Procedura „${nameTok.text}” jest już zdefiniowana w wierszu ${info.header.line}. Każda nazwa może być zdefiniowana tylko raz.`,
        nameTok,
      );
    }
    info.proc.params = this.parseHeaderParams(oto);

    const saved = { current: this.current, repeatDepth: this.repeatDepth };
    this.current = info;
    this.repeatDepth = 0;
    const body: Stmt[] = [];
    for (;;) {
      const tok = this.peek();
      if (tok.kind === "eof") {
        throw new LogoSyntaxError(`Brakuje „już” kończącego procedurę „${nameTok.text}”. Napisz „już” sam w osobnym wierszu.`, oto);
      }
      if (isWord(tok, END_WORDS)) {
        if (!tok.firstOnLine || !tok.lastOnLine) {
          throw new LogoSyntaxError(`„${tok.text}” kończy procedurę i musi stać sam w osobnym wierszu.`, tok);
        }
        this.next();
        break;
      }
      if (isWord(tok, DEFINE_WORDS)) {
        throw new LogoSyntaxError(
          `Nie można zdefiniować procedury wewnątrz innej procedury. Zakończ „${nameTok.text}” słowem „już” przed nową definicją.`,
          tok,
        );
      }
      body.push(this.parseStatement());
    }
    info.proc.body = body;
    this.current = saved.current;
    this.repeatDepth = saved.repeatDepth;
  }

  /** Parses "ma: a, b" or legacy ":a :b" on the header line. */
  private parseHeaderParams(oto: Token): string[] {
    const params: string[] = [];
    const onLine = () => this.peek().kind !== "eof" && this.peek().line === oto.line;
    const addParam = (p: Token) => {
      if (RESERVED.has(p.lower)) throw new LogoSyntaxError(`„${p.text}” to słowo języka — nie może być nazwą parametru.`, p);
      if (params.includes(p.lower)) throw new LogoSyntaxError(`Parametr „${p.text}” powtarza się w nagłówku.`, p);
      params.push(p.lower);
    };
    if (!onLine()) return params;
    const first = this.peek();
    if (first.kind === "label" && first.lower === "ma") {
      this.next();
      for (;;) {
        const p = this.peek();
        if (!onLine() || (p.kind !== "word" && p.kind !== "param")) {
          throw new LogoSyntaxError("Po „ma:” wypisz nazwy parametrów oddzielone przecinkami, np. ma: bok, kąt.", onLine() ? p : first);
        }
        this.next();
        addParam(p);
        if (!onLine()) break;
        const sep = this.peek();
        if (sep.kind !== "comma") {
          throw new LogoSyntaxError("Parametry w nagłówku oddziela się przecinkami, np. ma: bok, kąt.", sep);
        }
        this.next();
      }
      return params;
    }
    while (onLine()) {
      const p = this.peek();
      if (p.kind !== "param") {
        throw new LogoSyntaxError(
          "Niepoprawny nagłówek procedury. Parametry zapisuje się po „ma:”, np. oto kwadrat ma: bok — albo jako :bok.",
          p,
        );
      }
      this.next();
      addParam(p);
    }
    return params;
  }

  private parseBody(): Stmt[] {
    const open = this.next();
    if (open.kind !== "lbracket") throw new LogoSyntaxError("Oczekiwano listy poleceń w nawiasach [ ].", open);
    const body: Stmt[] = [];
    while (this.peek().kind !== "rbracket") {
      if (this.peek().kind === "eof") throw new LogoSyntaxError("Nawias „[” nie został zamknięty.", open);
      body.push(this.parseStatement());
    }
    this.next();
    return body;
  }

  private parseStatement(): Stmt {
    const stmt = this.parseStatementInner();
    this.lastStmt = stmt.tok;
    return stmt;
  }

  /** Text of a value written where a command was expected, e.g. "-5". */
  private strayText(tok: Token): string {
    if (tok.kind === "op") {
      const nxt = this.tokens[this.i + 1];
      if (nxt && nxt.offset === tok.end && nxt.kind !== "eof") return tok.text + nxt.text;
    }
    return tok.text;
  }

  private spacingHint(tok: Token): string {
    if (!this.lastStmt || tok.kind !== "op" || tok.spaceBefore === tok.spaceAfter) return "";
    const before = this.source.slice(this.lastStmt.offset, tok.offset).trimEnd();
    const nxt = this.tokens[this.i + 1];
    const after = nxt && nxt.kind !== "eof" ? nxt.text : "";
    const verb = { "+": "dodawanie", "-": "odejmowanie", "*": "mnożenie", "/": "dzielenie" }[tok.text];
    return ` Jeśli to ${verb}, postaw odstęp po obu stronach znaku „${tok.text}” (${before} ${tok.text} ${after}) albo nie stawiaj żadnego (${before}${tok.text}${after}).`;
  }

  private strayError(tok: Token): LogoSyntaxError {
    if (tok.kind === "op" && (tok.text === "*" || tok.text === "/")) {
      return new LogoSyntaxError(`Nieoczekiwany znak „${tok.text}” w miejscu polecenia.${this.spacingHint(tok)}`, tok);
    }
    return new LogoSyntaxError(
      `Nieoczekiwana wartość „${this.strayText(tok)}” w miejscu polecenia.${this.spacingHint(tok)}`,
      tok,
    );
  }

  private parseStatementInner(): Stmt {
    const tok = this.peek();
    if (tok.kind === "number" || tok.kind === "op" || tok.kind === "lparen" || tok.kind === "param" || tok.kind === "string") {
      throw this.strayError(tok);
    }
    this.next();
    const cmd: CommandId | undefined = tok.kind === "word" ? COMMANDS.get(tok.lower) : undefined;
    switch (cmd) {
      case "fd":
      case "bk":
        return { k: "move", sign: cmd === "fd" ? 1 : -1, arg: this.parseArg(), tok };
      case "rt":
      case "lt":
        return { k: "turn", axis: "yaw", sign: cmd === "rt" ? 1 : -1, arg: this.parseArg(), tok };
      case "pitchup":
      case "pitchdown":
        return { k: "turn", axis: "pitch", sign: cmd === "pitchup" ? 1 : -1, arg: this.parseArg(), tok };
      case "rollright":
      case "rollleft":
        return { k: "turn", axis: "roll", sign: cmd === "rollright" ? 1 : -1, arg: this.parseArg(), tok };
      case "pu":
      case "pd":
        return { k: "pen", down: cmd === "pd", tok };
      case "color": {
        const c = this.next();
        return { k: "color", color: c.lower.toLowerCase(), tok };
      }
      case "width":
        return { k: "width", arg: this.parseArg(), tok };
      case "repeat": {
        const count = this.parseArg();
        this.repeatDepth++;
        const body = this.parseBody();
        this.repeatDepth--;
        return { k: "repeat", count, body, tok };
      }
      case "if": {
        const cond = this.parseCond();
        return { k: "if", cond, then: this.parseBody(), else: null, tok };
      }
      case "ifelse": {
        const cond = this.parseCond();
        const then = this.parseBody();
        return { k: "if", cond, then, else: this.parseBody(), tok };
      }
      case "let": {
        const nameTok = this.next();
        if (nameTok.kind !== "word" && nameTok.kind !== "param") {
          throw new LogoSyntaxError("Po „niech” podaj nazwę zmiennej, np. niech bok 50.", nameTok.kind === "eof" ? tok : nameTok);
        }
        if (RESERVED.has(nameTok.lower)) {
          throw new LogoSyntaxError(`„${nameTok.text}” to słowo języka — nie może być nazwą zmiennej.`, nameTok);
        }
        if (this.procs.has(nameTok.lower)) {
          throw new LogoSyntaxError(`„${nameTok.text}” to nazwa procedury — zmienna musi nazywać się inaczej.`, nameTok);
        }
        return { k: "let", name: nameTok.lower, arg: this.parseArg(), tok };
      }
      case "stop":
        return { k: "stop", tok };
      case "home":
        return { k: "home", tok };
      case "cs":
        return { k: "clear", tok };
    }
    if (tok.kind === "word") {
      const info = this.procs.get(tok.lower);
      if (info) {
        const args = info.proc.params.map(() => this.parseArg());
        return { k: "call", proc: info.proc, args, tok };
      }
    }
    void this.mode;
    throw new LogoSyntaxError(`Nieznane polecenie „${tok.text}”.`, tok);
  }

  private parseArg(): Arg {
    const tok = this.peek();
    const expr = this.parseExpr();
    return { expr, tok, hasNames: hasNames(expr) };
  }

  private parseCond(): Cond {
    const tok = this.peek();
    const l = this.parseExpr();
    const opTok = this.next();
    if (opTok.kind !== "cmp") throw new LogoSyntaxError("W warunku brakuje porównania: <, >, =, <=, >= albo <>.", opTok);
    const r = this.parseExpr();
    return { l, op: opTok.text as CmpOp, r, tok };
  }

  /** A binary operator needs whitespace on both sides or on neither. */
  private isBinary(tok: Token, ops: string): boolean {
    return tok.kind === "op" && ops.includes(tok.text) && tok.spaceBefore === tok.spaceAfter;
  }

  private parseExpr(): Expr {
    let l = this.parseTerm();
    while (this.isBinary(this.peek(), "+-")) {
      const op = this.next().text as "+" | "-";
      l = { k: "bin", op, l, r: this.parseTerm() };
    }
    return l;
  }

  private parseTerm(): Expr {
    let l = this.parseUnary();
    while (this.isBinary(this.peek(), "*/")) {
      const op = this.next().text as "*" | "/";
      l = { k: "bin", op, l, r: this.parseUnary() };
    }
    return l;
  }

  private parseUnary(): Expr {
    let negative = false;
    while (this.peek().kind === "op" && (this.peek().text === "-" || this.peek().text === "+")) {
      if (this.next().text === "-") negative = !negative;
    }
    const e = this.parsePrimary();
    return negative ? { k: "neg", e } : e;
  }

  /** Is this name a parameter or a declared variable where it is used? */
  private isValueName(name: string): boolean {
    const cur = this.current;
    if (cur && (cur.proc.params.includes(name) || cur.locals.has(name))) return true;
    return this.globals.has(name);
  }

  private parsePrimary(): Expr {
    const tok = this.next();
    if (tok.kind === "number") return { k: "num", v: tok.value };
    if (tok.kind === "word" && REPCOUNT_WORDS.includes(tok.lower)) {
      if (this.repeatDepth === 0) {
        throw new LogoSyntaxError(`„${tok.text}” ma wartość tylko wewnątrz powtórz — to numer bieżącego powtórzenia.`, tok);
      }
      return { k: "repcount" };
    }
    if (tok.kind === "word" || tok.kind === "param") {
      if (this.isValueName(tok.lower)) return { k: "var", name: tok.lower, tok };
      throw new LogoSyntaxError(
        `Nieznana nazwa „${tok.text}”. Zmienną tworzy się poleceniem niech, np. niech ${tok.lower} 10.`,
        tok,
      );
    }
    if (tok.kind === "lparen") {
      const e = this.parseExpr();
      const close = this.next();
      if (close.kind !== "rparen") throw new LogoSyntaxError("Nawias „(” nie został zamknięty.", tok);
      return e;
    }
    throw new LogoSyntaxError(`Oczekiwano liczby, a znaleziono „${tok.text}”.`, tok);
  }
}

function hasNames(e: Expr): boolean {
  switch (e.k) {
    case "num":
      return false;
    case "var":
    case "repcount":
      return true;
    case "neg":
      return hasNames(e.e);
    case "bin":
      return hasNames(e.l) || hasNames(e.r);
  }
}

export function parse(source: string, mode: Mode): Program {
  return new Parser(source, tokenize(source), mode).parseProgram();
}

