import type { Expr } from "./ast";

/** An evaluation failure; the caller reports it at the argument's first token. */
export class EvalError extends Error {}

export function formatNumber(v: number): string {
  if (Number.isInteger(v)) return String(v);
  return String(Number(v.toFixed(6)));
}

export function arith(op: "+" | "-" | "*" | "/", l: number, r: number): number {
  let v: number;
  switch (op) {
    case "+":
      v = l + r;
      break;
    case "-":
      v = l - r;
      break;
    case "*":
      v = l * r;
      break;
    case "/":
      if (r === 0) throw new EvalError("Dzielenie przez zero.");
      v = l / r;
      break;
  }
  if (!Number.isFinite(v)) throw new EvalError("Wynik działania jest zbyt duży, by go policzyć.");
  return v;
}

/** Evaluates an expression with no names in it. */
export function evalConst(e: Expr): number {
  switch (e.k) {
    case "num":
      return e.v;
    case "neg":
      return -evalConst(e.e);
    case "bin":
      return arith(e.op, evalConst(e.l), evalConst(e.r));
    default:
      throw new EvalError("Wyrażenie zależy od nazw.");
  }
}

export function widthProblem(v: number): string | null {
  if (Number.isInteger(v) && v >= 1 && v <= 12) return null;
  return `Grubość musi być liczbą całkowitą od 1 do 12, a wychodzi ${formatNumber(v)}.`;
}

export function countProblem(v: number): string | null {
  if (Number.isInteger(v) && v >= 0 && v <= 10000) return null;
  return `Liczba powtórzeń musi być liczbą całkowitą od 0 do 10 000, a wychodzi ${formatNumber(v)}.`;
}
