describe("interpreter: 3D turtle", () => {
  test("gora 90 heads along the former up vector (+Z); dol pitches the other way", () => {
    expect([ends("gora 90 np 10", "3d"), ends("dół 90 np 5", "3d")]).toEqual([[[0, 0, 10]], [[0, 0, -5]]]);
  });

  test("pp 90: up becomes the former right, right becomes the former down; heading unchanged", () => {
    expect([ends("pp 90 np 3 gora 90 np 10", "3d"), ends("pp 90 pw 90 np 10", "3d"), ends("pl 90 gora 90 np 5", "3d")]).toEqual([
      [
        [0, 3, 0],
        [10, 3, 0],
      ],
      [[0, 0, -10]],
      [[-5, 0, 0]],
    ]);
  });

  test("pitch and roll commands are parse-time errors in 2D mode", () => {
    for (const cmd of ["gora", "dol", "pp", "pl", "pitchup", "rollleft"]) {
      const r = run(`np 10 ${cmd} 90`, "2d");
      expect(r.segments).toEqual([]);
      expect(r.error).toMatchObject({ line: 1, column: 7 });
    }
  });

  test("flat programs draw identical coordinates in 2D and 3D", () => {
    for (const id of ["kwadrat", "gwiazda", "rozeta", "spirala", "wielokaty", "drzewo", "sniezynka"]) {
      expect(run(example(id), "3d")).toEqual(run(example(id), "2d"));
    }
  });

  test("dom draws back to the origin when the pen is down and resets orientation", () => {
    const segs = run("np 10 pw 90 gora 30 np 10 dom np 5", "3d").segments;
    expect(segs.length).toBe(4);
    expect(segs[2].to).toEqual([0, 0, 0]);
    expect(segs[3].to).toEqual([0, 5, 0]);
    expect(run("pod np 10 dom opu np 1", "2d").segments).toEqual([{ from: [0, 0, 0], to: [0, 1, 0], color: "#16866a", width: 3 }]);
  });
});
