describe("interpreter: 3D standard programs", () => {
  test("Schody: six steps climbing to (0, 210, 120)", () => {
    const s = run(example("schody"), "3d").segments;
    expect(s.length).toBe(12);
    expect(s[11].to).toEqual([0, 210, 120]);
  });

  test("Sześcian: 17 strokes covering exactly the 12 edges of a 100-unit cube", () => {
    const s = run(example("szescian"), "3d").segments;
    expect(s.length).toBe(17);
    const key = (a: number[], b: number[]) => [a.join(","), b.join(",")].sort().join("|");
    const edges = new Set(s.map((x) => key(x.from, x.to)));
    expect(edges.size).toBe(12);
    for (const x of s) {
      expect([...x.from, ...x.to].every((c) => c === 0 || c === 100)).toBe(true);
      expect(len(x)).toBe(100);
    }
  });

  test("Pierścień: a closed ring of 36 strokes tilted 30° about the X axis", () => {
    const s = run(example("pierscien"), "3d").segments;
    expect(s.length).toBe(36);
    for (const x of s) expect(x.to[2]).toBeCloseTo(x.to[1] * Math.tan(Math.PI / 6), 6);
    expect(s[35].to.map((c) => Math.abs(c) < 1e-6)).toEqual([true, true, true]);
  });

  test("Kula: twelve closed circles in alternating colours", () => {
    const s = run(example("kula"), "3d").segments;
    expect(s.length).toBe(432);
    expect([s[0].color, s[36].color, s[72].color]).toEqual(["#16866a", "#2b6fb3", "#16866a"]);
    for (let c = 1; c <= 12; c++) expect(s[c * 36 - 1].to.map((v) => Math.abs(v) < 1e-6)).toEqual([true, true, true]);
  });

  test("Helisa: one turn every 24 steps, rising 1.5 per step", () => {
    const s = run(example("helisa"), "3d").segments;
    expect(s.length).toBe(240);
    s[47].to.forEach((v, i) => expect(v).toBeCloseTo([0, 0, 36][i], 6));
    expect(s[239].to[2]).toBeCloseTo(180, 6);
  });

  test("Drzewo 3D: 121 branches, the trunk straight up, the 4 thickest brown", () => {
    const s = run(example("drzewo3d"), "3d").segments;
    expect(s.length).toBe(121);
    expect(s[0]).toMatchObject({ from: [0, 0, 0], to: [0, 0, 70], color: "#6b4f2a", width: 3 });
    expect(s.filter((x) => x.color === "#6b4f2a").length).toBe(4);
  });

  test("every standard program runs without error in its own mode", () => {
    const { EXAMPLES } = require("../src/app/examples");
    for (const e of EXAMPLES) expect([e.id, run(e.source, e.mode).error]).toEqual([e.id, null]);
  });
});
