cat >> test/interpreter.test.ts <<'EOF'

describe("interpreter: limits", () => {
  test("10,000 executed operations: each command plus one per finished iteration", () => {
    expect(run("powtorz 4999 [np 1]", "2d").error).toBeNull();
    const r = run("powtorz 5000 [np 1]", "2d");
    expect(r.error!.message).toContain("10 000");
    expect(r.segments.length).toBe(5000);
  });

  test("calls and conditional bodies count one more when they finish", () => {
    expect(run("oto a\njuż\npowtorz 3333 [a]", "2d").error).toBeNull();
    expect(run("oto a\njuż\npowtorz 3334 [a]", "2d").error).not.toBeNull();
    expect(run("powtorz 3333 [jeśli 1 = 1 []]", "2d").error).toBeNull();
    expect(run("powtorz 3334 [jeśli 1 = 1 []]", "2d").error).not.toBeNull();
    expect(run("powtorz 4999 [jeśli 1 = 2 [np 1]]", "2d").error).toBeNull();
    expect(run("niech i 0\npowtorz 3333 [niech i i + 1]", "2d").error).toBeNull();
    expect(run("niech i 0\npowtorz 3334 [niech i i + 1]", "2d").error).not.toBeNull();
  });

  test("at most 32 active call and repeat frames; the 33rd is an error that keeps the drawing", () => {
    const r = run("oto r ma: n\n  np 1 r n + 1\njuż\nr 1", "2d");
    expect(r.segments.length).toBe(32);
    expect(r.error).toMatchObject({ line: 2, column: 8 });
  });

  test("bracket nesting deeper than 32 is a parse-time error at the 33rd [", () => {
    const nest = (n: number) => "powtorz 1 [".repeat(n) + "np 1" + "]".repeat(n);
    expect(run(nest(32), "2d").error).toBeNull();
    expect(err(nest(33))).toEqual({ line: 1, column: 32 * 11 + 9 });
  });

  test("coordinates must stay within ±100,000", () => {
    expect(run("np 100000", "2d").error).toBeNull();
    const r = run("np 10\npod np 99991", "2d");
    expect(r.segments.length).toBe(1);
    expect(r.error).toMatchObject({ line: 2, column: 5 });
  });

  test("a program longer than 50,000 characters is rejected", () => {
    const r = run("np 1\n;" + "x".repeat(50_000), "2d");
    expect(r.segments).toEqual([]);
    expect(r.error!.message).toContain("50 000");
  });

  test("more than 10,000 tokens is rejected at the 10,001st", () => {
    const r = run("pw 0 ".repeat(5001), "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 1, column: 25001 });
  });
});
EOF
