import { describe, expect, test } from "bun:test";
import { createController, type Scheduler } from "../src/app/controller";
import { run } from "../src/lang";

/** A frame clock the test advances by hand. */
function manualClock() {
  let t = 0;
  let queue: ((now: number) => void)[] = [];
  const scheduler: Scheduler = {
    request(cb) {
      queue.push(cb);
      return queue.length;
    },
    cancel() {
      queue = [];
    },
  };
  return {
    scheduler,
    /** Advances time by `ms`, delivering one frame. */
    frame(ms = 16) {
      t += ms;
      const q = queue;
      queue = [];
      q.forEach((cb) => cb(t));
    },
    frames(n: number, ms = 16) {
      for (let i = 0; i < n; i++) this.frame(ms);
    },
  };
}

const SRC = "np 10\npw 90\nnp 20";

describe("controller: stepping", () => {
  test("each step executes one command and reports where it was written", () => {
    const c = createController({ scheduler: manualClock().scheduler });
    const seen: [string, number | undefined, number][] = [];
    for (let i = 0; i < 3; i++) {
      c.step(SRC, "2d");
      seen.push([c.state.status, c.state.current?.line, c.state.segments.length]);
    }
    expect(seen).toEqual([
      ["paused", 1, 1],
      ["paused", 2, 1],
      ["done", 3, 2],
    ]);
  });
});
