export interface Position {
  line: number;
  column: number;
}

/** A program being executed one statement at a time. */
export interface Execution {
  /** The parse-time or run-time error, once one has happened. */
  readonly error: LogoError | null;
  readonly done: boolean;
  /** Position of the statement that the next step() will execute. */
  readonly pending: Position | null;
  /** Executes the pending statement; returns its position, or null when finished. */
  step(): Position | null;
  /** Strokes kept so far, in drawing order (raw coordinates). */
  readonly segments: readonly Segment[];
  readonly turtle: Readonly<TurtleState>;
  readonly ops: number;
  /** The public result: cleaned coordinates plus the error. */
  result(): RunResult;
}

export function createExecution(source: string, mode: Mode): Execution {
  let program;
  try {
    program = parse(source, mode);
  } catch (e) {
    const error = toLogoError(e);
    return {
      error,
      done: true,
      pending: null,
      step: () => null,
      segments: [],
      turtle: initialTurtle(),
      ops: 0,
      result: () => ({ segments: [], error }),
    };
  }
  const machine = new Machine(program);
  const gen = machine.execute();
  let error: LogoError | null = null;
  let pending: Position | null = null;
  let done = false;
  const advance = () => {
    try {
      const r = gen.next();
      if (r.done) {
        done = true;
        pending = null;
      } else {
        pending = { line: r.value.tok.line, column: r.value.tok.column };
      }
    } catch (e) {
      error = toLogoError(e);
      done = true;
      pending = null;
    }
  };
  advance();
  return {
    get error() {
      return error;
    },
    get done() {
      return done;
    },
    get pending() {
      return pending;
    },
    step() {
      if (done) return null;
      const executed = pending;
      advance();
      return executed;
    },
    get segments() {
      return machine.segments;
    },
    get turtle() {
      return machine.turtle;
    },
    get ops() {
      return machine.ops;
    },
    result: () => ({ segments: publicSegments(machine.segments), error }),
  };
}
