import { createExecution, type Execution, type LogoError, type Mode, type Position, type RunResult, type Segment, type TurtleState } from "../lang";
import { initialTurtle } from "../lang/turtle";

export type Status = "idle" | "running" | "paused" | "done" | "error";

/** Frame scheduling, injected so tests can drive time by hand. */
export interface Scheduler {
  request(cb: (now: number) => void): number;
  cancel(handle: number): void;
}

export interface ControllerState {
  status: Status;
  mode: Mode;
  segments: readonly Segment[];
  turtle: Readonly<TurtleState>;
  /** The statement executed most recently. */
  current: Position | null;
  error: LogoError | null;
}

export interface Controller {
  readonly state: ControllerState;
  /** Speed levels run from 1 (slowest) to maxSpeed (whole program at once). */
  readonly maxSpeed: number;
  readonly speed: number;
  setSpeed(level: number): void;
  /** Starts the program from the beginning, animated. */
  run(source: string, mode: Mode): void;
  /** Executes one statement, starting the program if none is active. */
  step(source: string, mode: Mode): void;
  result(): RunResult;
}

/** Statements per second for each speed level; the last level is "at once". */
const RATES = [2, 6, 20, 80, 400, Infinity];
/** Upper bound of statements per frame, so even "at once" never freezes the page. */
const FRAME_BUDGET = 4000;

export function createController(opts: { scheduler: Scheduler }): Controller {
  const { scheduler } = opts;
  let exec: Execution | null = null;
  let speed = 3;
  let handle = 0;
  let lastTime: number | null = null;
  let budget = 0;

  const state: ControllerState = {
    status: "idle",
    mode: "2d",
    segments: [],
    turtle: initialTurtle(),
    current: null,
    error: null,
  };

  const sync = () => {
    if (!exec) return;
    state.segments = exec.segments;
    state.turtle = exec.turtle;
    state.error = exec.error;
    if (exec.error) state.status = "error";
    else if (exec.done) state.status = "done";
  };

  const stepOnce = () => {
    const at = exec!.step();
    if (at) state.current = at;
  };

  const start = (source: string, mode: Mode) => {
    scheduler.cancel(handle);
    exec = createExecution(source, mode);
    state.mode = mode;
    state.current = null;
    lastTime = null;
    budget = 0;
  };

  const frame = (now: number) => {
    if (!exec || state.status !== "running") return;
    const rate = RATES[speed - 1];
    let n: number;
    if (lastTime === null) {
      n = rate === Infinity ? FRAME_BUDGET : 1;
    } else {
      budget += rate === Infinity ? FRAME_BUDGET : ((now - lastTime) * rate) / 1000;
      n = Math.min(FRAME_BUDGET, Math.floor(budget));
      budget -= n;
    }
    lastTime = now;
    for (let i = 0; i < n && !exec.done; i++) stepOnce();
    sync();
    if (state.status === "running") handle = scheduler.request(frame);
  };

  return {
    state,
    maxSpeed: RATES.length,
    get speed() {
      return speed;
    },
    setSpeed(level) {
      speed = Math.max(1, Math.min(RATES.length, Math.round(level)));
    },
    run(source, mode) {
      start(source, mode);
      state.status = "running";
      sync();
      if (state.status === "running") handle = scheduler.request(frame);
    },
    step(source, mode) {
      if (!exec || state.status === "done" || state.status === "error" || state.status === "idle") start(source, mode);
      scheduler.cancel(handle);
      state.status = "paused";
      stepOnce();
      sync();
    },
    result() {
      return exec ? exec.result() : { segments: [], error: null };
    },
  };
}

