describe("controller: pause, resume, reset", () => {
  const LONG = "powtorz 100 [np 1 pw 3]";

  test("pause freezes the drawing across frames; resume continues to the same end", () => {
    const clock = manualClock();
    const c = createController({ scheduler: clock.scheduler });
    c.setSpeed(3);
    c.run(LONG, "2d");
    clock.frames(5, 100);
    c.pause();
    const frozen = c.state.segments.length;
    clock.frames(20, 100);
    expect([c.state.status, c.state.segments.length]).toEqual(["paused", frozen]);
    c.resume();
    clock.frames(200, 100);
    expect(c.state.status).toBe("done");
    expect(c.result()).toEqual(run(LONG, "2d"));
  });

  test("step while running pauses and advances exactly one statement", () => {
    const clock = manualClock();
    const c = createController({ scheduler: clock.scheduler });
    c.setSpeed(2);
    c.run(LONG, "2d");
    clock.frames(3, 200);
    const before = c.state.current!;
    c.step(LONG, "2d");
    expect(c.state.status).toBe("paused");
    expect(c.state.current).not.toEqual(before);
    const after = c.state.segments.length;
    clock.frames(10, 200);
    expect(c.state.segments.length).toBe(after);
  });

  test("reset clears the drawing and puts the turtle back at the start", () => {
    const clock = manualClock();
    const c = createController({ scheduler: clock.scheduler });
    c.run("pw 45 np 50", "2d");
    clock.frames(10, 1000);
    c.reset();
    expect(c.state).toMatchObject({ status: "idle", segments: [], current: null, error: null });
    expect(c.state.turtle.pos).toEqual([0, 0, 0]);
    expect(c.state.turtle.heading).toEqual([0, 1, 0]);
  });
});
EOF
