  test("a parse error draws nothing and reports its position", () => {
    const clock = manualClock();
    const c = createController({ scheduler: clock.scheduler });
    c.run("np 10\nnp )", "2d");
    clock.frames(5);
    expect(c.state).toMatchObject({ status: "error", segments: [], error: { line: 2, column: 4 } });
  });

