    const clock = manualClock();
    const c = createController({ scheduler: clock.scheduler });
    c.setSpeed(c.maxSpeed);
    c.run("np 10\nniech z 0\nnp 1 / z", "2d");
    clock.frames(3);
    expect(c.state.status).toBe("error");
    expect(c.state.segments.length).toBe(1);
    expect(c.state.error).toMatchObject({ line: 3, column: 4 });
  });

