    const clock = manualClock();
    const c = createController({ scheduler: clock.scheduler });
    c.setSpeed(2);
    c.run("powtorz 50 [np 2 pw 7]", "2d");
    clock.frames(4, 250);
    const drawn = c.state.segments.length;
    c.sourceEdited();
    clock.frames(10, 250);
    expect(c.state).toMatchObject({ status: "stopped", current: null });
    expect(c.state.segments.length).toBe(drawn);
