    const statuses: string[] = [];
    c.subscribe((s) => statuses.push(s.status));
    c.step("np 1 np 2", "2d");
    c.step("np 1 np 2", "2d");
    c.reset();
    expect(statuses).toEqual(["paused", "done", "idle"]);
