    expect([b.mode, b.source]).toEqual(["3d", "gora 45 np 10"]);
    b.setMode("2d");
    expect(b.source).toBe("np 10");
  });

  test("a first visit opens a starter program in 2D", () => {
    const w = createWorkspace(memoryStorage());
    expect(w.mode).toBe("2d");
