    const storage = memoryStorage();
    const w = createWorkspace(storage);
    w.edit("np 5 pw 5");
    w.load(findExample("kwadrat")!.source, "2d");
    const after = createWorkspace(storage);
    expect(after.stash).toEqual({ source: "np 5 pw 5", mode: "2d" });
  });
});
