import type { Mode } from "../lang";
import { findExample } from "./examples";

export interface KeyValueStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export interface Stash {
  source: string;
  mode: Mode;
}

export interface Workspace {
  readonly mode: Mode;
  /** The draft of the current mode. */
  readonly source: string;
  /** The most recently replaced draft, if any. */
  readonly stash: Stash | null;
  setMode(mode: Mode): void;
  /** The learner typed: saves the draft of the current mode. */
  edit(source: string): void;
  /**
   * Replaces the draft of `mode` (and switches to it). A draft with the
   * learner's own changes is kept in the stash first.
   */
  load(source: string, mode: Mode): { stashed: boolean };
  /** Brings the stashed draft back, stashing the one it replaces. */
  restoreStash(): void;
}

const PREFIX = "logomocja:";
const STARTERS: Record<Mode, string> = { "2d": "kwadrat", "3d": "schody" };

/** Local storage can be full or blocked (private mode); the app keeps working in memory. */
function safe(store: KeyValueStore): KeyValueStore {
  const memory = new Map<string, string>();
  return {
    getItem(k) {
      try {
        return store.getItem(k) ?? memory.get(k) ?? null;
      } catch {
        return memory.get(k) ?? null;
      }
    },
    setItem(k, v) {
      memory.set(k, v);
      try {
        store.setItem(k, v);
      } catch {
        /* keep the in-memory copy */
      }
    },
    removeItem(k) {
      memory.delete(k);
      try {
        store.removeItem(k);
      } catch {
        /* ignore */
      }
    },
  };
}

export function createWorkspace(backing: KeyValueStore): Workspace {
  const store = safe(backing);
  const get = (k: string) => store.getItem(PREFIX + k);
  const set = (k: string, v: string) => store.setItem(PREFIX + k, v);

  const draft = (m: Mode): string => {
    const saved = get(`draft:${m}`);
    return saved ?? findExample(STARTERS[m])!.source;
  };
  /** Content last put there by the app (starter, example, link); edits make the draft "own work". */
  const pristine = (m: Mode): string => get(`pristine:${m}`) ?? findExample(STARTERS[m])!.source;
  const isOwnWork = (m: Mode) => {
    const d = draft(m);
    return d.trim() !== "" && d !== pristine(m);
  };

  let mode: Mode = get("mode") === "3d" ? "3d" : "2d";

  const readStash = (): Stash | null => {
    try {
      const raw = get("stash");
      if (!raw) return null;
      const s = JSON.parse(raw);
      if (typeof s.source === "string" && (s.mode === "2d" || s.mode === "3d")) return { source: s.source, mode: s.mode };
    } catch {
      /* corrupted entry */
    }
    return null;
  };

  const ws: Workspace = {
    get mode() {
      return mode;
    },
    get source() {
      return draft(mode);
    },
    get stash() {
      return readStash();
    },
    setMode(m) {
      mode = m;
      set("mode", m);
    },
    edit(source) {
      set(`draft:${mode}`, source);
    },
    load(source, m) {
      const stashed = isOwnWork(m) && draft(m) !== source;
      if (stashed) set("stash", JSON.stringify({ source: draft(m), mode: m }));
      set(`draft:${m}`, source);
      set(`pristine:${m}`, source);
      ws.setMode(m);
      return { stashed };
    },
    restoreStash() {
      const s = readStash();
      if (!s) return;
      const replaced = isOwnWork(s.mode) ? { source: draft(s.mode), mode: s.mode } : null;
      set(`draft:${s.mode}`, s.source);
      if (replaced) set("stash", JSON.stringify(replaced));
      else store.removeItem(PREFIX + "stash");
      ws.setMode(s.mode);
    },
  };
  return ws;
}
EOF
