import type { Mode } from "../lang";

/** Hash route that carries a shared program: #/program?tryb=2d&kod=<base64url UTF-8>. */
const ROUTE = "#/program";

function toBase64Url(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let bin = "";
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function fromBase64Url(code: string): string | null {
  if (!/^[A-Za-z0-9_-]*$/.test(code)) return null;
  try {
    const bin = atob(code.replace(/-/g, "+").replace(/_/g, "/"));
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    return null;
  }
}

export function encodePermalink(source: string, mode: Mode): string {
  return `${ROUTE}?tryb=${mode}&kod=${toBase64Url(source)}`;
}

export function decodePermalink(hash: string): { source: string; mode: Mode } | null {
  if (!hash.startsWith(ROUTE + "?")) return null;
  const params = new URLSearchParams(hash.slice(ROUTE.length + 1));
  const mode = params.get("tryb");
  const code = params.get("kod");
  if ((mode !== "2d" && mode !== "3d") || code === null) return null;
  const source = fromBase64Url(code);
  return source === null ? null : { source, mode };
}
