import { describe, expect, test } from "bun:test";
import { CHALLENGES, checkChallenge, createProgress } from "../src/app/challenges";

const byId = (id: string) => CHALLENGES.find((c) => c.id === id)!;

function memoryStorage() {
  const m = new Map<string, string>();
  return {
    getItem: (k: string) => m.get(k) ?? null,
    setItem: (k: string, v: string) => void m.set(k, v),
    removeItem: (k: string) => void m.delete(k),
  };
}

/** Solutions written independently of the shipped reference programs. */
const SOLUTIONS: Record<string, string> = {
  trojkat: "np 100 pw 120 np 100 pw 120 np 100",
  schodki: "powtorz 3 [\n  np 30\n  prawo 90\n  np 30\n  lewo 90\n]",
  szesciokat: "oto bok\n  np 30 np 30\n  pw 60\njuż\npowtorz 6 [bok]",
  przerywana: "np 20 pod np 10 opu np 20 pod np 10 opu np 20 pod np 10 opu np 20 pod np 10 opu np 20",
  kwadraty: "niech b 40\npowtorz 3 [\n  powtorz 4 [np b pw 90]\n  niech b b + 20\n]",
  dwukolorowy: 'powtorz 4 [\n  jeżeli nrpowt = 1 [kolor "#16866a"] [jeżeli nrpowt = 3 [kolor "#16866a"] [kolor "#c1763d"]]\n  np 80 pw 90\n]',
  pionowy: "gora 90 np 80 dol 90 np 80 dol 90 np 80 gora 90 ws 80",
  slupki: "pw 90\nniech h 30\npowtorz 3 [\n  gora 90 np h pod ws h opu dol 90\n  pod np 40 opu\n  niech h h + 30\n]",
};

describe("challenges", () => {
  test("there are at least five, each with a statement, a mode and a target drawing", () => {
    expect(CHALLENGES.length).toBeGreaterThanOrEqual(5);
    for (const c of CHALLENGES) {
      expect(c.title.length).toBeGreaterThan(0);
      expect(c.task.length).toBeGreaterThan(0);
      expect(["2d", "3d"]).toContain(c.mode);
    }
  });

  test("an independently written correct solution passes every challenge", () => {
    for (const c of CHALLENGES) expect([c.id, checkChallenge(c, SOLUTIONS[c.id]).passed]).toEqual([c.id, true]);
  });

  test("a shape of the wrong size fails and says where the drawing falls short", () => {
    const r = checkChallenge(byId("trojkat"), "powtorz 3 [np 80 pw 120]");
    expect(r.passed).toBe(false);
    expect(r.reason).toContain("Brakuje");
  });

  test("extra lines fail and are pointed out", () => {
    const r = checkChallenge(byId("trojkat"), "powtorz 3 [np 100 pw 120] pw 90 np 30");
    expect(r.passed).toBe(false);
    expect(r.reason).toContain("nie ma we wzorze");
  });

  test("a program with an error fails with the error's message", () => {
    const r = checkChallenge(byId("trojkat"), "powtorz 3 [np 100 pw 120");
    expect(r.passed).toBe(false);
    expect(r.reason).toContain("Nawias");
  });

  test("when a challenge asks for colours, the right shape in the wrong colours fails", () => {
    const r = checkChallenge(byId("dwukolorowy"), "powtorz 4 [np 80 pw 90]");
    expect(r.passed).toBe(false);
    expect(r.reason).toContain("kolor");
  });

  test("progress is remembered across reloads", () => {
    const storage = memoryStorage();
    const p = createProgress(storage);
    p.record("trojkat", true, SOLUTIONS.trojkat);
    p.saveSource("schodki", "np 30");
    const again = createProgress(storage);
    expect(again.get("trojkat")).toEqual({ passed: true, source: SOLUTIONS.trojkat });
    expect(again.get("schodki")).toEqual({ passed: false, source: "np 30" });
    expect(again.passedCount).toBe(1);
  });
});
EOF
