import { run, type Mode, type Segment, type Vec3 } from "../lang";
import type { KeyValueStore } from "./workspace";

export interface Challenge {
  id: string;
  title: string;
  mode: Mode;
  /** What to draw, in the learner's words. */
  task: string;
  /** A nudge for learners who are stuck. */
  hint: string;
  /** Program the learner starts from. */
  starter: string;
  /** The reference drawing comes from this program. */
  solution: string;
  /** Whether stroke colours must match as well as the shape. */
  checkColor?: boolean;
}

export const CHALLENGES: Challenge[] = [
  {
    id: "trojkat",
    title: "Trójkąt",
    mode: "2d",
    task: "Narysuj trójkąt równoboczny o boku 100. Zacznij od boku w górę i skręcaj w prawo.",
    hint: "Trzy boki, trzy skręty. Po każdym boku żółw obraca się o 120 stopni, bo 3 × 120 = 360.",
    starter: "; Trójkąt równoboczny o boku 100\n",
    solution: "powtorz 3 [np 100 pw 120]",
  },
  {
    id: "schodki",
    title: "Schodki",
    mode: "2d",
    task: "Narysuj trzy schodki w prawo: każdy stopień ma 30 wysokości i 30 szerokości. Pierwszy krok idzie w górę.",
    hint: "Jeden stopień to: w górę, w prawo i obrót z powrotem w górę. Powtórz go trzy razy.",
    starter: "; Trzy schodki po 30\n",
    solution: "powtorz 3 [np 30 pw 90 np 30 lw 90]",
  },
  {
    id: "szesciokat",
    title: "Sześciokąt",
    mode: "2d",
    task: "Narysuj sześciokąt foremny o boku 60, skręcając w prawo.",
    hint: "Kąt skrętu to 360 podzielone przez liczbę boków.",
    starter: "; Sześciokąt o boku 60\n",
    solution: "powtorz 6 [np 60 pw 60]",
  },
  {
    id: "przerywana",
    title: "Linia przerywana",
    mode: "2d",
    task: "Narysuj w górę pięć kresek po 20, z przerwami po 10 między nimi.",
    hint: "Podnieś pisak poleceniem pod, przesuń żółwia, opuść pisak poleceniem opu.",
    starter: "; Pięć kresek po 20, przerwy po 10\n",
    solution: "powtorz 5 [np 20 pod np 10 opu]",
  },
  {
    id: "kwadraty",
    title: "Trzy kwadraty",
    mode: "2d",
    task: "Narysuj trzy kwadraty o bokach 40, 60 i 80, wszystkie z jednym wspólnym rogiem w punkcie startu. Boki w górę i w prawo.",
    hint: "Napisz procedurę z parametrem: oto kwadrat ma: bok … już, a potem wywołaj ją trzy razy.",
    starter: "; Trzy kwadraty: 40, 60 i 80\n",
    solution: "oto kw ma: b\n  powtorz 4 [np b pw 90]\njuż\nkw 40 kw 60 kw 80",
  },
  {
    id: "dwukolorowy",
    title: "Dwukolorowy kwadrat",
    mode: "2d",
    task: 'Narysuj kwadrat o boku 80, w którym boki są na zmianę zielone ("#16866a") i rude ("#c1763d"). Pierwszy bok, w górę, jest zielony.',
    hint: "Zmieniaj kolor przed każdym bokiem. Pomoże powtórz 2 [ … ] z dwoma bokami w środku.",
    starter: '; Boki na zmianę: "#16866a" i "#c1763d"\n',
    solution: 'powtorz 2 [kolor "#16866a" np 80 pw 90 kolor "#c1763d" np 80 pw 90]',
    checkColor: true,
