    return { passed: false, reason: `Narysowano linię w okolicy punktu ${where(extra.point, c.mode)}, a takiej nie ma we wzorze.` };
  }
  if (c.checkColor) {
    const wrong = uncovered(target, segments, true);
    if (wrong) {
      return {
        passed: false,
        reason: `Kształt się zgadza, ale w okolicy punktu ${where(wrong.point, c.mode)} kolor powinien być ${wrong.seg.color}.`,
      };
    }
  }
  return { passed: true, reason: "Brawo! Rysunek zgadza się ze wzorem." };
}

export interface ChallengeRecord {
  passed: boolean;
  source?: string;
}

export interface Progress {
  get(id: string): ChallengeRecord;
  /** Records a check; a challenge once passed stays passed. */
  record(id: string, passed: boolean, source: string): void;
  saveSource(id: string, source: string): void;
  readonly passedCount: number;
}

const KEY = "logomocja:challenges";

export function createProgress(store: KeyValueStore): Progress {
  let data: Record<string, ChallengeRecord> = {};
  try {
    const raw = store.getItem(KEY);
    if (raw) data = JSON.parse(raw) ?? {};
  } catch {
    data = {};
  }
  const save = () => {
    try {
      store.setItem(KEY, JSON.stringify(data));
    } catch {
      /* storage full or blocked: keep progress for this visit */
    }
  };
  return {
    get(id) {
      const r = data[id];
      return r ? { passed: !!r.passed, ...(r.source !== undefined ? { source: r.source } : {}) } : { passed: false };
    },
    record(id, passed, source) {
      data[id] = { passed: passed || !!data[id]?.passed, source };
      save();
    },
    saveSource(id, source) {
      data[id] = { passed: !!data[id]?.passed, source };
      save();
    },
    get passedCount() {
      return CHALLENGES.filter((c) => data[c.id]?.passed).length;
    },
  };
}

