import { GlobalRegistrator } from "@happy-dom/global-registrator";
GlobalRegistrator.register({ url: "http://localhost/" });

import { beforeEach, describe, expect, test } from "bun:test";
import { run } from "../src/lang";

const { mountApp } = await import("../src/app/app");

function fresh(keepStorage = false) {
  if (!keepStorage) localStorage.clear();
  location.hash = "";
  document.body.innerHTML = '<div id="app"></div>';
  return mountApp(document.getElementById("app")!, { storage: localStorage });
}

const editor = () => document.querySelector<HTMLTextAreaElement>('textarea[aria-label="Program"]')!;
const modeRadio = (m: string) => document.querySelector<HTMLElement>(`[role="radio"][data-mode="${m}"]`)!;

describe("app: window.logomocja.open", () => {
  beforeEach(() => localStorage.clear());

  test("loads the source into the editor in the given mode and resolves with the interpreter's result", async () => {
    const api = fresh();
    const src = "gora 30\npowtorz 36 [np 12 pw 10]";
    const r = await api.open(src, "3d");
    expect(r).toEqual(run(src, "3d"));
    expect(editor().value).toBe(src);
    expect(modeRadio("3d").getAttribute("aria-checked")).toBe("true");
  });
});
EOF
timeout 20 bun test test/app.test.ts 2>&1 | grep -E "pass|fail|Expected|Received|error:" | head -3

