:root {
  color-scheme: light;

  --font-ui: "Fira Sans", "Segoe UI", system-ui, sans-serif;
  --font-code: "Fira Mono", ui-monospace, "Cascadia Mono", Menlo, monospace;

  /* Shell */
  --band: #17223b;
  --band-raised: #22304f;
  --band-rule: #2e3d5f;
  --on-band: #f2f4f8;
  --on-band-muted: #b3bdd0;

  /* Ground and surfaces */
  --ground: #eef1f5;
  --surface: #ffffff;
  --surface-sunk: #f6f8fa;
  --surface-hover: #e7ebf1;
  --rule: #d3d9e3;
  --rule-strong: #aeb8c7;

  /* Ink */
  --ink: #162033;
  --ink-2: #47526a;
  --ink-3: #636e84;
  --ink-inverse: #ffffff;

  /* Lines (modes) */
  --line-2d: #16866a;
  --line-2d-strong: #0f6b54;
  --line-3d: #2b6fb3;
  --line-3d-strong: #1f5a96;
  --line: var(--line-2d);
  --line-strong: var(--line-2d-strong);

  /* You are here — reserved for the executing line and the turtle */
  --here: #f2c230;
  --here-soft: #fff1bd;
  --here-ink: #3d2f00;

  /* States */
  --error: #b83227;
  --error-soft: #fdebe8;
  --error-ink: #8f2117;
  --success: #16866a;
  --success-soft: #e3f4ee;

  /* Drawing paper (stays light in both themes: pen colours are fixed by the programs) */
  --paper: #fbfcfd;
  --paper-grid: #e7ebf1;
  --paper-grid-major: #d5dbe4;
  --paper-axis: #a8b2c2;
