input.content:
import { COMMANDS, DEFINE_WORDS, END_WORDS, REPCOUNT_WORDS } from "../lang/commands";
import { tokenize, type Token } from "../lang/lexer";

const CONTROL = new Set(["repeat", "if", "ifelse", "let", "stop"]);

export function escapeHtml(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function classOf(t: Token, procs: Set<string>): string {
  switch (t.kind) {
    case "word": {
      if (DEFINE_WORDS.includes(t.lower) || END_WORDS.includes(t.lower)) return "ctl";
      if (REPCOUNT_WORDS.includes(t.lower)) return "name";
      const cmd = COMMANDS.get(t.lower);
      if (cmd) return CONTROL.has(cmd) ? "ctl" : "cmd";
      return procs.has(t.lower) ? "proc" : "name";
    }
    case "param":
      return "name";
    case "label":
      return "ctl";
    case "number":
      return "num";
    case "string":
      return "str";
    case "lbracket":
    case "rbracket":
    case "lparen":
    case "rparen":
      return "br";
