import type { LogoError, Position } from "../lang";
import { codeLines, escapeHtml, highlight, offsetOf } from "./highlight";

export interface EditorApi {
  readonly el: HTMLElement;
  readonly textarea: HTMLTextAreaElement;
  value: string;
  onInput(cb: (value: string) => void): void;
  setError(error: LogoError | null): void;
  /** Marks the executing statement ("you are here"). */
  setCurrent(pos: Position | null): void;
  /** Station fill and inlay counts after a run. */
  setVisits(visits: ReadonlyMap<number, number> | null): void;
  setRouteMode(mode: "2d" | "3d"): void;
  focusAt(line: number, column: number): void;
}

/** Characters that open an indented block. */
const OPENERS = /[[(]\s*$/;

export function createEditor(opts: { describedBy: string }): EditorApi {
  const el = document.createElement("div");
  el.className = "editor";
  el.innerHTML = `
    <div class="editor-gutter" aria-hidden="true"><div class="gutter-inner"></div></div>
    <div class="editor-body">
      <div class="editor-layer">
        <div class="editor-marks"><div class="here-band" hidden></div></div>
        <pre class="editor-hl"><code></code></pre>
        <div class="error-bubble" hidden></div>
      </div>
      <textarea aria-label="Program" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" wrap="off" aria-describedby="${opts.describedBy}"></textarea>
    </div>`;
  const textarea = el.querySelector("textarea")!;
  const gutter = el.querySelector<HTMLElement>(".gutter-inner")!;
  const layer = el.querySelector<HTMLElement>(".editor-layer")!;
  const code = el.querySelector("code")!;
  const hereBand = el.querySelector<HTMLElement>(".here-band")!;
  const bubble = el.querySelector<HTMLElement>(".error-bubble")!;

  let error: LogoError | null = null;
  let current: Position | null = null;
  let visits: ReadonlyMap<number, number> | null = null;
  const listeners: ((v: string) => void)[] = [];

  const metrics = () => {
    const cs = getComputedStyle(textarea);
    const lh = parseFloat(cs.lineHeight) || 22;
    const padTop = parseFloat(cs.paddingTop) || 0;
    const padLeft = parseFloat(cs.paddingLeft) || 0;
    const probe = document.createElement("span");
    probe.textContent = "0000000000";
    probe.style.visibility = "hidden";
    code.appendChild(probe);
    const ch = probe.getBoundingClientRect().width / 10 || 8.4;
    probe.remove();
    return { lh, padTop, padLeft, ch };
  };

  /** Visual column of a 1-based column on a line, with tabs at width 2. */
  const visualColumn = (line: number, column: number) => {
    const text = textarea.value.split("\n")[line - 1] ?? "";
    let v = 0;
    for (let i = 0; i < column - 1 && i < text.length; i++) v = text[i] === "\t" ? v + 2 - (v % 2) : v + 1;
    return v + Math.max(0, column - 1 - text.length);
  };

  const renderGutter = () => {
    const value = textarea.value;
    const count = value.split("\n").length;
    const lines = codeLines(value);
    const first = Math.min(...lines);
    const last = Math.max(...lines);
    let html = "";
    for (let n = 1; n <= count; n++) {
      const classes = ["g-row"];
      if (lines.size && n >= first && n <= last) classes.push("on-route");
      if (n === first) classes.push("route-start");
      if (n === last) classes.push("route-end");
      let station = "";
      if (lines.has(n)) {
        const v = visits?.get(n) ?? 0;
        const state =
          error && error.line === n ? "is-error" : current && current.line === n ? "is-here" : v > 0 ? "is-visited" : "";
        station = `<span class="g-station ${state}"></span>`;
      }
      html += `<div class="${classes.join(" ")}"><span class="g-route">${station}</span><span class="g-num">${n}</span></div>`;
    }
    gutter.innerHTML = html;
  };

  const renderHighlight = () => {
    const value = textarea.value;
    const mark = error ? offsetOf(value, error.line, error.column) : null;
    let html = highlight(value, mark);
    if (visits && visits.size) {
      // Inlay counts at the end of lines that ran more than once.
      const lines = html.split("\n");
      for (const [line, n] of visits) {
        if (n > 1 && lines[line - 1] !== undefined) lines[line - 1] += `<span class="inlay">×${n}</span>`;
      }
      html = lines.join("\n");
    }
    code.innerHTML = html;
  };

  const renderMarks = () => {
    const m = metrics();
    if (current) {
      hereBand.hidden = false;
      hereBand.style.transform = `translateY(${m.padTop + (current.line - 1) * m.lh}px)`;
      hereBand.style.height = `${m.lh}px`;
    } else {
      hereBand.hidden = true;
    }
    if (error) {
      bubble.hidden = false;
      bubble.innerHTML = `<strong>Wiersz ${error.line}, kolumna ${error.column}.</strong> ${escapeHtml(error.message)}`;
      const left = m.padLeft + visualColumn(error.line, error.column) * m.ch;
      bubble.style.top = `${m.padTop + error.line * m.lh + 4}px`;
      bubble.style.left = `${Math.max(4, left - 14)}px`;
      bubble.style.setProperty("--arrow", `${Math.min(14, left)}px`);
    } else {
      bubble.hidden = true;
    }
  };

  const syncScroll = () => {
    layer.style.transform = `translate(${-textarea.scrollLeft}px, ${-textarea.scrollTop}px)`;
    gutter.style.transform = `translateY(${-textarea.scrollTop}px)`;
  };

  const renderAll = () => {
    renderHighlight();
    renderGutter();
    renderMarks();
    syncScroll();
  };

  textarea.addEventListener("scroll", syncScroll);
  textarea.addEventListener("input", () => {
    error = null;
    current = null;
    visits = null;
    renderAll();
    listeners.forEach((l) => l(textarea.value));
  });

  /** Insert text keeping the browser's undo history where supported. */
  const insert = (text: string) => {
    textarea.focus();
    const ok = typeof document.execCommand === "function" && document.execCommand("insertText", false, text);
    if (!ok) {
      textarea.setRangeText(text, textarea.selectionStart, textarea.selectionEnd, "end");
      textarea.dispatchEvent(new Event("input", { bubbles: true }));
    }
  };

  textarea.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey && !e.isComposing) {
      const { selectionStart: s, value } = textarea;
      const lineStart = value.lastIndexOf("\n", s - 1) + 1;
      const before = value.slice(lineStart, s);
      const indent = /^[ \t]*/.exec(before)![0] + (OPENERS.test(before) ? "  " : "");
      if (indent) {
        e.preventDefault();
        insert("\n" + indent);
      }
    } else if (e.key === "]" && !e.ctrlKey && !e.metaKey) {
      // Outdent a closing bracket typed on an otherwise blank, indented line.
      const { selectionStart: s, selectionEnd, value } = textarea;
      const lineStart = value.lastIndexOf("\n", s - 1) + 1;
      const before = value.slice(lineStart, s);
      if (s === selectionEnd && /^ {2,}$/.test(before)) {
        e.preventDefault();
        textarea.setSelectionRange(s - 2, s);
        insert("]");
      }
    }
  });

  if (typeof ResizeObserver !== "undefined") new ResizeObserver(() => renderMarks()).observe(textarea);
  document.fonts?.ready.then(() => renderMarks());

  const api: EditorApi = {
    el,
    textarea,
    get value() {
      return textarea.value;
    },
    set value(v: string) {
      textarea.value = v;
      error = null;
      current = null;
      visits = null;
      renderAll();
    },
    onInput(cb) {
      listeners.push(cb);
    },
    setError(e) {
      error = e;
      textarea.setAttribute("aria-invalid", e ? "true" : "false");
      renderAll();
    },
    setCurrent(pos) {
      if (pos?.line === current?.line && pos?.column === current?.column) return;
      const lineChanged = pos?.line !== current?.line;
      current = pos;
      if (lineChanged) renderGutter();
      renderMarks();
      if (pos) {
        const m = metrics();
        const top = m.padTop + (pos.line - 1) * m.lh;
        if (top < textarea.scrollTop || top + m.lh > textarea.scrollTop + textarea.clientHeight) {
          textarea.scrollTop = Math.max(0, top - textarea.clientHeight / 2);
          syncScroll();
        }
      }
    },
    setVisits(v) {
      visits = v && v.size ? new Map(v) : null;
      renderHighlight();
      renderGutter();
    },
    setRouteMode(mode) {
      el.dataset.mode = mode;
    },
    focusAt(line, column) {
      const off = offsetOf(textarea.value, line, column);
      textarea.focus();
      textarea.setSelectionRange(off, off);
    },
  };
  renderAll();
  return api;
}

