        }
      }
    },
    setVisits(v) {
      visits = v && v.size ? new Map(v) : null;
      renderHighlight();
      renderGutter();
    },
    setRouteMode(mode) {
      el.dataset.mode = mode;
    },
    focusAt(line, column) {
