import type { Segment, TurtleState } from "../lang";

export interface DrawingView {
  readonly el: HTMLElement;
  setSegments(segments: readonly Segment[]): void;
  setTurtle(turtle: Readonly<TurtleState> | null): void;
  setGhost(segments: readonly Segment[] | null): void;
  /** Frames the drawing, the turtle and the origin. */
  fit(): void;
  zoomBy(factor: number): void;
  resetView(): void;
  /** Re-fits only if the turtle or drawing left the visible area (unless the learner moved the view). */
  follow(): void;
  /** Clears the learner's manual pan/zoom so following resumes. */
  release(): void;
  toPNG(): Promise<Blob | null>;
  render(): void;
  /** True when this view can draw at all. */
  readonly available: boolean;
}

interface Theme {
  paper: string;
  grid: string;
  gridMajor: string;
  axis: string;
  ghost: string;
  here: string;
  hereEdge: string;
  label: string;
}

function readTheme(el: HTMLElement): Theme {
  const cs = getComputedStyle(el);
  const v = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    paper: v("--paper", "#fbfcfd"),
    grid: v("--paper-grid", "#e7ebf1"),
    gridMajor: v("--paper-grid-major", "#d5dbe4"),
    axis: v("--paper-axis", "#a8b2c2"),
    ghost: v("--paper-ghost", "#7f8ba0"),
    here: v("--here", "#f2c230"),
    hereEdge: "#17223b",
    label: "#47526a",
  };
}

const MIN_SCALE = 0.01;
const MAX_SCALE = 40;
const FIT_PADDING = 36;

export function createView2D(): DrawingView {
  const el = document.createElement("div");
  el.className = "view2d";
  const canvas = document.createElement("canvas");
  canvas.setAttribute("role", "img");
  canvas.setAttribute("aria-label", "Rysunek żółwia na płaszczyźnie");
  canvas.tabIndex = 0;
  el.appendChild(canvas);
  const ctx = canvas.getContext("2d");

  let segments: readonly Segment[] = [];
  let ghost: readonly Segment[] | null = null;
  let turtle: Readonly<TurtleState> | null = null;
  // View: world point at the canvas centre and pixels per unit.
  let cx = 0;
  let cy = 60;
  let scale = 1;
  let manual = false;
  let width = 0;
  let height = 0;
  let dpr = 1;
  let queued = false;

  const toScreen = (x: number, y: number): [number, number] => [width / 2 + (x - cx) * scale, height / 2 - (y - cy) * scale];
  const toWorld = (sx: number, sy: number): [number, number] => [cx + (sx - width / 2) / scale, cy - (sy - height / 2) / scale];

  const resize = () => {
    const r = el.getBoundingClientRect();
    width = Math.max(1, Math.round(r.width));
    height = Math.max(1, Math.round(r.height));
    dpr = Math.min(window.devicePixelRatio || 1, 3);
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
  };

  const niceStep = (minPx: number) => {
    const raw = minPx / scale;
    const p = Math.pow(10, Math.floor(Math.log10(raw)));
    for (const m of [1, 2, 5, 10]) if (p * m >= raw) return p * m;
    return p * 10;
  };

  const drawGrid = (c: CanvasRenderingContext2D, t: Theme) => {
    const step = niceStep(14);
    const major = step * 5;
    const [x0, y1] = toWorld(0, 0);
    const [x1, y0] = toWorld(width, height);
    c.lineWidth = 1;
    for (const [s, color] of [
      [step, t.grid],
      [major, t.gridMajor],
    ] as const) {
      c.strokeStyle = color;
      c.beginPath();
      for (let x = Math.ceil(x0 / s) * s; x <= x1; x += s) {
        const [sx] = toScreen(x, 0);
        c.moveTo(Math.round(sx) + 0.5, 0);
        c.lineTo(Math.round(sx) + 0.5, height);
      }
      for (let y = Math.ceil(y0 / s) * s; y <= y1; y += s) {
        const [, sy] = toScreen(0, y);
        c.moveTo(0, Math.round(sy) + 0.5);
        c.lineTo(width, Math.round(sy) + 0.5);
      }
      c.stroke();
    }
    // Axes and origin.
    const [ox, oy] = toScreen(0, 0);
    c.strokeStyle = t.axis;
    c.lineWidth = 1.25;
    c.beginPath();
    c.moveTo(0, Math.round(oy) + 0.5);
    c.lineTo(width, Math.round(oy) + 0.5);
    c.moveTo(Math.round(ox) + 0.5, 0);
    c.lineTo(Math.round(ox) + 0.5, height);
    c.stroke();
    c.fillStyle = t.paper;
    c.beginPath();
    c.arc(ox, oy, 4.5, 0, Math.PI * 2);
    c.fill();
    c.lineWidth = 1.5;
    c.stroke();
    c.fillStyle = t.label;
    c.font = '500 11px "Fira Sans", system-ui, sans-serif';
    c.fillText("0", ox + 7, oy + 15);
    c.fillText("x", width - 14, oy - 7);
    c.fillText("y", ox + 7, 15);
  };

  const strokeSegments = (c: CanvasRenderingContext2D, segs: readonly Segment[], map: (x: number, y: number) => [number, number]) => {
    c.lineCap = "round";
    c.lineJoin = "round";
    let i = 0;
    while (i < segs.length) {
      const { color, width: w } = segs[i];
      c.strokeStyle = color;
      c.lineWidth = w;
      c.beginPath();
      let last: [number, number] | null = null;
      while (i < segs.length && segs[i].color === color && segs[i].width === w) {
        const s = segs[i];
        const a = map(s.from[0], s.from[1]);
        const b = map(s.to[0], s.to[1]);
        if (!last || Math.abs(last[0] - a[0]) > 0.01 || Math.abs(last[1] - a[1]) > 0.01) c.moveTo(a[0], a[1]);
        c.lineTo(b[0], b[1]);
        last = b;
        i++;
      }
      c.stroke();
    }
  };

  const drawTurtle = (c: CanvasRenderingContext2D, t: Theme) => {
    if (!turtle) return;
    const [sx, sy] = toScreen(turtle.pos[0], turtle.pos[1]);
    const angle = Math.atan2(turtle.heading[0], turtle.heading[1]);
    c.save();
    c.translate(sx, sy);
    c.rotate(angle);
    c.beginPath();
    c.moveTo(0, -13);
    c.lineTo(8.5, 8);
    c.lineTo(0, 4);
    c.lineTo(-8.5, 8);
    c.closePath();
    c.fillStyle = turtle.penDown ? t.here : "rgba(255,255,255,0.85)";
    c.fill();
    c.lineWidth = 1.75;
    c.lineJoin = "round";
    c.strokeStyle = t.hereEdge;
    c.stroke();
    c.restore();
  };

  const render = () => {
    queued = false;
    if (!ctx) return;
    const t = readTheme(el);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = t.paper;
    ctx.fillRect(0, 0, width, height);
    drawGrid(ctx, t);
    if (ghost) {
      ctx.save();
      ctx.setLineDash([6, 5]);
      ctx.globalAlpha = 0.75;
      strokeSegments(
        ctx,
        ghost.map((g) => ({ ...g, color: t.ghost, width: 2 })),
        toScreen,
      );
      ctx.restore();
    }
    strokeSegments(ctx, segments, toScreen);
    drawTurtle(ctx, t);
  };

  const schedule = () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(render);
  };

  const bounds = (includeGhost: boolean) => {
    let minX = 0;
    let maxX = 0;
    let minY = 0;
    let maxY = 0;
    const add = (x: number, y: number) => {
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x);
      minY = Math.min(minY, y);
      maxY = Math.max(maxY, y);
    };
    for (const s of segments) {
      add(s.from[0], s.from[1]);
      add(s.to[0], s.to[1]);
    }
    if (includeGhost && ghost) for (const s of ghost) (add(s.from[0], s.from[1]), add(s.to[0], s.to[1]));
    if (turtle) add(turtle.pos[0], turtle.pos[1]);
    return { minX, maxX, minY, maxY };
  };

  const fitTo = (b: { minX: number; maxX: number; minY: number; maxY: number }) => {
    if (!width || !height) resize();
    const w = Math.max(b.maxX - b.minX, 40);
    const h = Math.max(b.maxY - b.minY, 40);
    scale = Math.max(MIN_SCALE, Math.min(MAX_SCALE, Math.min((width - FIT_PADDING * 2) / w, (height - FIT_PADDING * 2) / h), 4));
    cx = (b.minX + b.maxX) / 2;
    cy = (b.minY + b.maxY) / 2;
  };

  const zoomAt = (factor: number, sx: number, sy: number) => {
    const [wx, wy] = toWorld(sx, sy);
    scale = Math.max(MIN_SCALE, Math.min(MAX_SCALE, scale * factor));
    cx = wx - (sx - width / 2) / scale;
    cy = wy + (sy - height / 2) / scale;
    manual = true;
    schedule();
  };

  // Pointer pan and pinch zoom.
  const pointers = new Map<number, { x: number; y: number }>();
  let pinchDist = 0;
  canvas.addEventListener("pointerdown", (e) => {
    canvas.setPointerCapture?.(e.pointerId);
    pointers.set(e.pointerId, { x: e.offsetX, y: e.offsetY });
    if (pointers.size === 2) {
      const [a, b] = [...pointers.values()];
      pinchDist = Math.hypot(a.x - b.x, a.y - b.y);
    }
    el.classList.add("is-dragging");
  });
  canvas.addEventListener("pointermove", (e) => {
    const prev = pointers.get(e.pointerId);
    if (!prev) return;
    const next = { x: e.offsetX, y: e.offsetY };
