import type { Segment, TurtleState } from "../lang";

export interface DrawingView {
  readonly el: HTMLElement;
  setSegments(segments: readonly Segment[]): void;
  setTurtle(turtle: Readonly<TurtleState> | null): void;
  setGhost(segments: readonly Segment[] | null): void;
  /** Frames the drawing, the turtle and the origin. */
  fit(): void;
  zoomBy(factor: number): void;
  resetView(): void;
  /** Re-fits only if the turtle or drawing left the visible area (unless the learner moved the view). */
  follow(): void;
  /** Clears the learner's manual pan/zoom so following resumes. */
  release(): void;
  toPNG(): Promise<Blob | null>;
  render(): void;
  /** True when this view can draw at all. */
  readonly available: boolean;
}

interface Theme {
  paper: string;
  grid: string;
  gridMajor: string;
  axis: string;
  ghost: string;
  here: string;
  hereEdge: string;
  label: string;
}

function readTheme(el: HTMLElement): Theme {
  const cs = getComputedStyle(el);
  const v = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    paper: v("--paper", "#fbfcfd"),
    grid: v("--paper-grid", "#e7ebf1"),
    gridMajor: v("--paper-grid-major", "#d5dbe4"),
    axis: v("--paper-axis", "#a8b2c2"),
    ghost: v("--paper-ghost", "#7f8ba0"),
    here: v("--here", "#f2c230"),
    hereEdge: "#17223b",
    label: "#47526a",
  };
}

const MIN_SCALE = 0.01;
const MAX_SCALE = 40;
const FIT_PADDING = 36;

export function createView2D(): DrawingView {
  const el = document.createElement("div");
  el.className = "view2d";
  const canvas = document.createElement("canvas");
  canvas.setAttribute("role", "img");
  canvas.setAttribute("aria-label", "Rysunek żółwia na płaszczyźnie");
  canvas.tabIndex = 0;
  el.appendChild(canvas);
  const ctx = canvas.getContext("2d");

  let segments: readonly Segment[] = [];
  let ghost: readonly Segment[] | null = null;
  let turtle: Readonly<TurtleState> | null = null;
  // View: world point at the canvas centre and pixels per unit.
  let cx = 0;
  let cy = 60;
  let scale = 1;
  let manual = false;
  let width = 0;
  let height = 0;
  let dpr = 1;
  let queued = false;

  const toScreen = (x: number, y: number): [number, number] => [width / 2 + (x - cx) * scale, height / 2 - (y - cy) * scale];
  const toWorld = (sx: number, sy: number): [number, number] => [cx + (sx - width / 2) / scale, cy - (sy - height / 2) / scale];

  const resize = () => {
    const r = el.getBoundingClientRect();
    width = Math.max(1, Math.round(r.width));
    height = Math.max(1, Math.round(r.height));
    dpr = Math.min(window.devicePixelRatio || 1, 3);
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
  };

  const niceStep = (minPx: number) => {
    const raw = minPx / scale;
    const p = Math.pow(10, Math.floor(Math.log10(raw)));
    for (const m of [1, 2, 5, 10]) if (p * m >= raw) return p * m;
    return p * 10;
  };

