    c.beginPath();
    c.moveTo(0, -13);
    c.lineTo(8.5, 8);
    c.lineTo(0, 4);
    c.lineTo(-8.5, 8);
    c.closePath();
    c.fillStyle = turtle.penDown ? t.here : "rgba(255,255,255,0.85)";
