    while (i < segs.length) {
      const { color, width: w } = segs[i];
      c.strokeStyle = color;
      c.lineWidth = w;
      c.beginPath();
      let last: [number, number] | null = null;
      while (i < segs.length && segs[i].color === color && segs[i].width === w) {
        const s = segs[i];
        const a = map(s.from[0], s.from[1]);
        const b = map(s.to[0], s.to[1]);
        if (!last || Math.abs(last[0] - a[0]) > 0.01 || Math.abs(last[1] - a[1]) > 0.01) c.moveTo(a[0], a[1]);
        c.lineTo(b[0], b[1]);
        last = b;
        i++;
      }
      c.stroke();
    }
  };

  const drawTurtle = (c: CanvasRenderingContext2D, t: Theme) => {
    if (!turtle) return;
    const [sx, sy] = toScreen(turtle.pos[0], turtle.pos[1]);
    const angle = Math.atan2(turtle.heading[0], turtle.heading[1]);
    c.save();
    c.translate(sx, sy);
    c.rotate(angle);
    c.beginPath();
    c.moveTo(0, -13);
    c.lineTo(8.5, 8);
    c.lineTo(0, 4);
    c.lineTo(-8.5, 8);
    c.closePath();
    c.fillStyle = turtle.penDown ? t.here : "rgba(255,255,255,0.85)";
    c.fill();
    c.lineWidth = 1.75;
    c.lineJoin = "round";
    c.strokeStyle = t.hereEdge;
    c.stroke();
    c.restore();
  };

  const render = () => {
    queued = false;
    if (!ctx) return;
    const t = readTheme(el);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = t.paper;
    ctx.fillRect(0, 0, width, height);
    drawGrid(ctx, t);
    if (ghost) {
      ctx.save();
      ctx.setLineDash([6, 5]);
      ctx.globalAlpha = 0.75;
      strokeSegments(
        ctx,
        ghost.map((g) => ({ ...g, color: t.ghost, width: 2 })),
        toScreen,
      );
      ctx.restore();
    }
    strokeSegments(ctx, segments, toScreen);
    drawTurtle(ctx, t);
  };

  const schedule = () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(render);
  };

  const bounds = (includeGhost: boolean) => {
    let minX = 0;
    let maxX = 0;
    let minY = 0;
    let maxY = 0;
    const add = (x: number, y: number) => {
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x);
      minY = Math.min(minY, y);
      maxY = Math.max(maxY, y);
    };
    for (const s of segments) {
      add(s.from[0], s.from[1]);
      add(s.to[0], s.to[1]);
    }
    if (includeGhost && ghost) for (const s of ghost) (add(s.from[0], s.from[1]), add(s.to[0], s.to[1]));
    if (turtle) add(turtle.pos[0], turtle.pos[1]);
    return { minX, maxX, minY, maxY };
  };

  const fitTo = (b: { minX: number; maxX: number; minY: number; maxY: number }) => {
    if (!width || !height) resize();
    const w = Math.max(b.maxX - b.minX, 40);
    const h = Math.max(b.maxY - b.minY, 40);
    scale = Math.max(MIN_SCALE, Math.min(MAX_SCALE, Math.min((width - FIT_PADDING * 2) / w, (height - FIT_PADDING * 2) / h), 4));
    cx = (b.minX + b.maxX) / 2;
    cy = (b.minY + b.maxY) / 2;
  };

  const zoomAt = (factor: number, sx: number, sy: number) => {
    const [wx, wy] = toWorld(sx, sy);
    scale = Math.max(MIN_SCALE, Math.min(MAX_SCALE, scale * factor));
    cx = wx - (sx - width / 2) / scale;
    cy = wy + (sy - height / 2) / scale;
    manual = true;
    schedule();
  };

  // Pointer pan and pinch zoom.
  const pointers = new Map<number, { x: number; y: number }>();
  let pinchDist = 0;
  canvas.addEventListener("pointerdown", (e) => {
    canvas.setPointerCapture?.(e.pointerId);
    pointers.set(e.pointerId, { x: e.offsetX, y: e.offsetY });
    if (pointers.size === 2) {
      const [a, b] = [...pointers.values()];
      pinchDist = Math.hypot(a.x - b.x, a.y - b.y);
    }
    el.classList.add("is-dragging");
  });
  canvas.addEventListener("pointermove", (e) => {
    const prev = pointers.get(e.pointerId);
    if (!prev) return;
    const next = { x: e.offsetX, y: e.offsetY };
    pointers.set(e.pointerId, next);
    if (pointers.size === 1) {
      cx -= (next.x - prev.x) / scale;
      cy += (next.y - prev.y) / scale;
      manual = true;
      schedule();
    } else if (pointers.size === 2) {
      const [a, b] = [...pointers.values()];
      const d = Math.hypot(a.x - b.x, a.y - b.y);
      if (pinchDist > 0) zoomAt(d / pinchDist, (a.x + b.x) / 2, (a.y + b.y) / 2);
      pinchDist = d;
    }
  });
  const endPointer = (e: PointerEvent) => {
    pointers.delete(e.pointerId);
    if (pointers.size < 2) pinchDist = 0;
    if (pointers.size === 0) el.classList.remove("is-dragging");
  };
  canvas.addEventListener("pointerup", endPointer);
  canvas.addEventListener("pointercancel", endPointer);
  canvas.addEventListener(
    "wheel",
    (e) => {
      e.preventDefault();
      const factor = Math.exp(-e.deltaY * (e.ctrlKey ? 0.01 : 0.0015));
      zoomAt(factor, e.offsetX, e.offsetY);
    },
    { passive: false },
  );
  canvas.addEventListener("keydown", (e) => {
    const step = 40 / scale;
    const keys: Record<string, () => void> = {
      ArrowLeft: () => (cx -= step),
      ArrowRight: () => (cx += step),
      ArrowUp: () => (cy += step),
      ArrowDown: () => (cy -= step),
      "+": () => zoomAt(1.25, width / 2, height / 2),
      "=": () => zoomAt(1.25, width / 2, height / 2),
      "-": () => zoomAt(0.8, width / 2, height / 2),
      "0": () => api.fit(),
    };
    const f = keys[e.key];
    if (!f || e.ctrlKey || e.metaKey || e.altKey) return;
    e.preventDefault();
    f();
    if (e.key.startsWith("Arrow")) manual = true;
    schedule();
  });

  if (typeof ResizeObserver !== "undefined") {
    new ResizeObserver(() => {
      resize();
      render();
    }).observe(el);
  }

  const api: DrawingView = {
    el,
    available: !!ctx,
    setSegments(s) {
      segments = s;
      schedule();
    },
    setTurtle(t) {
      turtle = t;
      schedule();
    },
    setGhost(g) {
      ghost = g;
      schedule();
    },
    fit() {
      fitTo(bounds(true));
      manual = false;
      schedule();
    },
    zoomBy(f) {
      if (!width) resize();
      zoomAt(f, width / 2, height / 2);
    },
    resetView() {
      if (!width) resize();
      cx = 0;
      cy = Math.min(120, height / 4);
      scale = 1;
      manual = false;
      schedule();
    },
    follow() {
      if (manual) return;
      const b = bounds(true);
      const [l, t] = toScreen(b.minX, b.maxY);
      const [r, bt] = toScreen(b.maxX, b.minY);
      const m = 12;
      if (l < m || t < m || r > width - m || bt > height - m) fitTo(b);
      schedule();
    },
    release() {
      manual = false;
    },
    render,
    async toPNG() {
      const b = bounds(false);
      const pad = 24;
      const k = 2;
      const w = Math.max(b.maxX - b.minX, 1);
      const h = Math.max(b.maxY - b.minY, 1);
      const s = Math.min(4, 1600 / Math.max(w, h));
      const out = document.createElement("canvas");
      out.width = Math.ceil((w * s + pad * 2) * k);
      out.height = Math.ceil((h * s + pad * 2) * k);
      const c = out.getContext("2d");
      if (!c) return null;
      c.scale(k, k);
      c.fillStyle = "#ffffff";
      c.fillRect(0, 0, out.width, out.height);
      strokeSegments(c, segments, (x, y) => [pad + (x - b.minX) * s, pad + (b.maxY - y) * s]);
      return new Promise((resolve) => out.toBlob((blob) => resolve(blob), "image/png"));
    },
  };
  return api;
}

