import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { LineMaterial } from "three/examples/jsm/lines/LineMaterial.js";
import { LineSegments2 } from "three/examples/jsm/lines/LineSegments2.js";
import { LineSegmentsGeometry } from "three/examples/jsm/lines/LineSegmentsGeometry.js";
import type { Segment, TurtleState } from "../lang";
import type { DrawingView } from "./view2d";

export interface View3D extends DrawingView {
  /** Why 3D is off, when it is. */
  readonly unavailableReason: string | null;
}

function webglSupport(): string | null {
  try {
    const c = document.createElement("canvas");
    const gl = c.getContext("webgl2") || c.getContext("webgl");
    if (!gl) return "Ta przeglądarka nie udostępnia WebGL, więc widok przestrzenny jest wyłączony.";
    return null;
  } catch {
    return "Nie udało się uruchomić WebGL, więc widok przestrzenny jest wyłączony.";
  }
}

const DEFAULT_DIR = new THREE.Vector3(1, -1.5, 1.1).normalize();

export function createView3D(): View3D {
  const el = document.createElement("div");
  el.className = "view3d";
  let reason = webglSupport();

  let renderer: THREE.WebGLRenderer | null = null;
  if (!reason) {
    try {
      renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
    } catch {
      reason = "Nie udało się uruchomić WebGL, więc widok przestrzenny jest wyłączony.";
    }
  }

  if (!renderer) {
    el.classList.add("is-off");
    el.innerHTML = `<div class="view-off" role="status"><strong>Widok 3D jest wyłączony.</strong><p>${reason}</p><p>Program w trybie 3D nadal możesz pisać, uruchamiać i sprawdzać — zobaczysz komunikaty i liczbę odcinków. Tryb 2D działa normalnie.</p></div>`;
    const noop = () => {};
    return {
      el,
      available: false,
      unavailableReason: reason,
      setSegments: noop,
      setTurtle: noop,
      setGhost: noop,
      fit: noop,
      zoomBy: noop,
      resetView: noop,
      follow: noop,
      release: noop,
      render: noop,
      toPNG: async () => null,
    };
  }

  const r = renderer;
  r.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  r.domElement.setAttribute("role", "img");
  r.domElement.setAttribute("aria-label", "Rysunek żółwia w przestrzeni");
  r.domElement.tabIndex = 0;
  el.appendChild(r.domElement);

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(45, 1, 0.5, 20000);
  camera.up.set(0, 0, 1);
  const controls = new OrbitControls(camera, r.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.12;
  controls.screenSpacePanning = true;
  controls.listenToKeyEvents(r.domElement);
  controls.keyPanSpeed = 20;

  // Ground grid in the XY plane, 10-unit cells.
  const grid = new THREE.GridHelper(400, 40);
  grid.rotation.x = Math.PI / 2;
  scene.add(grid);

  // Axes with letter labels.
  const axes = new THREE.Group();
  const axisColors = [0xc0533f, 0x3b9659, 0x3a6fbe];
  const axisDirs = [new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 0, 1)];
  const labelSprites: THREE.Sprite[] = [];
  ["x", "y", "z"].forEach((name, i) => {
    const g = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), axisDirs[i].clone().multiplyScalar(120)]);
    axes.add(new THREE.Line(g, new THREE.LineBasicMaterial({ color: axisColors[i] })));
    const c = document.createElement("canvas");
    c.width = c.height = 64;
    const x = c.getContext("2d");
    if (x) {
      x.font = '600 40px "Fira Sans", system-ui, sans-serif';
      x.fillStyle = "#" + axisColors[i].toString(16).padStart(6, "0");
      x.textAlign = "center";
      x.textBaseline = "middle";
      x.fillText(name, 32, 34);
    }
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(c), depthTest: false }));
    sprite.position.copy(axisDirs[i].clone().multiplyScalar(132));
    sprite.scale.set(14, 14, 1);
    labelSprites.push(sprite);
    axes.add(sprite);
  });
  scene.add(axes);

  // Strokes: one fat-line object per pen width.
  const strokes = new THREE.Group();
  scene.add(strokes);
  const ghostGroup = new THREE.Group();
  scene.add(ghostGroup);
  const materials = new Map<number, LineMaterial>();
  const materialFor = (w: number, dashed = false) => {
    const key = dashed ? -w : w;
    let m = materials.get(key);
    if (!m) {
      m = new LineMaterial({ linewidth: w, vertexColors: !dashed, worldUnits: false, dashed, dashSize: 6, gapSize: 5 });
      if (dashed) {
        m.color.set(0x7f8ba0);
        m.transparent = true;
        m.opacity = 0.8;
      }
      materials.set(key, m);
    }
    return m;
  };

  // Turtle: a flat dart along heading/right with a fin along up, so roll is visible.
  const turtleGeom = new THREE.BufferGeometry();
  // prettier-ignore
  const tv = new Float32Array([
    0, 13, 0,   8, -7, 0,   0, -3, 0,
    0, 13, 0,   0, -3, 0,  -8, -7, 0,
    0, 9, 0,    0, -4, 0,   0, -4, 7,
  ]);
  turtleGeom.setAttribute("position", new THREE.BufferAttribute(tv, 3));
  turtleGeom.computeVertexNormals();
  const turtleMesh = new THREE.Mesh(turtleGeom, new THREE.MeshBasicMaterial({ color: 0xf2c230, side: THREE.DoubleSide }));
  const turtleEdges = new THREE.LineSegments(new THREE.EdgesGeometry(turtleGeom), new THREE.LineBasicMaterial({ color: 0x17223b }));
  const turtleObj = new THREE.Group();
  turtleObj.add(turtleMesh, turtleEdges);
  scene.add(turtleObj);

  let segments: readonly Segment[] = [];
  let ghost: readonly Segment[] | null = null;
  let builtCount = -1;
  let builtRef: readonly Segment[] | null = null;
  let manual = false;
  let width = 1;
  let height = 1;
  let queued = false;

  const applyTheme = () => {
    const cs = getComputedStyle(el);
    scene.background = new THREE.Color(cs.getPropertyValue("--paper").trim() || "#fbfcfd");
    const gridMat = grid.material as THREE.LineBasicMaterial;
    gridMat.color = new THREE.Color(cs.getPropertyValue("--paper-grid-major").trim() || "#d5dbe4");
    (grid as unknown as { material: THREE.Material }).material.needsUpdate = true;
  };

  const rebuild = () => {
    if (builtRef === segments && builtCount === segments.length) return;
    for (const child of [...strokes.children]) {
      strokes.remove(child);
      (child as LineSegments2).geometry.dispose();
    }
    const byWidth = new Map<number, Segment[]>();
    for (const s of segments) {
      let list = byWidth.get(s.width);
      if (!list) byWidth.set(s.width, (list = []));
      list.push(s);
    }
    const color = new THREE.Color();
    for (const [w, list] of byWidth) {
      const pos = new Float32Array(list.length * 6);
      const col = new Float32Array(list.length * 6);
      list.forEach((s, i) => {
        pos.set([...s.from, ...s.to], i * 6);
        color.set(s.color);
        col.set([color.r, color.g, color.b, color.r, color.g, color.b], i * 6);
      });
      const g = new LineSegmentsGeometry();
      g.setPositions(pos);
      g.setColors(col);
      strokes.add(new LineSegments2(g, materialFor(w)));
    }
    builtRef = segments;
    builtCount = segments.length;
  };

  const rebuildGhost = () => {
    for (const child of [...ghostGroup.children]) {
      ghostGroup.remove(child);
      (child as LineSegments2).geometry.dispose();
    }
    if (!ghost || !ghost.length) return;
    const pos = new Float32Array(ghost.length * 6);
    ghost.forEach((s, i) => pos.set([...s.from, ...s.to], i * 6));
    const g = new LineSegmentsGeometry();
    g.setPositions(pos);
    const line = new LineSegments2(g, materialFor(2, true));
    line.computeLineDistances();
    ghostGroup.add(line);
  };

  const resize = () => {
    const rect = el.getBoundingClientRect();
    width = Math.max(1, Math.round(rect.width));
    height = Math.max(1, Math.round(rect.height));
    r.setSize(width, height, true);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
    for (const m of materials.values()) m.resolution.set(width, height);
  };

  const render = () => {
    queued = false;
    rebuild();
    for (const m of materials.values()) m.resolution.set(width, height);
    // Keep axis labels and the turtle a readable size at any zoom.
    const d = camera.position.distanceTo(controls.target);
    const k = Math.max(0.35, d / 450);
    labelSprites.forEach((s) => s.scale.set(14 * k, 14 * k, 1));
    turtleObj.scale.setScalar(Math.max(0.6, d / 500));
    r.render(scene, camera);
  };

  const schedule = () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(render);
  };

  controls.addEventListener("change", schedule);
  controls.addEventListener("start", () => {
    manual = true;
  });

  // Damping needs a few frames after the user lets go.
  let animating = false;
  const loop = () => {
    if (!animating) return;
    controls.update();
    requestAnimationFrame(loop);
  };
  r.domElement.addEventListener("pointerdown", () => {
    animating = true;
    loop();
  });
  r.domElement.addEventListener("pointerup", () => setTimeout(() => (animating = false), 600));

  const box = () => {
    const b = new THREE.Box3();
    b.expandByPoint(new THREE.Vector3(0, 0, 0));
    for (const s of segments) {
      b.expandByPoint(new THREE.Vector3(...s.from));
      b.expandByPoint(new THREE.Vector3(...s.to));
    }
    if (ghost) for (const s of ghost) (b.expandByPoint(new THREE.Vector3(...s.from)), b.expandByPoint(new THREE.Vector3(...s.to)));
    b.expandByPoint(turtleObj.position);
    return b;
  };

  const frameBox = (b: THREE.Box3) => {
    const sphere = b.getBoundingSphere(new THREE.Sphere());
    const radius = Math.max(sphere.radius, 60);
    const fov = (camera.fov * Math.PI) / 180;
    const fitH = radius / Math.sin(fov / 2);
    const fitW = fitH / Math.min(1, camera.aspect);
    const dist = Math.max(fitH, fitW) * 1.05;
    controls.target.copy(sphere.center);
    camera.position.copy(sphere.center).addScaledVector(DEFAULT_DIR, dist);
    camera.near = Math.max(0.5, dist / 500);
    camera.far = dist * 20 + radius * 4;
    camera.updateProjectionMatrix();
    controls.update();
  };

  if (typeof ResizeObserver !== "undefined") {
    new ResizeObserver(() => {
      resize();
      render();
    }).observe(el);
  }
  applyTheme();
  frameBox(box());

  const api: View3D = {
    el,
    available: true,
    unavailableReason: null,
    setSegments(s) {
      segments = s;
      schedule();
    },
    setTurtle(t) {
      if (t) {
        turtleObj.visible = true;
        turtleObj.position.set(...t.pos);
        const m = new THREE.Matrix4().makeBasis(new THREE.Vector3(...t.right), new THREE.Vector3(...t.heading), new THREE.Vector3(...t.up));
        turtleObj.quaternion.setFromRotationMatrix(m);
        (turtleMesh.material as THREE.MeshBasicMaterial).color.set(t.penDown ? 0xf2c230 : 0xffffff);
      } else {
        turtleObj.visible = false;
      }
      schedule();
    },
    setGhost(g) {
      ghost = g;
      rebuildGhost();
      schedule();
    },
    fit() {
      if (width <= 1) resize();
      frameBox(box());
      manual = false;
      schedule();
    },
    zoomBy(f) {
      const offset = camera.position.clone().sub(controls.target).multiplyScalar(1 / f);
      camera.position.copy(controls.target).add(offset);
      controls.update();
      manual = true;
      schedule();
    },
    resetView() {
      if (width <= 1) resize();
      const b = new THREE.Box3(new THREE.Vector3(-100, -100, 0), new THREE.Vector3(100, 100, 60));
      frameBox(b);
      manual = false;
      schedule();
    },
    follow() {
      if (manual) return;
      // Re-frame when anything drawn falls outside the camera's view.
      camera.updateMatrixWorld();
      const projScreen = new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
      const frustum = new THREE.Frustum().setFromProjectionMatrix(projScreen);
      const b = box();
      if (!frustum.containsPoint(b.min) || !frustum.containsPoint(b.max)) frameBox(b);
      schedule();
    },
    release() {
      manual = false;
    },
    render() {
      applyTheme();
      render();
    },
    async toPNG() {
      render();
      return new Promise((resolve) => r.domElement.toBlob((b) => resolve(b), "image/png"));
    },
  };
  return api;
}

