      const frustum = new THREE.Frustum().setFromProjectionMatrix(projScreen);
      const b = box();
      if (!frustum.containsPoint(b.min) || !frustum.containsPoint(b.max)) frameBox(b);
      schedule();
    },
    release() {
      manual = false;
    },
    render() {
      applyTheme();
      render();
    },
    async toPNG() {
      render();
      return new Promise((resolve) => r.domElement.toBlob((b) => resolve(b), "image/png"));
    },
  };
  return api;
}

