import type { Mode } from "../lang";

export interface DocExample {
  code: string;
  mode: Mode;
}

export interface DocCommand {
  names: string[];
  english: string[];
  arg: string;
  text: string;
  example: DocExample;
}

export interface DocSection {
  id: string;
  title: string;
  intro: string;
  commands?: DocCommand[];
  /** Free-form blocks: paragraphs (strings) and examples. */
  blocks?: (string | DocExample | { list: string[] } | { table: string[][] })[];
}

export const DOC_SECTIONS: DocSection[] = [
  {
    id: "start",
    title: "Pierwsze kroki",
    intro:
      "Program to lista poleceń dla żółwia. Żółw stoi na środku, w punkcie (0, 0), patrzy w górę ekranu i trzyma opuszczony pisak w kolorze \"#16866a\" o grubości 3. Każde polecenie przesuwa go albo obraca — a kiedy pisak jest opuszczony, za żółwiem zostaje linia.",
    blocks: [
      { code: "np 100\npw 90\nnp 50", mode: "2d" },
      "Wielkość liter nie ma znaczenia: NP, Np i np to to samo polecenie. Polskie słowa możesz pisać z ogonkami albo bez nich (naprzód i naprzod), a zamiast nich używać angielskich odpowiedników (fd, rt…).",
      "Średnik zaczyna komentarz, który trwa do końca wiersza. Żółw go pomija.",
      { code: "; To jest komentarz.\nnp 80 ; ten też", mode: "2d" },
    ],
  },
  {
    id: "ruch",
    title: "Ruch i obroty",
    intro: "Odległości mierzy się w krokach żółwia, kąty w stopniach. Liczba może mieć część ułamkową, a wartość ujemna działa w przeciwną stronę.",
    commands: [
      {
        names: ["np", "naprzód", "naprzod"],
        english: ["fd", "forward"],
        arg: "odległość",
        text: "Żółw idzie naprzód, w kierunku, w którym patrzy.",
        example: { code: "np 120", mode: "2d" },
      },
      {
        names: ["ws", "wstecz"],
        english: ["bk", "back"],
        arg: "odległość",
        text: "Żółw cofa się, nie obracając się.",
        example: { code: "np 100\nws 40", mode: "2d" },
      },
      {
        names: ["pw", "prawo"],
        english: ["rt", "right"],
        arg: "kąt",
        text: "Żółw obraca się w prawo (zgodnie z ruchem wskazówek zegara, patrząc z góry).",
        example: { code: "np 60\npw 90\nnp 60", mode: "2d" },
      },
      {
        names: ["lw", "lewo"],
        english: ["lt", "left"],
        arg: "kąt",
        text: "Żółw obraca się w lewo.",
        example: { code: "np 60\nlw 45\nnp 60", mode: "2d" },
      },
      {
        names: ["dom"],
        english: ["home"],
        arg: "—",
        text: "Żółw wraca do punktu startu i ustawia się jak na początku (w górę). Jeśli pisak jest opuszczony, rysuje drogę powrotną. Pisak, kolor i grubość zostają bez zmian.",
        example: { code: "np 80\npw 90\nnp 80\ndom", mode: "2d" },
      },
    ],
  },
  {
    id: "pisak",
    title: "Pisak",
    intro: "Pisak ma stan (opuszczony albo podniesiony), kolor i grubość. Wszystkie trzy obowiązują, dopóki ich nie zmienisz.",
    commands: [
      {
        names: ["pod", "podnieś", "podnies"],
        english: ["pu", "penup"],
        arg: "—",
        text: "Podnosi pisak: żółw chodzi, ale nie rysuje.",
        example: { code: "np 30\npod\nnp 20\nopu\nnp 30", mode: "2d" },
      },
      {
        names: ["opu", "opuść", "opusc"],
        english: ["pd", "pendown"],
        arg: "—",
        text: "Opuszcza pisak: od teraz za żółwiem znów zostaje linia.",
        example: { code: "pod ws 50 opu\nnp 100", mode: "2d" },
      },
      {
        names: ["kolor"],
        english: ["color"],
        arg: 'kolor w cudzysłowie, "#rrggbb"',
        text: "Zmienia kolor pisaka. Kolor zapisuje się jako znak # i sześć cyfr szesnastkowych: dwie na czerwony, dwie na zielony, dwie na niebieski.",
        example: { code: 'kolor "#c1763d"\nnp 80\nkolor "#2b6fb3"\npw 90 np 80', mode: "2d" },
      },
      {
        names: ["grubość", "grubosc"],
        english: ["width"],
        arg: "liczba całkowita od 1 do 12",
        text: "Zmienia grubość linii.",
        example: { code: "grubosc 1 np 40\npw 90\ngrubosc 8 np 40", mode: "2d" },
      },
      {
        names: ["czyść", "czysc"],
        english: ["cs", "clearscreen"],
        arg: "—",
        text: "Wymazuje wszystko, co narysowano do tej pory. Żółw zostaje tam, gdzie był, z tym samym kierunkiem i pisakiem.",
        example: { code: "np 50\nczyść\npw 90 np 50", mode: "2d" },
      },
    ],
  },
  {
    id: "przestrzen",
    title: "Przestrzeń (tryb 3D)",
    intro:
      "W trybie 3D żółw może też zadzierać i opuszczać nos oraz przechylać się na boki. Osie: x w prawo, y przed siebie (w górę kartki), z w górę, ku tobie. Te cztery polecenia w trybie 2D są błędem. Program złożony tylko z poleceń płaskich rysuje w obu trybach dokładnie to samo.",
    commands: [
      {
        names: ["góra", "gora"],
        english: ["pitchup"],
        arg: "kąt",
        text: "Żółw zadziera nos: obraca kierunek ku swojej górze. Po gora 90 idzie tam, gdzie wcześniej miał grzbiet.",
        example: { code: "np 50\ngora 90\nnp 50", mode: "3d" },
      },
      {
        names: ["dół", "dol"],
        english: ["pitchdown"],
        arg: "kąt",
        text: "Żółw opuszcza nos — obrót w przeciwną stronę niż góra.",
        example: { code: "np 50\ndol 45\nnp 50", mode: "3d" },
      },
      {
        names: ["pp", "przechylprawo"],
        english: ["rr", "rollright"],
        arg: "kąt",
        text: "Żółw przechyla się na prawy bok, nie zmieniając kierunku. Po pp 90 jego grzbiet jest tam, gdzie był prawy bok.",
        example: { code: "pp 90\npowtorz 4 [np 60 pw 90]", mode: "3d" },
      },
      {
        names: ["pl", "przechyllewo"],
        english: ["rl", "rollleft"],
        arg: "kąt",
        text: "Żółw przechyla się na lewy bok.",
        example: { code: "pl 45\npowtorz 36 [np 10 pw 10]", mode: "3d" },
      },
    ],
  },
  {
    id: "powtorz",
    title: "Powtarzanie",
    intro:
      "Polecenia w nawiasach kwadratowych [ ] tworzą listę. Powtórz wykonuje ją podaną liczbę razy. Nawiasy można zagnieżdżać.",
    commands: [
      {
        names: ["powtórz", "powtorz"],
        english: ["repeat"],
        arg: "liczba całkowita od 0 do 10 000, potem [ lista ]",
        text: "Wykonuje listę poleceń tyle razy, ile podano. Zero oznacza: ani razu.",
        example: { code: "powtorz 4 [np 80 pw 90]", mode: "2d" },
      },
      {
        names: ["nrpowt"],
        english: ["repcount"],
        arg: "(wartość, nie polecenie)",
        text: "Numer bieżącego powtórzenia, licząc od 1, w najbliższym powtórz, które obejmuje ten fragment programu. Poza powtórz nie ma wartości — także wewnątrz procedury, która sama nie zawiera powtórz.",
        example: { code: "powtorz 20 [np nrpowt * 5 pw 90]", mode: "2d" },
      },
    ],
  },
  {
    id: "wyrazenia",
    title: "Wyrażenia",
    intro:
      "Wszędzie, gdzie polecenie przyjmuje liczbę, możesz napisać wyrażenie: liczbę, nazwę zmiennej lub parametru (także w dawnej postaci :nazwa), nrpowt, wyrażenie w nawiasach okrągłych, znak + lub − przed którymkolwiek z nich, albo dwa wyrażenia połączone działaniem + − * /.",
    blocks: [
      { list: ["* i / wiążą mocniej niż + i −: np 2 + 3 * 4 idzie o 14.", "Działania o tej samej mocy liczy się od lewej: np 20 - 5 - 3 idzie o 12.", "Nawiasy okrągłe zmieniają kolejność: np (2 + 3) * 4 idzie o 20."] },
      { code: "np 2 + 3 * 4\npw 90\nnp (2 + 3) * 4", mode: "2d" },
      "Ważne: znak działania musi mieć odstęp z obu stron albo z żadnej. np 10 - 5 i np 10-5 idą o 5. Ale np 10 -5 to np 10 i osobna, zbędna wartość −5 — taki zapis jest błędem.",
      "Znaki można łączyć: np -(3 - 5) idzie o 2, tak samo np - -2.",
      "Liczby zapisuje się cyframi, z kropką przed częścią ułamkową: 80, 12.5, .5. Zapisy 1e3, 0x10 czy Infinity nie są liczbami.",
      "Dzielenie przez zero i wynik zbyt duży, by go policzyć, zatrzymują program z błędem.",
    ],
  },
  {
    id: "zmienne",
    title: "Zmienne",
    intro: "Zmienna to nazwana liczba. Nadajesz jej wartość poleceniem niech, a potem używasz nazwy w wyrażeniach.",
    commands: [
      {
        names: ["niech"],
        english: ["let"],
        arg: "nazwa, potem wyrażenie",
        text: "Nadaje zmiennej wartość wyrażenia. Kolejne niech z tą samą nazwą zmienia wartość.",
        example: { code: "niech bok 20\npowtorz 8 [\n  np bok pw 90\n  niech bok bok + 10\n]", mode: "2d" },
      },
    ],
    blocks: [
      { list: [
        "niech poza procedurą tworzy zmienną globalną, widoczną w całym programie.",
        "niech wewnątrz procedury tworzy zmienną lokalną: przesłania globalną o tej samej nazwie do końca tego wywołania i znika, gdy wywołanie się kończy. Tak samo można zmienić parametr.",
        "Nazwy, której nigdzie nie nadano wartości, nie można użyć — to błąd, zanim program w ogóle ruszy.",
        "Odczyt zmiennej, która jeszcze nie dostała wartości w tym przebiegu, zatrzymuje program z błędem.",
        "Nazwa zmiennej nie może być słowem polecenia ani nazwą procedury.",
      ] },
    ],
  },
  {
    id: "warunki",
    title: "Warunki",
    intro:
      "Warunek to dwa wyrażenia i porównanie między nimi: <, >, =, <=, >= albo <> (różne). Porównania są dokładne: 0.1 + 0.2 = 0.3 nie jest prawdą, bo komputer liczy ułamki z maleńkim błędem.",
    commands: [
      {
        names: ["jeśli", "jesli"],
        english: ["if"],
        arg: "warunek, potem [ lista ]",
        text: "Wykonuje listę tylko wtedy, gdy warunek jest spełniony.",
        example: { code: "powtorz 12 [\n  jeśli nrpowt > 6 [kolor \"#c1763d\"]\n  np 40 pw 30\n]", mode: "2d" },
      },
      {
        names: ["jeżeli", "jezeli"],
        english: ["ifelse"],
        arg: "warunek, potem [ lista ] [ lista ]",
        text: "Wykonuje pierwszą listę, gdy warunek jest spełniony, a drugą — gdy nie jest.",
        example: { code: "powtorz 8 [\n  jeżeli nrpowt / 2 = 4 [np 80] [np 40]\n  pw 45\n]", mode: "2d" },
      },
      {
        names: ["stop"],
        english: ["stop"],
        arg: "—",
        text: "Kończy bieżące wywołanie procedury od razu. Poza procedurą kończy cały program. stop w powtórz albo w warunku kończy całą procedurę, nie tylko tę listę.",
        example: { code: "powtorz 100 [\n  np 10 pw 30\n  jeśli nrpowt = 12 [stop]\n]", mode: "2d" },
      },
    ],
  },
  {
    id: "procedury",
    title: "Procedury",
    intro:
      "Procedura to nowe polecenie zbudowane z innych. Definicja zaczyna się od oto na początku wiersza, potem nazwa i — jeśli trzeba — ma: oraz parametry oddzielone przecinkami. Treść jest w kolejnych wierszach, a kończy ją już, samo w osobnym wierszu.",
    blocks: [
      { code: "oto kwadrat ma: bok, kąt\n  powtorz 4 [np bok pw kąt]\njuż\n\nkwadrat 80 90", mode: "2d" },
      { list: [
        "Wywołanie podaje argumenty po kolei, oddzielone odstępami — dokładnie tyle, ile procedura ma parametrów. Każdy argument jest wyrażeniem: kwadrat 40 * 2 90 przekazuje 80 i 90.",
        "Procedurę można zdefiniować przed jej wywołaniem albo po nim, ale tylko raz i tylko na najwyższym poziomie — nie w nawiasach i nie w innej procedurze.",
        "Procedura może wywoływać samą siebie (rekurencja). Pamiętaj o warunku z stop, który ją zakończy.",
        "Dawny zapis nagłówka też działa: oto kwadrat :bok :kąt, a parametr można pisać jako :bok albo bok.",
        "Parametr może nazywać się tak samo jak procedura: jako polecenie ta nazwa wywołuje procedurę, jako argument oznacza parametr.",
        "Słowa oto, ma: i już mają odpowiedniki to i end; juz działa jak już.",
      ] },
      { code: "oto gałąź ma: dł\n  jeśli dł < 10 [stop]\n  np dł\n  lw 30 gałąź dł * 0.7\n  pw 60 gałąź dł * 0.7\n  lw 30\n  pod ws dł opu\njuż\n\ngałąź 60", mode: "2d" },
    ],
  },
  {
    id: "bledy",
    title: "Błędy",
    intro:
      "Każdy błąd ma numer wiersza i kolumny oraz opis po polsku. Edytor podkreśla miejsce błędu, a na pasku pod edytorem jest pełny opis.",
    blocks: [
      { list: [
        "Program jest sprawdzany w całości przed rysowaniem. Błąd w zapisie (nieznane polecenie, brakujący argument, niedomknięty nawias, zła liczba argumentów…) oznacza, że nic się nie narysuje.",
        "Niektóre błędy wychodzą dopiero w trakcie: dzielenie przez zero, zmienna bez wartości, przekroczony limit, grubość albo liczba powtórzeń wyliczona ze zmiennej. Wtedy to, co już narysowano, zostaje na ekranie.",
        "Błąd złego argumentu wskazuje pierwszy znak tego argumentu. Brakujący argument wskazuje to, co stoi w jego miejscu — albo samo polecenie, gdy program się na nim kończy.",
      ] },
    ],
  },
  {
    id: "limity",
    title: "Ograniczenia",
    intro: "Żeby żaden program nie zawiesił przeglądarki, obowiązują limity. Przekroczenie każdego z nich to błąd.",
    blocks: [
      {
        table: [
          ["Długość programu", "50 000 znaków"],
          ["Elementy programu", "10 000 (słowa, liczby, znaki działań, nawiasy i przecinki)"],
          ["Zagnieżdżenie nawiasów", "32 poziomy"],
          ["Naraz otwarte wywołania procedur i powtórzenia", "32"],
          ["Wykonane operacje", "10 000 — każde polecenie, niech, warunek, powtórz i wywołanie, plus jedna za zakończenie każdego obrotu pętli, listy warunku i wywołania"],
          ["Odcinki na rysunku", "10 000 (liczą się te, które zostały po czyść)"],
          ["Współrzędne żółwia", "od −100 000 do 100 000"],
        ],
      },
    ],
  },
];

export const SHORTCUTS: [string, string][] = [
  ["Uruchom od początku", "Ctrl + Enter"],
  ["Krok (jedno polecenie)", "Ctrl + Shift + Enter"],
  ["Pauza / wznów", "Ctrl + ."],
  ["Od nowa (wyczyść rysunek)", "Ctrl + Shift + Backspace"],
  ["Widok: przesuń / powiększ / dopasuj", "strzałki / + − / 0 (gdy rysunek ma fokus)"],
];

