import { icon } from "./icons";

export interface MenuItem {
  label: string;
  /** Secondary line under the label. */
  detail?: string;
  icon?: string;
  /** Small badge before the label, e.g. a mode bullet. */
  badge?: { text: string; mode: "2d" | "3d" };
  group?: string;
  action: () => void;
  disabled?: boolean;
}

/**
 * A button that opens a menu of actions. Arrow keys move, Enter/Space run,
 * Escape and Tab close, focus returns to the button.
 */
export function createMenuButton(opts: { label: string; icon: string; items: () => MenuItem[]; className?: string }) {
  const wrap = document.createElement("div");
  wrap.className = `menu ${opts.className ?? ""}`;
  const id = `menu-${Math.random().toString(36).slice(2, 8)}`;
  wrap.innerHTML = `<button type="button" class="btn btn-quiet" aria-haspopup="menu" aria-expanded="false" aria-controls="${id}">${icon(opts.icon)}<span class="btn-label">${opts.label}</span>${icon("chevron", 16)}</button><div class="menu-pop" role="menu" id="${id}" aria-label="${opts.label}" hidden></div>`;
  const button = wrap.querySelector("button")!;
  const pop = wrap.querySelector<HTMLElement>(".menu-pop")!;

  const itemsEls = () => [...pop.querySelectorAll<HTMLElement>('[role="menuitem"]:not([aria-disabled="true"])')];

  const place = () => {
    const r = button.getBoundingClientRect();
    pop.style.top = `${Math.round(r.bottom + 6)}px`;
    const w = pop.offsetWidth || 300;
    const left = Math.min(Math.max(8, r.right - w), Math.max(8, window.innerWidth - w - 8));
    pop.style.left = `${Math.round(r.left + w < window.innerWidth - 8 ? r.left : left)}px`;
    pop.style.maxHeight = `${Math.max(160, window.innerHeight - r.bottom - 20)}px`;
  };

  const close = (refocus = true) => {
    if (pop.hidden) return;
    pop.hidden = true;
    button.setAttribute("aria-expanded", "false");
    document.removeEventListener("pointerdown", outside, true);
    window.removeEventListener("resize", onResize);
    if (refocus) button.focus();
  };

  const outside = (e: Event) => {
    if (!wrap.contains(e.target as Node)) close(false);
  };
  const onResize = () => close(false);

  const open = (focusLast = false) => {
    const items = opts.items();
    let html = "";
    let group: string | undefined;
    for (const [i, it] of items.entries()) {
      if (it.group && it.group !== group) {
        group = it.group;
        html += `<div class="menu-group" role="presentation">${it.group}</div>`;
      }
      const badge = it.badge ? `<span class="bullet bullet-${it.badge.mode}" aria-hidden="true">${it.badge.text}</span>` : "";
      const ic = it.icon ? icon(it.icon) : "";
      html += `<div role="menuitem" tabindex="-1" data-i="${i}" class="menu-item"${it.disabled ? ' aria-disabled="true"' : ""}>${badge}${ic}<span class="menu-text"><span class="menu-label">${it.label}</span>${it.detail ? `<span class="menu-detail">${it.detail}</span>` : ""}</span></div>`;
    }
    pop.innerHTML = html;
    pop.hidden = false;
    button.setAttribute("aria-expanded", "true");
    place();
    const els = itemsEls();
    (focusLast ? els[els.length - 1] : els[0])?.focus();
    pop.onclick = (e) => {
      const el = (e.target as HTMLElement).closest<HTMLElement>('[role="menuitem"]');
      if (!el || el.getAttribute("aria-disabled") === "true") return;
      close();
      items[Number(el.dataset.i)].action();
    };
    document.addEventListener("pointerdown", outside, true);
    window.addEventListener("resize", onResize);
  };

  button.addEventListener("click", () => (pop.hidden ? open() : close()));
  button.addEventListener("keydown", (e) => {
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      open(e.key === "ArrowUp");
    }
  });
  pop.addEventListener("keydown", (e) => {
    const els = itemsEls();
    const i = els.indexOf(document.activeElement as HTMLElement);
    if (e.key === "ArrowDown") {
      e.preventDefault();
      els[(i + 1) % els.length]?.focus();
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      els[(i - 1 + els.length) % els.length]?.focus();
    } else if (e.key === "Home") {
      e.preventDefault();
      els[0]?.focus();
    } else if (e.key === "End") {
      e.preventDefault();
      els[els.length - 1]?.focus();
    } else if (e.key === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      close();
    } else if (e.key === "Tab") {
      close(false);
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      (document.activeElement as HTMLElement)?.click();
    }
  });

  return { el: wrap, button, close };
}

