import { escapeHtml } from "./highlight";

export interface Toaster {
  readonly el: HTMLElement;
  show(message: string, action?: { label: string; run: () => void }, ms?: number): void;
}

/** One polite live region; a new message replaces the previous one. */
export function createToaster(): Toaster {
  const el = document.createElement("div");
  el.className = "toast-region";
  el.setAttribute("role", "status");
  el.setAttribute("aria-live", "polite");
  let timer: ReturnType<typeof setTimeout> | undefined;
  return {
    el,
    show(message, action, ms = 6000) {
      clearTimeout(timer);
      el.innerHTML = `<div class="toast"><span>${escapeHtml(message)}</span>${action ? `<button type="button" class="btn btn-small btn-on-dark">${escapeHtml(action.label)}</button>` : ""}<button type="button" class="toast-close" aria-label="Zamknij powiadomienie">×</button></div>`;
      const toast = el.firstElementChild as HTMLElement;
      const hide = () => toast.remove();
      if (action) {
        toast.querySelector(".btn")!.addEventListener("click", () => {
          action.run();
          hide();
        });
      }
      toast.querySelector(".toast-close")!.addEventListener("click", hide);
      timer = setTimeout(hide, action ? Math.max(ms, 10000) : ms);
    },
  };
}

