import type { Mode, RunResult, Segment } from "../lang";
import { createEditor } from "../ui/editor";
import { escapeHtml } from "../ui/highlight";
import { icon } from "../ui/icons";
import { createMenuButton, type MenuItem } from "../ui/menu";
import type { Toaster } from "../ui/toast";
import { createView2D, type DrawingView } from "../ui/view2d";
import { createView3D, type View3D } from "../ui/view3d";
import { checkChallenge, targetDrawing, type Challenge, type Progress } from "./challenges";
import type { Controller, ControllerState } from "./controller";
import { EXAMPLES } from "./examples";
import { programFileName, readProgramFile, slug } from "./files";
import { encodePermalink } from "./share";
import type { Workspace } from "./workspace";
import { plural } from "../lang/values";

const SPEED_LABELS = ["Bardzo wolno", "Wolno", "Średnio", "Szybko", "Bardzo szybko", "Od razu"];

export interface StudioDeps {
  workspace: Workspace;
  controller: Controller;
  progress: Progress;
  toaster: Toaster;
  store: { getItem(k: string): string | null; setItem(k: string, v: string): void };
  keyLabel: (combo: string) => string;
  /** Called whenever the studio's mode changes (the shell shows it). */
  onModeChange: (mode: Mode) => void;
  /** Called when the challenge list may need refreshing. */
  onProgress: () => void;
}

export interface Studio {
  readonly el: HTMLElement;
  readonly mode: Mode;
  setMode(mode: Mode): void;
  /** Opens a challenge in the studio, or the learner's draft when null. */
  openChallenge(c: Challenge | null): void;
  /** Replaces the draft (stashing the learner's own work) and optionally runs it. */
  load(source: string, mode: Mode, how: { run: "animate" | "instant" | "none"; notice?: string }): RunResult | null;
  run(): void;
  step(): void;
  togglePause(): void;
  reset(): void;
  /** Re-reads theme colours into the canvases. */
  repaint(): void;
  show(): void;
}

export function createStudio(deps: StudioDeps): Studio {
  const { workspace, controller, progress, toaster } = deps;
  let mode: Mode = workspace.mode;
  let challenge: Challenge | null = null;

  const el = document.createElement("section");
  el.className = "studio";
  el.setAttribute("aria-label", "Studio");
  el.innerHTML = `
    <div class="toolrow" role="toolbar" aria-label="Wykonanie programu">
      <div class="tool-group">
        <button type="button" class="btn btn-primary" data-act="run" aria-keyshortcuts="Control+Enter Meta+Enter">${icon("play")}<span class="btn-label">Uruchom</span></button>
        <button type="button" class="btn" data-act="step" aria-keyshortcuts="Control+Shift+Enter Meta+Shift+Enter">${icon("step")}<span class="btn-label">Krok</span></button>
        <button type="button" class="btn" data-act="pause" aria-keyshortcuts="Control+. Meta+.">${icon("pause")}<span class="btn-label">Pauza</span></button>
        <button type="button" class="btn" data-act="reset" aria-keyshortcuts="Control+Shift+Backspace Meta+Shift+Backspace">${icon("reset")}<span class="btn-label">Od nowa</span></button>
      </div>
      <label class="speed">
        <span class="speed-label">Tempo</span>
        <input type="range" min="1" max="${controller.maxSpeed}" step="1" />
        <output class="speed-value"></output>
      </label>
      <div class="tool-group tool-end"></div>
    </div>
    <div class="pane-switch" role="tablist" aria-label="Widok na telefonie">
      <button type="button" role="tab" id="tab-code" aria-controls="pane-code" aria-selected="true">${icon("code")}Kod</button>
      <button type="button" role="tab" id="tab-view" aria-controls="pane-view" aria-selected="false" tabindex="-1">${icon("drawing")}Rysunek</button>
    </div>
    <div class="work" data-pane="code">
      <section class="code-pane" id="pane-code" aria-label="Program" role="tabpanel" aria-labelledby="tab-code">
        <div class="challenge-strip" hidden></div>
        <div class="code-head">
          <span class="bullet" aria-hidden="true"></span>
          <h1 class="code-title"></h1>
          <span class="code-hint"></span>
        </div>
        <div class="editor-host"></div>
        <div class="status-band" id="status-band" data-tone="idle">
          <p class="status-text" aria-live="polite"></p>
          <button type="button" class="btn btn-small status-action" hidden>Pokaż w kodzie</button>
        </div>
      </section>
      <section class="view-pane" id="pane-view" aria-label="Rysunek" role="tabpanel" aria-labelledby="tab-view">
        <div class="view-host"></div>
        <div class="readout" aria-live="off"></div>
        <div class="view-controls" role="group" aria-label="Widok rysunku">
          <button type="button" class="btn btn-icon" data-view="in" aria-label="Powiększ" title="Powiększ">${icon("zoomIn")}</button>
          <button type="button" class="btn btn-icon" data-view="out" aria-label="Pomniejsz" title="Pomniejsz">${icon("zoomOut")}</button>
          <button type="button" class="btn btn-icon" data-view="fit" aria-label="Dopasuj widok do rysunku" title="Dopasuj do rysunku">${icon("fit")}</button>
          <button type="button" class="btn btn-icon" data-view="reset" aria-label="Widok początkowy" title="Widok początkowy">${icon("center")}</button>
        </div>
      </section>
    </div>
    <input type="file" class="file-input" accept=".logo,.txt,text/plain" hidden />`;

  const $ = <T extends HTMLElement>(sel: string) => el.querySelector<T>(sel)!;
  const btn = (act: string) => $<HTMLButtonElement>(`[data-act="${act}"]`);
  const work = $<HTMLElement>(".work");
  const strip = $<HTMLElement>(".challenge-strip");
  const statusBand = $<HTMLElement>(".status-band");
  const statusText = $<HTMLElement>(".status-text");
  const statusAction = $<HTMLButtonElement>(".status-action");
  const readout = $<HTMLElement>(".readout");
  const viewHost = $<HTMLElement>(".view-host");
  const fileInput = $<HTMLInputElement>(".file-input");
  const speedInput = $<HTMLInputElement>(".speed input");
  const speedOut = $<HTMLOutputElement>(".speed-value");

  // Shortcut hints on the buttons.
  const hints: Record<string, string> = {
    run: "Ctrl+Enter",
    step: "Ctrl+Shift+Enter",
    pause: "Ctrl+.",
    reset: "Ctrl+Shift+Backspace",
  };
  for (const [act, combo] of Object.entries(hints)) btn(act).title = `${btn(act).textContent!.trim()} (${deps.keyLabel(combo)})`;

  const editor = createEditor({ describedBy: "status-band" });
  $(".editor-host").appendChild(editor.el);

  // Views: 2D at once, 3D on first use (it opens a WebGL context).
  const view2d = createView2D();
  let view3d: View3D | null = null;
  const view = (): DrawingView => (mode === "3d" ? (view3d ??= createView3D()) : view2d);
  const mountView = () => {
    const v = view();
    if (v.el.parentElement !== viewHost) {
      viewHost.replaceChildren(v.el);
    }
    el.classList.toggle("view-off", !v.available);
  };

  // Speed.
  const savedSpeed = Number(deps.store.getItem("logomocja:speed"));
  controller.setSpeed(savedSpeed >= 1 ? savedSpeed : 3);
  const showSpeed = () => {
    speedInput.value = String(controller.speed);
    speedOut.textContent = SPEED_LABELS[controller.speed - 1];
    speedInput.setAttribute("aria-valuetext", SPEED_LABELS[controller.speed - 1]);
  };
  speedInput.addEventListener("input", () => {
    controller.setSpeed(Number(speedInput.value));
    deps.store.setItem("logomocja:speed", String(controller.speed));
    showSpeed();
  });
  showSpeed();

  // Title of what is in the editor.
  const programTitle = () => {
    if (challenge) return challenge.title;
    const ex = EXAMPLES.find((e) => e.mode === mode && e.source === editor.value);
    return ex ? ex.name : "Szkic";
  };
  const renderHead = () => {
    const bullet = $<HTMLElement>(".code-head .bullet");
    bullet.textContent = mode.toUpperCase();
    bullet.className = `bullet bullet-${mode}`;
    const ex = !challenge && EXAMPLES.find((e) => e.mode === mode && e.source === editor.value);
    $(".code-title").textContent = challenge ? `Wyzwanie: ${challenge.title}` : ex ? `Przykład: ${ex.name}` : `Szkic ${mode.toUpperCase()}`;
    $(".code-hint").textContent = challenge ? "zapisuje się samo" : "zapisuje się samo w tej przeglądarce";
  };

  // ---- Menus -------------------------------------------------------------
  const toolEnd = $<HTMLElement>(".tool-end");
  const examplesMenu = createMenuButton({
    label: "Przykłady",
    icon: "list",
    className: "menu-examples",
    items: () => {
      const items: MenuItem[] = EXAMPLES.map((e) => ({
        label: e.name,
        detail: e.description,
        badge: { text: e.mode.toUpperCase(), mode: e.mode },
        group: e.mode === "2d" ? "Na płaszczyźnie (2D)" : "W przestrzeni (3D)",
        action: () => {
          api.openChallenge(null);
          api.load(e.source, e.mode, { run: "animate", notice: `Wczytano przykład „${e.name}”.` });
        },
      }));
      const stash = workspace.stash;
      if (stash) {
        items.push({
          label: "Przywróć poprzedni szkic",
          detail: `Szkic ${stash.mode.toUpperCase()} sprzed wczytania przykładu`,
          icon: "restore",
          group: "Schowek",
          action: () => restoreStash(),
        });
      }
      return items;
    },
  });
  const fileMenu = createMenuButton({
    label: "Plik",
    icon: "file",
    className: "menu-file",
    items: () => [
      { label: "Otwórz plik .logo…", icon: "open", action: () => fileInput.click() },
      { label: "Pobierz program (.logo)", icon: "download", action: downloadProgram },
      { label: "Zapisz rysunek jako PNG", icon: "image", action: exportPng, disabled: !view().available },
    ],
  });
  const shareBtn = document.createElement("button");
  shareBtn.type = "button";
  shareBtn.className = "btn btn-quiet";
  shareBtn.innerHTML = `${icon("link")}<span class="btn-label">Udostępnij</span>`;
  shareBtn.addEventListener("click", () => share());
  toolEnd.append(examplesMenu.el, fileMenu.el, shareBtn);

  // ---- Status --------------------------------------------------------------
  const setStatus = (tone: string, text: string, action?: () => void) => {
    statusBand.dataset.tone = tone;
    statusText.innerHTML = text;
    statusAction.hidden = !action;
    statusAction.onclick = action ?? null;
  };

  const ops = (n: number) => plural(n, "operacja", "operacje", "operacji");
  const segs = (n: number) => plural(n, "odcinek", "odcinki", "odcinków");

  const renderStatus = (s: ControllerState) => {
    switch (s.status) {
      case "idle":
        setStatus("idle", `Gotowe do uruchomienia. Naciśnij <b>Uruchom</b> albo <kbd>${deps.keyLabel("Ctrl+Enter")}</kbd>.`);
        break;
      case "running":
        setStatus("running", `Działa · wiersz ${s.current?.line ?? 1} · ${ops(s.ops)}`);
        break;
      case "paused":
        setStatus("paused", `Pauza po wierszu ${s.current?.line ?? "–"} · ${ops(s.ops)}. <b>Krok</b> wykona następne polecenie.`);
        break;
      case "done":
        setStatus("done", `Gotowe: ${segs(s.segments.length)}, ${ops(s.ops)}.`);
        break;
      case "stopped":
        setStatus("stopped", "Zatrzymano, bo program zmienił się w trakcie działania. Uruchom go ponownie.");
        break;
      case "error": {
        const e = s.error!;
        const kept = s.segments.length ? ` Rysunek do miejsca błędu został (${segs(s.segments.length)}).` : "";
        setStatus(
          "error",
          `<b>Wiersz ${e.line}, kolumna ${e.column}:</b> ${escapeHtml(e.message)}${kept}`,
          () => editor.focusAt(e.line, e.column),
        );
        break;
      }
    }
  };

  const fmt = (v: number) => {
    const r = Math.round(v * 10) / 10;
    return (r === 0 ? 0 : r).toLocaleString("pl-PL", { maximumFractionDigits: 1 });
  };
  const renderReadout = (s: ControllerState) => {
    const t = s.turtle;
    const az = ((Math.atan2(t.heading[0], t.heading[1]) * 180) / Math.PI + 360) % 360;
    const parts = [`x ${fmt(t.pos[0])}`, `y ${fmt(t.pos[1])}`];
    if (mode === "3d") parts.push(`z ${fmt(t.pos[2])}`);
    let dir = `kierunek ${fmt(az)}°`;
    if (mode === "3d") dir += ` · nachylenie ${fmt((Math.asin(Math.max(-1, Math.min(1, t.heading[2]))) * 180) / Math.PI)}°`;
    readout.innerHTML = `<span class="ro-pos">${parts.join(" · ")}</span><span class="ro-dir">${dir}</span><span class="ro-pen"><span class="swatch" style="--swatch:${t.color}"></span>${t.penDown ? "pisak w dół" : "pisak w górze"} · ${t.width} · ${segs(s.segments.length)}</span>`;
  };

  const renderButtons = (s: ControllerState) => {
    const pause = btn("pause");
    const paused = s.status === "paused";
    pause.innerHTML = `${icon(paused ? "play" : "pause")}<span class="btn-label">${paused ? "Wznów" : "Pauza"}</span>`;
    pause.disabled = s.status !== "running" && !paused;
    pause.title = `${paused ? "Wznów" : "Pauza"} (${deps.keyLabel("Ctrl+.")})`;
    btn("reset").disabled = s.status === "idle";
    el.dataset.status = s.status;
  };

  let lastStatus = "";
  controller.subscribe((s) => {
    const v = view();
    v.setSegments(s.segments);
    v.setTurtle(s.turtle);
    if (s.status === "running" || s.status === "paused" || s.status === "done") v.follow();
    const settled = s.status !== "running";
    editor.setCurrent(s.status === "running" || s.status === "paused" ? s.current : null);
    if (settled || s.status !== lastStatus) {
      editor.setVisits(s.status === "idle" || s.status === "stopped" ? null : s.visits);
      editor.setError(s.status === "error" ? s.error : null);
    }
    if (s.status === "error" || s.status !== lastStatus || s.status === "running") renderStatus(s);
    renderReadout(s);
    renderButtons(s);
    lastStatus = s.status;
  });

  // ---- Editing -------------------------------------------------------------
  editor.onInput((value) => {
    if (challenge) progress.saveSource(challenge.id, value);
    else workspace.edit(value);
    controller.sourceEdited();
    renderHead();
    if (challenge) setChallengeResult(null);
  });

  // ---- Actions -------------------------------------------------------------
  const isPhone = () => window.matchMedia?.("(max-width: 759px)").matches ?? false;
  const showPane = (pane: "code" | "view") => {
    work.dataset.pane = pane;
    $("#tab-code").setAttribute("aria-selected", String(pane === "code"));
    $("#tab-view").setAttribute("aria-selected", String(pane === "view"));
    $("#tab-code").tabIndex = pane === "code" ? 0 : -1;
    $("#tab-view").tabIndex = pane === "view" ? 0 : -1;
    if (pane === "view") view().render();
  };
  $("#tab-code").addEventListener("click", () => showPane("code"));
  $("#tab-view").addEventListener("click", () => showPane("view"));
  $(".pane-switch").addEventListener("keydown", (e) => {
    if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
      const next = work.dataset.pane === "code" ? "view" : "code";
      showPane(next);
      $(`#tab-${next}`).focus();
    }
  });

  const run = () => {
    view().release();
    controller.run(editor.value, mode);
    if (isPhone() && controller.state.status !== "error") showPane("view");
  };
  const step = () => {
    controller.step(editor.value, mode);
  };
  const togglePause = () => {
    if (controller.state.status === "running") controller.pause();
    else if (controller.state.status === "paused") controller.resume();
  };
  const reset = () => {
    controller.reset();
    view().release();
  };
  btn("run").addEventListener("click", run);
  btn("step").addEventListener("click", step);
  btn("pause").addEventListener("click", togglePause);
  btn("reset").addEventListener("click", reset);

  el.querySelector(".view-controls")!.addEventListener("click", (e) => {
    const b = (e.target as HTMLElement).closest<HTMLElement>("[data-view]");
    if (!b) return;
    const v = view();
    ({ in: () => v.zoomBy(1.25), out: () => v.zoomBy(0.8), fit: () => v.fit(), reset: () => v.resetView() })[b.dataset.view as "in"]();
  });

  // ---- Files and sharing ---------------------------------------------------
  const download = (blob: Blob, name: string) => {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  function downloadProgram() {
    const name = programFileName(programTitle() === "Szkic" ? "program" : programTitle(), mode);
    download(new Blob([editor.value], { type: "text/plain;charset=utf-8" }), name);
    toaster.show(`Pobrano plik ${name}.`);
  }
  async function exportPng() {
    view().render();
    const blob = await view().toPNG();
    if (!blob) {
      toaster.show("Nie udało się zapisać rysunku jako PNG.");
      return;
    }
    const name = `${slug(programTitle() === "Szkic" ? "rysunek" : programTitle()) || "rysunek"}-${mode}.png`;
    download(blob, name);
    toaster.show(`Zapisano rysunek: ${name}.`);
  }
  fileInput.addEventListener("change", async () => {
    const f = fileInput.files?.[0];
    fileInput.value = "";
    if (!f) return;
    if (f.size > 200_000) {
      toaster.show("Ten plik jest za duży na program Logo (limit to 50 000 znaków).");
      return;
    }
    const text = await f.text();
    const { source, mode: m } = readProgramFile(f.name, text, mode);
    api.openChallenge(null);
    api.load(source, m, { run: "animate", notice: `Otwarto plik ${f.name}.` });
  });

  async function share() {
    const url = `${location.origin}${location.pathname}${encodePermalink(editor.value, mode)}`;
    let copied = false;
    try {
      await navigator.clipboard.writeText(url);
      copied = true;
    } catch {
      copied = false;
    }
    if (copied) {
      toaster.show("Skopiowano link do programu. Kto go otworzy, zobaczy ten program i jego rysunek.");
    } else {
      history.replaceState(null, "", url);
      toaster.show("Link do programu jest teraz w pasku adresu — skopiuj go stamtąd.");
    }
  }

  function restoreStash() {
    const s = workspace.stash;
    if (!s) return;
    api.openChallenge(null);
    workspace.restoreStash();
    setModeInternal(workspace.mode);
    editor.value = workspace.source;
    controller.reset();
    renderHead();
    toaster.show("Przywrócono poprzedni szkic.");
  }

  // ---- Challenges ------------------------------------------------------------
  const setChallengeResult = (r: { passed: boolean; reason: string } | null) => {
    const out = strip.querySelector<HTMLElement>(".ch-result");
    if (!out) return;
    out.dataset.tone = r ? (r.passed ? "pass" : "fail") : "";
    out.innerHTML = r ? `${icon(r.passed ? "check" : "cross", 18)}<span>${escapeHtml(r.reason)}</span>` : "";
  };
  const renderStrip = () => {
    if (!challenge) {
      strip.hidden = true;
      strip.innerHTML = "";
      return;
    }
    const c = challenge;
    const passed = progress.get(c.id).passed;
    strip.hidden = false;
    strip.innerHTML = `
      <div class="ch-head">
        <a class="btn btn-small btn-quiet" href="#/wyzwania">${icon("arrowLeft", 16)}<span>Wszystkie wyzwania</span></a>
        <span class="ch-badge" data-passed="${passed}">${passed ? `${icon("check", 16)}Zaliczone` : "Do zrobienia"}</span>
      </div>
      <p class="ch-task">${escapeHtml(c.task)}</p>
      <details class="ch-hint"><summary>Podpowiedź</summary><p>${escapeHtml(c.hint)}</p></details>
      <div class="ch-actions">
        <button type="button" class="btn btn-check">${icon("target")}<span>Sprawdź</span></button>
        <button type="button" class="btn btn-quiet btn-small ch-leave">Wróć do szkicu</button>
        <p class="ch-result" role="status"></p>
      </div>`;
    strip.querySelector(".btn-check")!.addEventListener("click", () => {
      const result = checkChallenge(c, editor.value);
      controller.finish(editor.value, mode);
      view().fit();
      progress.record(c.id, result.passed, editor.value);
      renderStrip();
      setChallengeResult(result);
      deps.onProgress();
      if (isPhone()) showPane("view");
    });
    strip.querySelector(".ch-leave")!.addEventListener("click", () => {
      location.hash = "#/";
    });
  };

  // ---- Mode --------------------------------------------------------------------
  const setModeInternal = (m: Mode) => {
    mode = m;
    document.documentElement.dataset.mode = m;
    editor.setRouteMode(m);
    mountView();
    deps.onModeChange(m);
  };

  const showDraft = () => {
    editor.value = workspace.source;
    controller.reset();
    view().setGhost(null);
    renderHead();
  };

  const api: Studio = {
    el,
    get mode() {
      return mode;
    },
    setMode(m) {
      if (challenge) {
        challenge = null;
        renderStrip();
        if (location.hash.startsWith("#/wyzwania")) history.replaceState(null, "", "#/");
      }
      if (m === mode && editor.value === workspace.source) return;
      workspace.setMode(m);
      setModeInternal(m);
      showDraft();
      view().resetView();
    },
    openChallenge(c) {
      if (c === challenge) return;
      challenge = c;
      if (c) {
        setModeInternal(c.mode);
        editor.value = progress.get(c.id).source ?? c.starter;
        controller.reset();
        view().setGhost(targetDrawing(c));
        view().fit();
      } else {
        setModeInternal(workspace.mode);
        showDraft();
        view().resetView();
      }
      renderStrip();
      renderHead();
    },
    load(source, m, how) {
      const { stashed } = workspace.load(source, m);
      setModeInternal(m);
      editor.value = source;
      view().setGhost(null);
      renderHead();
      if (how.notice) {
        const msg = stashed ? `${how.notice} Twój poprzedni szkic jest w schowku.` : how.notice;
        toaster.show(msg, stashed ? { label: "Przywróć", run: restoreStash } : undefined);
      }
      if (how.run === "animate") {
        controller.reset();
        view().resetView();
        run();
        return null;
      }
      if (how.run === "instant") {
        const result = controller.finish(source, m);
        view().fit();
        view().render();
        return result;
      }
      controller.reset();
      return null;
    },
    run,
    step,
    togglePause,
    reset,
    repaint() {
      view2d.render();
      view3d?.render();
    },
    show() {
      mountView();
      requestAnimationFrame(() => view().render());
    },
  };

  setModeInternal(mode);
  showDraft();
  showPane("code");
  requestAnimationFrame(() => view().resetView());
  return api;
}

export type { Segment };

tool_use_result.content:
import type { Mode, RunResult, Segment } from "../lang";
import { createEditor } from "../ui/editor";
import { escapeHtml } from "../ui/highlight";
import { icon } from "../ui/icons";
import { createMenuButton, type MenuItem } from "../ui/menu";
import type { Toaster } from "../ui/toast";
import { createView2D, type DrawingView } from "../ui/view2d";
import { createView3D, type View3D } from "../ui/view3d";
import { checkChallenge, targetDrawing, type Challenge, type Progress } from "./challenges";
import type { Controller, ControllerState } from "./controller";
import { EXAMPLES } from "./examples";
import { programFileName, readProgramFile, slug } from "./files";
import { encodePermalink } from "./share";
import type { Workspace } from "./workspace";
import { plural } from "../lang/values";

const SPEED_LABELS = ["Bardzo wolno", "Wolno", "Średnio", "Szybko", "Bardzo szybko", "Od razu"];

export interface StudioDeps {
  workspace: Workspace;
  controller: Controller;
  progress: Progress;
  toaster: Toaster;
  store: { getItem(k: string): string | null; setItem(k: string, v: string): void };
  keyLabel: (combo: string) => string;
  /** Called whenever the studio's mode changes (the shell shows it). */
  onModeChange: (mode: Mode) => void;
  /** Called when the challenge list may need refreshing. */
  onProgress: () => void;
}

export interface Studio {
  readonly el: HTMLElement;
  readonly mode: Mode;
  setMode(mode: Mode): void;
  /** Opens a challenge in the studio, or the learner's draft when null. */
  openChallenge(c: Challenge | null): void;
  /** Replaces the draft (stashing the learner's own work) and optionally runs it. */
  load(source: string, mode: Mode, how: { run: "animate" | "instant" | "none"; notice?: string }): RunResult | null;
  run(): void;
  step(): void;
  togglePause(): void;
  reset(): void;
  /** Re-reads theme colours into the canvases. */
  repaint(): void;
  show(): void;
}

export function createStudio(deps: StudioDeps): Studio {
  const { workspace, controller, progress, toaster } = deps;
  let mode: Mode = workspace.mode;
  let challenge: Challenge | null = null;

  const el = document.createElement("section");
  el.className = "studio";
  el.setAttribute("aria-label", "Studio");
  el.innerHTML = `
    <div class="toolrow" role="toolbar" aria-label="Wykonanie programu">
      <div class="tool-group">
        <button type="button" class="btn btn-primary" data-act="run" aria-keyshortcuts="Control+Enter Meta+Enter">${icon("play")}<span class="btn-label">Uruchom</span></button>
        <button type="button" class="btn" data-act="step" aria-keyshortcuts="Control+Shift+Enter Meta+Shift+Enter">${icon("step")}<span class="btn-label">Krok</span></button>
        <button type="button" class="btn" data-act="pause" aria-keyshortcuts="Control+. Meta+.">${icon("pause")}<span class="btn-label">Pauza</span></button>
        <button type="button" class="btn" data-act="reset" aria-keyshortcuts="Control+Shift+Backspace Meta+Shift+Backspace">${icon("reset")}<span class="btn-label">Od nowa</span></button>
      </div>
      <label class="speed">
        <span class="speed-label">Tempo</span>
        <input type="range" min="1" max="${controller.maxSpeed}" step="1" />
        <output class="speed-value"></output>
      </label>
      <div class="tool-group tool-end"></div>
    </div>
    <div class="pane-switch" role="tablist" aria-label="Widok na telefonie">
      <button type="button" role="tab" id="tab-code" aria-controls="pane-code" aria-selected="true">${icon("code")}Kod</button>
      <button type="button" role="tab" id="tab-view" aria-controls="pane-view" aria-selected="false" tabindex="-1">${icon("drawing")}Rysunek</button>
    </div>
    <div class="work" data-pane="code">
      <section class="code-pane" id="pane-code" aria-label="Program" role="tabpanel" aria-labelledby="tab-code">
        <div class="challenge-strip" hidden></div>
        <div class="code-head">
          <span class="bullet" aria-hidden="true"></span>
          <h1 class="code-title"></h1>
          <span class="code-hint"></span>
        </div>
        <div class="editor-host"></div>
        <div class="status-band" id="status-band" data-tone="idle">
          <p class="status-text" aria-live="polite"></p>
          <button type="button" class="btn btn-small status-action" hidden>Pokaż w kodzie</button>
        </div>
      </section>
      <section class="view-pane" id="pane-view" aria-label="Rysunek" role="tabpanel" aria-labelledby="tab-view">
        <div class="view-host"></div>
        <div class="readout" aria-live="off"></div>
        <div class="view-controls" role="group" aria-label="Widok rysunku">
          <button type="button" class="btn btn-icon" data-view="in" aria-label="Powiększ" title="Powiększ">${icon("zoomIn")}</button>
          <button type="button" class="btn btn-icon" data-view="out" aria-label="Pomniejsz" title="Pomniejsz">${icon("zoomOut")}</button>
          <button type="button" class="btn btn-icon" data-view="fit" aria-label="Dopasuj widok do rysunku" title="Dopasuj do rysunku">${icon("fit")}</button>
          <button type="button" class="btn btn-icon" data-view="reset" aria-label="Widok początkowy" title="Widok początkowy">${icon("center")}</button>
        </div>
      </section>
    </div>
    <input type="file" class="file-input" accept=".logo,.txt,text/plain" hidden />`;

  const $ = <T extends HTMLElement>(sel: string) => el.querySelector<T>(sel)!;
  const btn = (act: string) => $<HTMLButtonElement>(`[data-act="${act}"]`);
  const work = $<HTMLElement>(".work");
  const strip = $<HTMLElement>(".challenge-strip");
  const statusBand = $<HTMLElement>(".status-band");
  const statusText = $<HTMLElement>(".status-text");
  const statusAction = $<HTMLButtonElement>(".status-action");
  const readout = $<HTMLElement>(".readout");
  const viewHost = $<HTMLElement>(".view-host");
  const fileInput = $<HTMLInputElement>(".file-input");
  const speedInput = $<HTMLInputElement>(".speed input");
  const speedOut = $<HTMLOutputElement>(".speed-value");

  // Shortcut hints on the buttons.
  const hints: Record<string, string> = {
    run: "Ctrl+Enter",
    step: "Ctrl+Shift+Enter",
    pause: "Ctrl+.",
    reset: "Ctrl+Shift+Backspace",
  };
  for (const [act, combo] of Object.entries(hints)) btn(act).title = `${btn(act).textContent!.trim()} (${deps.keyLabel(combo)})`;

  const editor = createEditor({ describedBy: "status-band" });
  $(".editor-host").appendChild(editor.el);

  // Views: 2D at once, 3D on first use (it opens a WebGL context).
  const view2d = createView2D();
  let view3d: View3D | null = null;
  const view = (): DrawingView => (mode === "3d" ? (view3d ??= createView3D()) : view2d);
  const mountView = () => {
    const v = view();
    if (v.el.parentElement !== viewHost) {
      viewHost.replaceChildren(v.el);
    }
    el.classList.toggle("view-off", !v.available);
  };

  // Speed.
  const savedSpeed = Number(deps.store.getItem("logomocja:speed"));
  controller.setSpeed(savedSpeed >= 1 ? savedSpeed : 3);
  const showSpeed = () => {
    speedInput.value = String(controller.speed);
    speedOut.textContent = SPEED_LABELS[controller.speed - 1];
    speedInput.setAttribute("aria-valuetext", SPEED_LABELS[controller.speed - 1]);
  };
  speedInput.addEventListener("input", () => {
    controller.setSpeed(Number(speedInput.value));
    deps.store.setItem("logomocja:speed", String(controller.speed));
    showSpeed();
  });
  showSpeed();

  // Title of what is in the editor.
  const programTitle = () => {
    if (challenge) return challenge.title;
    const ex = EXAMPLES.find((e) => e.mode === mode && e.source === editor.value);
    return ex ? ex.name : "Szkic";
  };
  const renderHead = () => {
    const bullet = $<HTMLElement>(".code-head .bullet");
    bullet.textContent = mode.toUpperCase();
    bullet.className = `bullet bullet-${mode}`;
    const ex = !challenge && EXAMPLES.find((e) => e.mode === mode && e.source === editor.value);
    $(".code-title").textContent = challenge ? `Wyzwanie: ${challenge.title}` : ex ? `Przykład: ${ex.name}` : `Szkic ${mode.toUpperCase()}`;
    $(".code-hint").textContent = challenge ? "zapisuje się samo" : "zapisuje się samo w tej przeglądarce";
  };

  // ---- Menus -------------------------------------------------------------
  const toolEnd = $<HTMLElement>(".tool-end");
  const examplesMenu = createMenuButton({
    label: "Przykłady",
    icon: "list",
    className: "menu-examples",
    items: () => {
      const items: MenuItem[] = EXAMPLES.map((e) => ({
        label: e.name,
        detail: e.description,
        badge: { text: e.mode.toUpperCase(), mode: e.mode },
        group: e.mode === "2d" ? "Na płaszczyźnie (2D)" : "W przestrzeni (3D)",
        action: () => {
          api.openChallenge(null);
          api.load(e.source, e.mode, { run: "animate", notice: `Wczytano przykład „${e.name}”.` });
        },
      }));
      const stash = workspace.stash;
      if (stash) {
        items.push({
          label: "Przywróć poprzedni szkic",
          detail: `Szkic ${stash.mode.toUpperCase()} sprzed wczytania przykładu`,
          icon: "restore",
          group: "Schowek",
          action: () => restoreStash(),
        });
      }
      return items;
    },
  });
  const fileMenu = createMenuButton({
    label: "Plik",
    icon: "file",
    className: "menu-file",
    items: () => [
      { label: "Otwórz plik .logo…", icon: "open", action: () => fileInput.click() },
      { label: "Pobierz program (.logo)", icon: "download", action: downloadProgram },
      { label: "Zapisz rysunek jako PNG", icon: "image", action: exportPng, disabled: !view().available },
    ],
  });
  const shareBtn = document.createElement("button");
  shareBtn.type = "button";
  shareBtn.className = "btn btn-quiet";
  shareBtn.innerHTML = `${icon("link")}<span class="btn-label">Udostępnij</span>`;
  shareBtn.addEventListener("click", () => share());
  toolEnd.append(examplesMenu.el, fileMenu.el, shareBtn);

  // ---- Status --------------------------------------------------------------
  const setStatus = (tone: string, text: string, action?: () => void) => {
    statusBand.dataset.tone = tone;
    statusText.innerHTML = text;
    statusAction.hidden = !action;
    statusAction.onclick = action ?? null;
  };

  const ops = (n: number) => plural(n, "operacja", "operacje", "operacji");
  const segs = (n: number) => plural(n, "odcinek", "odcinki", "odcinków");

  const renderStatus = (s: ControllerState) => {
    switch (s.status) {
      case "idle":
        setStatus("idle", `Gotowe do uruchomienia. Naciśnij <b>Uruchom</b> albo <kbd>${deps.keyLabel("Ctrl+Enter")}</kbd>.`);
        break;
      case "running":
        setStatus("running", `Działa · wiersz ${s.current?.line ?? 1} · ${ops(s.ops)}`);
        break;
      case "paused":
        setStatus("paused", `Pauza po wierszu ${s.current?.line ?? "–"} · ${ops(s.ops)}. <b>Krok</b> wykona następne polecenie.`);
        break;
      case "done":
        setStatus("done", `Gotowe: ${segs(s.segments.length)}, ${ops(s.ops)}.`);
        break;
      case "stopped":
        setStatus("stopped", "Zatrzymano, bo program zmienił się w trakcie działania. Uruchom go ponownie.");
        break;
      case "error": {
        const e = s.error!;
        const kept = s.segments.length ? ` Rysunek do miejsca błędu został (${segs(s.segments.length)}).` : "";
        setStatus(
          "error",
          `<b>Wiersz ${e.line}, kolumna ${e.column}:</b> ${escapeHtml(e.message)}${kept}`,
          () => editor.focusAt(e.line, e.column),
        );
        break;
      }
    }
  };

  const fmt = (v: number) => {
    const r = Math.round(v * 10) / 10;
    return (r === 0 ? 0 : r).toLocaleString("pl-PL", { maximumFractionDigits: 1 });
  };
  const renderReadout = (s: ControllerState) => {
    const t = s.turtle;
    const az = ((Math.atan2(t.heading[0], t.heading[1]) * 180) / Math.PI + 360) % 360;
    const parts = [`x ${fmt(t.pos[0])}`, `y ${fmt(t.pos[1])}`];
    if (mode === "3d") parts.push(`z ${fmt(t.pos[2])}`);
    let dir = `kierunek ${fmt(az)}°`;
    if (mode === "3d") dir += ` · nachylenie ${fmt((Math.asin(Math.max(-1, Math.min(1, t.heading[2]))) * 180) / Math.PI)}°`;
    readout.innerHTML = `<span class="ro-pos">${parts.join(" · ")}</span><span class="ro-dir">${dir}</span><span class="ro-pen"><span class="swatch" style="--swatch:${t.color}"></span>${t.penDown ? "pisak w dół" : "pisak w górze"} · ${t.width} · ${segs(s.segments.length)}</span>`;
  };

  const renderButtons = (s: ControllerState) => {
    const pause = btn("pause");
    const paused = s.status === "paused";
    pause.innerHTML = `${icon(paused ? "play" : "pause")}<span class="btn-label">${paused ? "Wznów" : "Pauza"}</span>`;
    pause.disabled = s.status !== "running" && !paused;
    pause.title = `${paused ? "Wznów" : "Pauza"} (${deps.keyLabel("Ctrl+.")})`;
    btn("reset").disabled = s.status === "idle";
    el.dataset.status = s.status;
  };

  let lastStatus = "";
  controller.subscribe((s) => {
    const v = view();
    v.setSegments(s.segments);
    v.setTurtle(s.turtle);
    if (s.status === "running" || s.status === "paused" || s.status === "done") v.follow();
    const settled = s.status !== "running";
    editor.setCurrent(s.status === "running" || s.status === "paused" ? s.current : null);
    if (settled || s.status !== lastStatus) {
      editor.setVisits(s.status === "idle" || s.status === "stopped" ? null : s.visits);
      editor.setError(s.status === "error" ? s.error : null);
    }
    if (s.status === "error" || s.status !== lastStatus || s.status === "running") renderStatus(s);
    renderReadout(s);
    renderButtons(s);
    lastStatus = s.status;
  });

  // ---- Editing -------------------------------------------------------------
  editor.onInput((value) => {
    if (challenge) progress.saveSource(challenge.id, value);
    else workspace.edit(value);
    controller.sourceEdited();
    renderHead();
    if (challenge) setChallengeResult(null);
  });

  // ---- Actions -------------------------------------------------------------
  const isPhone = () => window.matchMedia?.("(max-width: 759px)").matches ?? false;
  const showPane = (pane: "code" | "view") => {
    work.dataset.pane = pane;
    $("#tab-code").setAttribute("aria-selected", String(pane === "code"));
    $("#tab-view").setAttribute("aria-selected", String(pane === "view"));
    $("#tab-code").tabIndex = pane === "code" ? 0 : -1;
    $("#tab-view").tabIndex = pane === "view" ? 0 : -1;
    if (pane === "view") view().render();
  };
  $("#tab-code").addEventListener("click", () => showPane("code"));
  $("#tab-view").addEventListener("click", () => showPane("view"));
  $(".pane-switch").addEventListener("keydown", (e) => {
    if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
      const next = work.dataset.pane === "code" ? "view" : "code";
      showPane(next);
      $(`#tab-${next}`).focus();
    }
  });

  const run = () => {
    view().release();
    controller.run(editor.value, mode);
    if (isPhone() && controller.state.status !== "error") showPane("view");
  };
  const step = () => {
    controller.step(editor.value, mode);
  };
  const togglePause = () => {
    if (controller.state.status === "running") controller.pause();
    else if (controller.state.status === "paused") controller.resume();
  };
  const reset = () => {
    controller.reset();
    view().release();
  };
  btn("run").addEventListener("click", run);
  btn("step").addEventListener("click", step);
  btn("pause").addEventListener("click", togglePause);
  btn("reset").addEventListener("click", reset);

  el.querySelector(".view-controls")!.addEventListener("click", (e) => {
    const b = (e.target as HTMLElement).closest<HTMLElement>("[data-view]");
    if (!b) return;
    const v = view();
    ({ in: () => v.zoomBy(1.25), out: () => v.zoomBy(0.8), fit: () => v.fit(), reset: () => v.resetView() })[b.dataset.view as "in"]();
  });

  // ---- Files and sharing ---------------------------------------------------
  const download = (blob: Blob, name: string) => {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  function downloadProgram() {
    const name = programFileName(programTitle() === "Szkic" ? "program" : programTitle(), mode);
    download(new Blob([editor.value], { type: "text/plain;charset=utf-8" }), name);
    toaster.show(`Pobrano plik ${name}.`);
  }
  async function exportPng() {
    view().render();
    const blob = await view().toPNG();
    if (!blob) {
      toaster.show("Nie udało się zapisać rysunku jako PNG.");
      return;
    }
    const name = `${slug(programTitle() === "Szkic" ? "rysunek" : programTitle()) || "rysunek"}-${mode}.png`;
    download(blob, name);
    toaster.show(`Zapisano rysunek: ${name}.`);
  }
  fileInput.addEventListener("change", async () => {
    const f = fileInput.files?.[0];
    fileInput.value = "";
    if (!f) return;
    if (f.size > 200_000) {
      toaster.show("Ten plik jest za duży na program Logo (limit to 50 000 znaków).");
      return;
    }
    const text = await f.text();
    const { source, mode: m } = readProgramFile(f.name, text, mode);
    api.openChallenge(null);
    api.load(source, m, { run: "animate", notice: `Otwarto plik ${f.name}.` });
  });

  async function share() {
    const url = `${location.origin}${location.pathname}${encodePermalink(editor.value, mode)}`;
    let copied = false;
    try {
      await navigator.clipboard.writeText(url);
      copied = true;
    } catch {
      copied = false;
    }
    if (copied) {
      toaster.show("Skopiowano link do programu. Kto go otworzy, zobaczy ten program i jego rysunek.");
    } else {
      history.replaceState(null, "", url);
      toaster.show("Link do programu jest teraz w pasku adresu — skopiuj go stamtąd.");
    }
  }

  function restoreStash() {
    const s = workspace.stash;
    if (!s) return;
    api.openChallenge(null);
    workspace.restoreStash();
    setModeInternal(workspace.mode);
    editor.value = workspace.source;
    controller.reset();
    renderHead();
    toaster.show("Przywrócono poprzedni szkic.");
  }

  // ---- Challenges ------------------------------------------------------------
  const setChallengeResult = (r: { passed: boolean; reason: string } | null) => {
    const out = strip.querySelector<HTMLElement>(".ch-result");
    if (!out) return;
    out.dataset.tone = r ? (r.passed ? "pass" : "fail") : "";
    out.innerHTML = r ? `${icon(r.passed ? "check" : "cross", 18)}<span>${escapeHtml(r.reason)}</span>` : "";
  };
  const renderStrip = () => {
    if (!challenge) {
      strip.hidden = true;
      strip.innerHTML = "";
      return;
    }
    const c = challenge;
    const passed = progress.get(c.id).passed;
    strip.hidden = false;
    strip.innerHTML = `
      <div class="ch-head">
        <a class="btn btn-small btn-quiet" href="#/wyzwania">${icon("arrowLeft", 16)}<span>Wszystkie wyzwania</span></a>
        <span class="ch-badge" data-passed="${passed}">${passed ? `${icon("check", 16)}Zaliczone` : "Do zrobienia"}</span>
      </div>
      <p class="ch-task">${escapeHtml(c.task)}</p>
      <details class="ch-hint"><summary>Podpowiedź</summary><p>${escapeHtml(c.hint)}</p></details>
      <div class="ch-actions">
        <button type="button" class="btn btn-check">${icon("target")}<span>Sprawdź</span></button>
        <button type="button" class="btn btn-quiet btn-small ch-leave">Wróć do szkicu</button>
        <p class="ch-result" role="status"></p>
      </div>`;
    strip.querySelector(".btn-check")!.addEventListener("click", () => {
      const result = checkChallenge(c, editor.value);
      controller.finish(editor.value, mode);
      view().fit();
      progress.record(c.id, result.passed, editor.value);
      renderStrip();
      setChallengeResult(result);
      deps.onProgress();
      if (isPhone()) showPane("view");
    });
    strip.querySelector(".ch-leave")!.addEventListener("click", () => {
      location.hash = "#/";
    });
  };

  // ---- Mode --------------------------------------------------------------------
  const setModeInternal = (m: Mode) => {
    mode = m;
    document.documentElement.dataset.mode = m;
    editor.setRouteMode(m);
    mountView();
    deps.onModeChange(m);
  };

  const showDraft = () => {
    editor.value = workspace.source;
    controller.reset();
    view().setGhost(null);
    renderHead();
  };

  const api: Studio = {
    el,
    get mode() {
      return mode;
    },
    setMode(m) {
      if (challenge) {
        challenge = null;
        renderStrip();
        if (location.hash.startsWith("#/wyzwania")) history.replaceState(null, "", "#/");
      }
      if (m === mode && editor.value === workspace.source) return;
      workspace.setMode(m);
      setModeInternal(m);
      showDraft();
      view().resetView();
    },
    openChallenge(c) {
      if (c === challenge) return;
      challenge = c;
      if (c) {
        setModeInternal(c.mode);
        editor.value = progress.get(c.id).source ?? c.starter;
        controller.reset();
        view().setGhost(targetDrawing(c));
        view().fit();
      } else {
        setModeInternal(workspace.mode);
        showDraft();
        view().resetView();
      }
      renderStrip();
      renderHead();
    },
    load(source, m, how) {
      const { stashed } = workspace.load(source, m);
      setModeInternal(m);
      editor.value = source;
      view().setGhost(null);
      renderHead();
      if (how.notice) {
        const msg = stashed ? `${how.notice} Twój poprzedni szkic jest w schowku.` : how.notice;
