      }
      if (how.run === "animate") {
        controller.reset();
        view().resetView();
        run();
        return null;
      }
      if (how.run === "instant") {
        const result = controller.finish(source, m);
        view().fit();
        view().render();
        return result;
      }
      controller.reset();
      return null;
    },
    run,
    step,
    togglePause,
    reset,
    repaint() {
      view2d.render();
      view3d?.render();
    },
    show() {
      mountView();
      requestAnimationFrame(() => view().render());
    },
  };

  setModeInternal(mode);
  showDraft();
  showPane("code");
