import { escapeHtml, highlight } from "../ui/highlight";
import { icon } from "../ui/icons";
import { CHALLENGES, targetDrawing, type Progress } from "./challenges";
import { COMMAND_ALIASES } from "../lang/commands";
import { DOC_SECTIONS, SHORTCUTS, type DocExample } from "./docs";

/** A small SVG of a drawing; 3D drawings get an oblique projection. */
export function drawingSvg(segments: readonly Segment[], mode: Mode, size = 96): string {
  const project = (p: readonly number[]): [number, number] =>
    mode === "3d" ? [p[0] + p[1] * 0.5, -(p[2] + p[1] * 0.35)] : [p[0], -p[1]];
  const pts = segments.flatMap((s) => [project(s.from), project(s.to)]);
  pts.push([0, 0]);
  const xs = pts.map((p) => p[0]);
  const ys = pts.map((p) => p[1]);
  const minX = Math.min(...xs);
  const minY = Math.min(...ys);
  const w = Math.max(Math.max(...xs) - minX, 1);
  const h = Math.max(Math.max(...ys) - minY, 1);
  const pad = 10;
  const k = (size - pad * 2) / Math.max(w, h);
  const ox = pad + ((size - pad * 2) - w * k) / 2;
  const oy = pad + ((size - pad * 2) - h * k) / 2;
  const tx = (p: [number, number]) => `${(ox + (p[0] - minX) * k).toFixed(1)},${(oy + (p[1] - minY) * k).toFixed(1)}`;
  const lines = segments
    .map((s) => `<line x1="${tx(project(s.from)).split(",")[0]}" y1="${tx(project(s.from)).split(",")[1]}" x2="${tx(project(s.to)).split(",")[0]}" y2="${tx(project(s.to)).split(",")[1]}"/>`)
    .join("");
  const [sx, sy] = tx([0, 0]).split(",");
  return `<svg class="drawing-thumb" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" aria-hidden="true" focusable="false"><g stroke="currentColor" stroke-width="2" stroke-linecap="round">${lines}</g><circle cx="${sx}" cy="${sy}" r="3" class="thumb-start"/></svg>`;
}

export function renderChallengesPage(el: HTMLElement, progress: Progress): void {
  const done = progress.passedCount;
  el.innerHTML = `
    <div class="page-inner">
      <header class="page-head">
        <h1>Wyzwania</h1>
        <p>Każde wyzwanie pokazuje wzór. Napisz program, który go narysuje, i naciśnij <b>Sprawdź</b> — Logomocja porówna twój rysunek ze wzorem, z dokładnością do półtora kroku żółwia.</p>
        <p class="progress-line"><span class="progress-count">Zaliczone: ${done} z ${CHALLENGES.length}</span><span class="progress-track" aria-hidden="true">${CHALLENGES.map((c) => `<span class="${progress.get(c.id).passed ? "is-done" : ""}"></span>`).join("")}</span></p>
      </header>
      <ol class="ch-list">
        ${CHALLENGES.map((c) => {
          const rec = progress.get(c.id);
          const status = rec.passed ? `<span class="ch-status is-done">${icon("check", 16)}Zaliczone</span>` : rec.source && rec.source !== c.starter ? '<span class="ch-status">W trakcie</span>' : '<span class="ch-status">Do zrobienia</span>';
