      })
      .join("");
    return `<section class="doc-section" id="doc-${s.id}" aria-labelledby="h-${s.id}">
      <h2 id="h-${s.id}">${escapeHtml(s.title)}</h2>
      <p class="lead">${escapeHtml(s.intro)}</p>
      ${blocks}${cmds}
    </section>`;
