    <div class="docs">
      <nav class="docs-toc" aria-label="Spis treści dokumentacji">
        <p class="toc-title">Spis treści</p>
        <ol>
          <li><a href="#/dokumentacja/sciaga">Ściąga poleceń</a></li>
          ${DOC_SECTIONS.map((s) => `<li><a href="#/dokumentacja/${s.id}">${escapeHtml(s.title)}</a></li>`).join("")}
          <li><a href="#/dokumentacja/skroty">Skróty klawiszowe</a></li>
        </ol>
      </nav>
      <article class="docs-body">
        <h1>Język Logomocji</h1>
        <p class="lead">Wszystko, co potrafi żółw: polecenia, wyrażenia, zmienne, warunki, procedury i ograniczenia. Każdy przykład możesz od razu uruchomić przyciskiem <b>Wypróbuj</b> — twój szkic trafi wtedy do schowka.</p>
        <section class="doc-section" id="doc-sciaga" aria-labelledby="h-sciaga">
          <h2 id="h-sciaga">Ściąga poleceń</h2>
          <div class="table-wrap"><table class="cheat">
            <thead><tr><th scope="col">Po polsku</th><th scope="col">Po angielsku</th></tr></thead>
            <tbody>${summaryRows.map((r) => `<tr><td>${r.polish.map((a) => `<code>${a}</code>`).join(" ")}</td><td>${r.english.map((a) => `<code>${a}</code>`).join(" ")}</td></tr>`).join("")}
            <tr><td><code>oto</code> … <code>ma:</code> … <code>już</code> <code>juz</code></td><td><code>to</code> … <code>end</code></td></tr>
            <tr><td><code>nrpowt</code></td><td><code>repcount</code></td></tr></tbody>
          </table></div>
        </section>
        ${sections}
        <section class="doc-section" id="doc-skroty" aria-labelledby="h-skroty">
          <h2 id="h-skroty">Skróty klawiszowe</h2>
          <table class="limits"><tbody>${SHORTCUTS.map(([k, v]) => `<tr><th scope="row">${escapeHtml(k)}</th><td><kbd>${escapeHtml(keyLabel(v))}</kbd></td></tr>`).join("")}</tbody></table>
