import { run, type Mode, type RunResult } from "../lang";
import { icon, TURTLE_MARK } from "../ui/icons";
import { createToaster } from "../ui/toast";
import { CHALLENGES, createProgress } from "./challenges";
import { createController, type Scheduler } from "./controller";
import { findExample } from "./examples";
import { renderChallengesPage, renderDocsPage } from "./pages";
import { decodePermalink } from "./share";
import { createStudio } from "./studio";
import { createWorkspace, type KeyValueStore } from "./workspace";

export const VERSION = "1.0.0";

export interface LogomocjaApi {
  version: string;
  run(source: string, mode: Mode): RunResult;
  open(source: string, mode: Mode): Promise<RunResult>;
}

export interface AppDeps {
  storage: KeyValueStore;
  scheduler?: Scheduler;
}

const rafScheduler: Scheduler = {
  request: (cb) => requestAnimationFrame(cb),
  cancel: (h) => cancelAnimationFrame(h),
};

const nextFrame = () => new Promise<void>((r) => requestAnimationFrame(() => r()));

type Route = { name: "studio" } | { name: "challenge"; id: string } | { name: "challenges" } | { name: "docs"; section?: string };

function parseRoute(hash: string): Route {
  const path = hash.replace(/^#\/?/, "").split("?")[0];
  const [head, arg] = path.split("/");
  if (head === "wyzwania") return arg ? { name: "challenge", id: arg } : { name: "challenges" };
  if (head === "dokumentacja") return { name: "docs", section: arg };
  return { name: "studio" };
}

export function mountApp(root: HTMLElement, deps: AppDeps): LogomocjaApi {
  const store = deps.storage;
  const workspace = createWorkspace(store);
  const progress = createProgress(store);
  const controller = createController({ scheduler: deps.scheduler ?? rafScheduler });
  const toaster = createToaster();
  const isMac = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent || "");
  const keyLabel = (combo: string) => (isMac ? combo.replace(/Ctrl/g, "⌘").replace(/Shift/g, "⇧") : combo);

  root.innerHTML = `
    <a class="skip-link" href="#main">Przejdź do treści</a>
    <header class="band">
      <a class="wordmark" href="#/" aria-label="Logomocja — studio">${TURTLE_MARK}<span>Logomocja</span></a>
      <div class="mode-switch" role="radiogroup" aria-label="Tryb rysowania">
        <button type="button" role="radio" data-mode="2d" aria-checked="true" title="Płaszczyzna">2D</button>
        <button type="button" role="radio" data-mode="3d" aria-checked="false" title="Przestrzeń">3D</button>
      </div>
      <nav class="main-nav" aria-label="Główna">
        <a href="#/" data-route="studio">Studio</a>
        <a href="#/wyzwania" data-route="challenges">Wyzwania <span class="nav-count"></span></a>
        <a href="#/dokumentacja" data-route="docs">Dokumentacja</a>
      </nav>
      <button type="button" class="btn btn-icon btn-on-band theme-toggle"></button>
    </header>
    <main id="main" tabindex="-1">
      <div class="route route-studio"></div>
      <div class="route route-challenges page" hidden></div>
      <div class="route route-docs page page-read" hidden></div>
    </main>`;
  root.appendChild(toaster.el);

  const $ = <T extends HTMLElement>(sel: string) => root.querySelector<T>(sel)!;
  const modeButtons = [...root.querySelectorAll<HTMLButtonElement>(".mode-switch [role=radio]")];
  const navCount = $<HTMLElement>(".nav-count");

  const refreshCount = () => {
    navCount.textContent = `${progress.passedCount}/${CHALLENGES.length}`;
    navCount.setAttribute("aria-label", `zaliczone ${progress.passedCount} z ${CHALLENGES.length}`);
  };

  const studio = createStudio({
    workspace,
    controller,
    progress,
    toaster,
    store,
    keyLabel,
    onModeChange(mode) {
      for (const b of modeButtons) {
        const on = b.dataset.mode === mode;
        b.setAttribute("aria-checked", String(on));
        b.tabIndex = on ? 0 : -1;
      }
    },
    onProgress: refreshCount,
  });
  $(".route-studio").appendChild(studio.el);

  // Mode switch: a radio group of line bullets.
  for (const b of modeButtons) {
    b.addEventListener("click", () => {
      if (parseRoute(location.hash).name !== "studio" && parseRoute(location.hash).name !== "challenge") location.hash = "#/";
      studio.setMode(b.dataset.mode as Mode);
    });
    b.addEventListener("keydown", (e) => {
      if (["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(e.key)) {
        e.preventDefault();
        const other = modeButtons.find((x) => x !== b)!;
        other.focus();
        other.click();
      }
    });
  }

  // Theme: follows the system until the learner picks one.
  const themeBtn = $<HTMLButtonElement>(".theme-toggle");
  const media = window.matchMedia?.("(prefers-color-scheme: dark)");
  const effectiveTheme = () => {
    const saved = store.getItem("logomocja:theme");
    if (saved === "light" || saved === "dark") return saved;
    return media?.matches ? "dark" : "light";
  };
  const applyTheme = () => {
    const t = effectiveTheme();
    document.documentElement.dataset.theme = t;
    const next = t === "dark" ? "jasny" : "ciemny";
    themeBtn.innerHTML = icon(t === "dark" ? "sun" : "moon");
    themeBtn.setAttribute("aria-label", `Włącz motyw ${next}`);
    themeBtn.title = `Motyw ${t === "dark" ? "ciemny" : "jasny"} — kliknij, aby włączyć ${next}`;
    document.querySelector('meta[name="theme-color"]')?.setAttribute("content", t === "dark" ? "#0b1222" : "#17223b");
    studio.repaint();
  };
  themeBtn.addEventListener("click", () => {
    store.setItem("logomocja:theme", effectiveTheme() === "dark" ? "light" : "dark");
    applyTheme();
  });
  media?.addEventListener?.("change", applyTheme);
  applyTheme();

  // Routing.
  const challengesEl = $<HTMLElement>(".route-challenges");
  const docsEl = $<HTMLElement>(".route-docs");
  let docsRendered = false;
  docsEl.addEventListener("click", (e) => {
    const b = (e.target as HTMLElement).closest<HTMLElement>("[data-try]");
    if (!b) return;
    const code = decodeURIComponent(b.dataset.try!);
    location.hash = "#/";
    studio.openChallenge(null);
    studio.load(code, b.dataset.mode as Mode, { run: "animate", notice: "Wczytano przykład z dokumentacji." });
  });

  const show = (name: "studio" | "challenges" | "docs") => {
    $(".route-studio").hidden = name !== "studio";
    challengesEl.hidden = name !== "challenges";
    docsEl.hidden = name !== "docs";
    root.querySelector(".band")!.setAttribute("data-route", name);
    for (const a of root.querySelectorAll<HTMLAnchorElement>(".main-nav a")) {
      if (a.dataset.route === name) a.setAttribute("aria-current", "page");
      else a.removeAttribute("aria-current");
    }
  };

  const route = () => {
    const hash = location.hash;
    const shared = decodePermalink(hash);
    if (shared) {
      history.replaceState(null, "", "#/");
      show("studio");
      studio.openChallenge(null);
      studio.load(shared.source, shared.mode, { run: "animate", notice: "Otwarto program z linku." });
      studio.show();
      return;
    }
    const exampleMatch = /^#\/przyklad\/([\w-]+)/.exec(hash);
    if (exampleMatch) {
      history.replaceState(null, "", "#/");
      const ex = findExample(exampleMatch[1]);
      show("studio");
      studio.openChallenge(null);
      if (ex) studio.load(ex.source, ex.mode, { run: "animate", notice: `Wczytano przykład „${ex.name}”.` });
      else toaster.show("Nie ma takiego przykładu.");
      studio.show();
      return;
    }
    const r = parseRoute(hash);
    if (r.name === "studio") {
      show("studio");
      studio.openChallenge(null);
      studio.show();
      document.title = "Logomocja — studio żółwia";
    } else if (r.name === "challenge") {
      const c = CHALLENGES.find((x) => x.id === r.id);
      if (!c) {
        location.hash = "#/wyzwania";
        return;
      }
      show("studio");
      studio.openChallenge(c);
      studio.show();
      document.title = `${c.title} — wyzwanie — Logomocja`;
    } else if (r.name === "challenges") {
      renderChallengesPage(challengesEl, progress);
      show("challenges");
      document.title = "Wyzwania — Logomocja";
    } else {
      if (!docsRendered) {
        renderDocsPage(docsEl, keyLabel);
        docsRendered = true;
      }
      show("docs");
      document.title = "Dokumentacja — Logomocja";
      const target = r.section ? docsEl.querySelector<HTMLElement>(`#doc-${r.section}`) : null;
      if (target) {
        target.scrollIntoView({ block: "start" });
        target.querySelector("h2")?.setAttribute("tabindex", "-1");
        target.querySelector<HTMLElement>("h2")?.focus({ preventScroll: true });
      } else window.scrollTo?.(0, 0);
    }
  };
  window.addEventListener("hashchange", route);

  // Keyboard shortcuts (studio only).
  document.addEventListener("keydown", (e) => {
    if (!$(".route-studio") || $(".route-studio").hidden) return;
    const mod = e.ctrlKey || e.metaKey;
    if (!mod || e.altKey) return;
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      studio.run();
    } else if (e.key === "Enter" && e.shiftKey) {
      e.preventDefault();
      studio.step();
    } else if (e.key === "." && !e.shiftKey) {
      e.preventDefault();
      studio.togglePause();
    } else if (e.key === "Backspace" && e.shiftKey) {
      e.preventDefault();
      studio.reset();
    }
  });

  refreshCount();
  route();

  return {
    version: VERSION,
    run: (source, mode) => run(source, mode),
    async open(source, mode) {
      if (parseRoute(location.hash).name !== "studio" || location.hash.startsWith("#/program")) {
        history.replaceState(null, "", "#/");
        show("studio");
      }
      studio.openChallenge(null);
      const result = studio.load(source, mode, { run: "instant" })!;
      studio.show();
      await nextFrame();
      await nextFrame();
      return result;
    },
  };
}

