      document.title = "Logomocja — studio żółwia";
    } else if (r.name === "challenge") {
      const c = CHALLENGES.find((x) => x.id === r.id);
      if (!c) {
        location.hash = "#/wyzwania";
        return;
      }
      show("studio");
      studio.openChallenge(c);
      studio.show();
      document.title = `${c.title} — wyzwanie — Logomocja`;
    } else if (r.name === "challenges") {
      renderChallengesPage(challengesEl, progress);
      show("challenges");
      document.title = "Wyzwania — Logomocja";
    } else {
      if (!docsRendered) {
        renderDocsPage(docsEl, keyLabel);
        docsRendered = true;
      }
      show("docs");
      document.title = "Dokumentacja — Logomocja";
      const target = r.section ? docsEl.querySelector<HTMLElement>(`#doc-${r.section}`) : null;
      if (target) {
        target.scrollIntoView({ block: "start" });
        target.querySelector("h2")?.setAttribute("tabindex", "-1");
        target.querySelector<HTMLElement>("h2")?.focus({ preventScroll: true });
      } else window.scrollTo?.(0, 0);
    }
  };
  window.addEventListener("hashchange", route);

  // Keyboard shortcuts (studio only).
  document.addEventListener("keydown", (e) => {
    if (!$(".route-studio") || $(".route-studio").hidden) return;
    const mod = e.ctrlKey || e.metaKey;
    if (!mod || e.altKey) return;
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      studio.run();
    } else if (e.key === "Enter" && e.shiftKey) {
      e.preventDefault();
      studio.step();
    } else if (e.key === "." && !e.shiftKey) {
      e.preventDefault();
      studio.togglePause();
    } else if (e.key === "Backspace" && e.shiftKey) {
      e.preventDefault();
      studio.reset();
    }
  });

  refreshCount();
  route();

  return {
    version: VERSION,
    run: (source, mode) => run(source, mode),
    async open(source, mode) {
      if (parseRoute(location.hash).name !== "studio" || location.hash.startsWith("#/program")) {
        history.replaceState(null, "", "#/");
        show("studio");
      }
      studio.openChallenge(null);
      const result = studio.load(source, mode, { run: "instant" })!;
      studio.show();
      await nextFrame();
      await nextFrame();
      return result;
    },
  };
}

