cat >> test/app.test.ts <<'EOF'

function manualClock() {
  let t = 0;
  let queue: ((now: number) => void)[] = [];
  return {
    scheduler: {
      request(cb: (now: number) => void) {
        queue.push(cb);
        return queue.length;
      },
      cancel() {
        queue = [];
      },
    },
    frames(n: number, ms = 100) {
      for (let i = 0; i < n; i++) {
        t += ms;
        const q = queue;
        queue = [];
        q.forEach((cb) => cb(t));
      }
    },
  };
}

function mountWithClock(clock: ReturnType<typeof manualClock>) {
  localStorage.clear();
  location.hash = "";
  document.body.innerHTML = '<div id="app"></div>';
  return mountApp(document.getElementById("app")!, { storage: localStorage, scheduler: clock.scheduler });
}

const type = (text: string) => {
  editor().value = text;
  editor().dispatchEvent(new Event("input", { bubbles: true }));
};
const button = (label: string) =>
  [...document.querySelectorAll<HTMLButtonElement>("button")].find((b) => b.textContent!.trim() === label)!;
const status = () => document.querySelector(".status-text")!.textContent!;

describe("app: running from the controls", () => {
  test("Uruchom, Od nowa and Uruchom again agree with the language contract", () => {
    const clock = manualClock();
    mountWithClock(clock);
    type("powtorz 4 [np 50 pw 90]");
    button("Uruchom").click();
    clock.frames(200);
    expect(status()).toContain("4 odcinki");
    button("Od nowa").click();
    expect(status()).toContain("Gotowe do uruchomienia");
    button("Uruchom").click();
    clock.frames(200);
    expect(status()).toContain("4 odcinki");
  });

  test("Krok runs one statement at a time and marks its line in the gutter", () => {
    const clock = manualClock();
    mountWithClock(clock);
    type("np 10\npw 90\nnp 10");
    button("Krok").click();
    button("Krok").click();
    expect(status()).toContain("wiersz 2");
    expect(document.querySelectorAll(".g-station.is-here").length).toBe(1);
    const rows = [...document.querySelectorAll(".g-row")];
    expect(rows[1].querySelector(".is-here")).not.toBeNull();
  });

  test("a parse error from open() shows the Polish message inline at its line and column, and draws nothing", async () => {
    const api = fresh();
    const r = await api.open("np 10\nnp )", "2d");
    expect(r.error).toMatchObject({ line: 2, column: 4 });
    const bubble = document.querySelector<HTMLElement>(".error-bubble")!;
    expect(bubble.hidden).toBe(false);
    expect(bubble.textContent).toContain("Wiersz 2, kolumna 4");
    expect(document.querySelector(".tok-op.is-error, .is-error")).not.toBeNull();
    expect(editor().getAttribute("aria-invalid")).toBe("true");
  });
});
EOF
