input.content:
/* ---------- Base ---------------------------------------------------------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
}

body {
  background: var(--ground);
  color: var(--ink);
  font: 400 15px/1.5 var(--font-ui);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

* {
  scrollbar-color: var(--rule-strong) transparent;
  scrollbar-width: thin;
}

::selection {
  background: var(--code-sel);
  color: inherit;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

a {
  color: var(--line-strong);
  text-underline-offset: 0.18em;
  text-decoration-thickness: 1px;
}

kbd {
  font: 500 0.85em/1 var(--font-code);
  padding: 2px 6px;
  border: 1px solid var(--rule-strong);
  border-bottom-width: 2px;
  border-radius: var(--radius-s);
  background: var(--surface);
  color: var(--ink);
  white-space: nowrap;
}

code {
  font-family: var(--font-code);
  font-size: 0.94em;
}

.icon {
  flex: none;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

#app {
  min-height: 100dvh;
  display: grid;
  grid-template-rows: auto 1fr;
}

main {
  min-height: 0;
  display: grid;
}

main:focus {
  outline: none;
}

.route[hidden] {
  display: none !important;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  z-index: 100;
  padding: 8px 14px;
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  font-weight: 600;
  box-shadow: var(--shadow-pop);
}

.skip-link:focus {
  top: 8px;
}

/* ---------- Band (the station sign) ----------------------------------------- */

.band {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 20px;
  height: var(--band-h);
  padding: 0 16px;
  background: var(--band);
  color: var(--on-band);
}

.band :focus-visible {
  outline-color: var(--on-band);
}

.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--on-band);
  font: 600 19px/1 var(--font-ui);
  letter-spacing: -0.01em;
  text-decoration: none;
  border-radius: var(--radius);
}

.wordmark .mark {
  flex: none;
}

.mode-switch {
  display: inline-flex;
  gap: 6px;
}

.mode-switch [role="radio"] {
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 30px;
  padding: 0;
  border: 1.5px solid rgba(255, 255, 255, 0.28);
  border-radius: 5px;
  background: transparent;
  color: var(--on-band-muted);
  font: 700 13px/1 var(--font-ui);
  letter-spacing: 0.02em;
  cursor: pointer;
  transition:
    background-color 160ms var(--ease-out),
    border-color 160ms var(--ease-out),
    color 160ms var(--ease-out);
}

.mode-switch [role="radio"]:hover {
  border-color: var(--on-band);
  color: var(--on-band);
}

.mode-switch [data-mode="2d"][aria-checked="true"] {
  background: var(--line-2d);
  border-color: var(--line-2d);
  color: var(--on-line);
}

.mode-switch [data-mode="3d"][aria-checked="true"] {
  background: var(--line-3d);
  border-color: var(--line-3d);
  color: var(--on-line);
}

.band:not([data-route="studio"]) .mode-switch {
  visibility: hidden;
}

.main-nav {
  display: flex;
  gap: 2px;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.main-nav a {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 12px;
  border-radius: var(--radius);
  color: var(--on-band-muted);
  font: 500 15px/1 var(--font-ui);
  text-decoration: none;
  white-space: nowrap;
}

.main-nav a:hover {
  color: var(--on-band);
  background: var(--band-raised);
}

.main-nav a[aria-current="page"] {
  color: var(--on-band);
}

.main-nav a[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: -10px;
  height: 3px;
  border-radius: 2px 2px 0 0;
  background: var(--on-band);
}

.nav-count {
  padding: 2px 6px;
  border-radius: 9px;
  background: var(--band-raised);
  color: var(--on-band-muted);
  font: 500 12px/1.2 var(--font-ui);
  font-variant-numeric: tabular-nums;
}

.theme-toggle {
  margin-left: auto;
}

/* ---------- Buttons ------------------------------------------------------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 36px;
  padding: 0 13px;
  border: 1px solid var(--rule-strong);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  font: 500 14px/1 var(--font-ui);
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
  transition:
    background-color 150ms var(--ease-out),
    border-color 150ms var(--ease-out),
    color 150ms var(--ease-out);
}

.btn:hover {
  background: var(--surface-hover);
}

.btn:active {
  background: var(--rule);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  background: var(--surface);
}

.btn-primary {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--on-line);
  font-weight: 600;
}

.btn-primary:hover {
  background: color-mix(in srgb, var(--primary) 86%, var(--ink));
}

.btn-primary:active {
  background: color-mix(in srgb, var(--primary) 76%, var(--ink));
}

.btn-quiet {
  border-color: transparent;
  background: transparent;
}

.btn-icon {
  width: 36px;
  padding: 0;
}

.btn-small {
  height: 30px;
  padding: 0 10px;
  font-size: 13px;
}

.btn-on-band {
  border-color: transparent;
  background: transparent;
  color: var(--on-band);
}

.btn-on-band:hover {
  background: var(--band-raised);
}

.btn-on-dark {
  border-color: rgba(255, 255, 255, 0.35);
  background: transparent;
  color: var(--on-band);
}

.btn-on-dark:hover {
  background: var(--band-raised);
}

.bullet {
  display: inline-grid;
  place-items: center;
  min-width: 28px;
  height: 22px;
  padding: 0 5px;
  border-radius: 4px;
  background: var(--line);
  color: var(--on-line);
  font: 700 12px/1 var(--font-ui);
  letter-spacing: 0.02em;
}

.bullet-2d {
  background: var(--line-2d);
}

.bullet-3d {
  background: var(--line-3d);
}

/* ---------- Studio layout ----------------------------------------------- */

.studio {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  height: calc(100dvh - var(--band-h));
  min-height: 420px;
}

.toolrow {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 16px;
  padding: 8px 16px;
  background: var(--surface);
  border-bottom: 1px solid var(--rule);
}

.tool-group {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tool-end {
  margin-left: auto;
  gap: 2px;
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--ink-2);
  font-size: 13px;
}

.speed-label {
  font-weight: 500;
}

.speed input {
  width: 120px;
  accent-color: var(--line-strong);
}

.speed-value {
  min-width: 7.5em;
  color: var(--ink);
  font-weight: 500;
}

.pane-switch {
  display: none;
}

.work {
  display: grid;
  grid-template-columns: minmax(340px, 42fr) minmax(0, 58fr);
  min-height: 0;
}

.code-pane {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  min-width: 0;
  min-height: 0;
  background: var(--surface);
  border-right: 1px solid var(--rule);
}

.code-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 9px 16px;
  border-bottom: 1px solid var(--rule);
}

.code-title {
  margin: 0;
  overflow: hidden;
  font: 600 15px/1.3 var(--font-ui);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.code-hint {
  margin-left: auto;
  color: var(--ink-3);
  font-size: 12.5px;
  white-space: nowrap;
}

.editor-host {
  display: grid;
  min-height: 0;
}

/* ---------- Editor ------------------------------------------------------------ */

.editor {
  --code-size: 14px;
  --code-lh: 22px;
  --pad: 12px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  min-height: 0;
  font: 400 var(--code-size) / var(--code-lh) var(--font-code);
  font-variant-ligatures: none;
}

.editor-gutter {
  position: relative;
  overflow: hidden;
  padding-top: var(--pad);
  background: var(--surface-sunk);
  border-right: 1px solid var(--rule);
  user-select: none;
}

.g-row {
  display: grid;
  grid-template-columns: 20px auto;
  align-items: center;
  height: var(--code-lh);
  padding-right: 10px;
}

.g-num {
  min-width: 2.4ch;
  color: var(--ink-3);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.g-route {
  position: relative;
  height: 100%;
}

.on-route .g-route::before {
  content: "";
  position: absolute;
  left: 9px;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--rule-strong);
}

.editor.has-visits .on-route .g-route::before {
  background: var(--line);
}

.route-start .g-route::before {
  top: 50%;
}

.route-end .g-route::before {
  bottom: 50%;
}

.route-start.route-end .g-route::before {
  display: none;
}

.g-station {
  position: absolute;
  z-index: 1;
  left: 5px;
  top: 50%;
  width: 10px;
  height: 10px;
  margin-top: -5px;
  border: 2px solid var(--rule-strong);
  border-radius: 50%;
  background: var(--surface);
}

.g-station.is-visited {
  border-color: var(--line);
  background: var(--line);
}

.g-station.is-here {
  left: 3px;
  width: 14px;
  height: 14px;
  margin-top: -7px;
  border: 3px solid var(--band);
  background: var(--here);
  box-shadow: 0 0 0 2px var(--surface-sunk);
}

.g-station.is-error {
  left: 3px;
  width: 14px;
  height: 4px;
  margin-top: -2px;
  border: 0;
  border-radius: 2px;
  background: var(--error);
}

.editor-body {
  position: relative;
  overflow: hidden;
  min-height: 0;
}

.editor-body:focus-within {
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--focus) 55%, transparent);
}

.editor textarea {
  position: absolute;
  inset: 0;
  z-index: 2;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: var(--pad) 16px;
  border: 0;
  outline: none;
  resize: none;
  overflow: auto;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  font: inherit;
  font-variant-ligatures: none;
  white-space: pre;
  tab-size: 2;
  -webkit-text-fill-color: transparent;
}

.editor textarea::selection {
  background: color-mix(in srgb, var(--focus) 26%, transparent);
  -webkit-text-fill-color: transparent;
}

.editor-layer {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}

.editor-hl {
  position: relative;
  z-index: 1;
  margin: 0;
  padding: var(--pad) 16px;
  color: var(--ink);
  font: inherit;
  font-variant-ligatures: none;
  white-space: pre;
  tab-size: 2;
}

.editor-marks {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.here-band {
  position: absolute;
  top: 0;
  left: 0;
  width: 400vw;
  background: var(--here-soft);
}

.tok-cmd {
  color: var(--code-cmd);
}

.tok-ctl {
  color: var(--code-ctl);
}

.tok-num {
  color: var(--code-num);
}

.tok-name {
  color: var(--code-name);
}

.tok-proc {
  color: var(--code-proc);
  text-decoration: underline dotted 1px;
  text-underline-offset: 4px;
}

.tok-str {
  color: var(--code-str);
}

.tok-str[style] {
  background-image: linear-gradient(var(--swatch), var(--swatch));
  background-repeat: no-repeat;
  background-position: 0 100%;
  background-size: 100% 3px;
}

.tok-cmt {
  color: var(--code-cmt);
}

.tok-br,
.tok-op {
  color: var(--code-br);
}

.tok-bad,
.is-error {
  background-color: var(--error-soft);
  text-decoration: underline wavy var(--error) 1.5px;
  text-decoration-skip-ink: none;
  text-underline-offset: 4px;
}

.tok-mark {
  display: inline-block;
  width: 3px;
  height: 1.15em;
  margin-left: 1px;
  vertical-align: -0.2em;
  border-radius: 1px;
  background: var(--error);
}

.inlay {
  margin-left: 2ch;
  padding: 1px 7px;
  border-radius: 9px;
  background: var(--surface-sunk);
  box-shadow: inset 0 0 0 1px var(--rule);
  color: var(--ink-2);
  font: 500 11.5px/1 var(--font-ui);
  font-variant-numeric: tabular-nums;
  vertical-align: 1px;
}

.error-bubble {
  position: absolute;
  z-index: 3;
  max-width: min(460px, 86vw);
  padding: 7px 11px;
  border: 1px solid color-mix(in srgb, var(--error) 55%, transparent);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow-pop);
  color: var(--error-ink);
  font: 400 13px/1.45 var(--font-ui);
  white-space: normal;
}

.error-bubble::before {
  content: "";
  position: absolute;
  top: -6px;
  left: var(--arrow, 14px);
  width: 10px;
  height: 10px;
  border-top: 1px solid color-mix(in srgb, var(--error) 55%, transparent);
  border-left: 1px solid color-mix(in srgb, var(--error) 55%, transparent);
  background: var(--surface);
  transform: rotate(45deg);
}

/* ---------- Status band ---------------------------------------------------- */

.status-band {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 48px;
  padding: 9px 16px;
  border-top: 1px solid var(--rule);
  background: var(--surface-sunk);
  font-size: 14px;
  line-height: 1.4;
}

.status-band::before {
  content: "";
  flex: none;
  width: 12px;
  height: 12px;
  border: 2px solid var(--rule-strong);
  border-radius: 50%;
  background: var(--surface);
}

.status-band[data-tone="running"]::before,
.status-band[data-tone="paused"]::before {
  border: 3px solid var(--band);
  background: var(--here);
}

.status-band[data-tone="done"]::before {
  border-color: var(--line);
  background: var(--line);
}

.status-band[data-tone="error"] {
  background: var(--error-soft);
  color: var(--error-ink);
}

.status-band[data-tone="error"]::before {
  width: 14px;
  height: 4px;
  border: 0;
  border-radius: 2px;
  background: var(--error);
}

.status-text {
  flex: 1;
  min-width: 0;
  margin: 0;
}

.status-text b {
  font-weight: 600;
}

.status-action {
  flex: none;
}

/* ---------- Drawing view --------------------------------------------------- */

.view-pane {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--paper);
}

.view-host,
.view2d,
.view3d {
  position: absolute;
  inset: 0;
}

.view2d canvas,
.view3d canvas {
  display: block;
  touch-action: none;
  cursor: grab;
}

.view2d.is-dragging canvas {
  cursor: grabbing;
}

.view2d canvas:focus-visible,
.view3d canvas:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: -4px;
}

.readout {
  position: absolute;
  top: 12px;
  left: 12px;
  display: grid;
  gap: 2px;
  max-width: calc(100% - 24px);
  padding: 8px 12px 9px;
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--band) 94%, transparent);
  color: var(--on-band);
  font: 400 12.5px/1.35 var(--font-ui);
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}

.ro-pos {
  font-weight: 600;
  font-size: 13.5px;
}

.ro-dir,
.ro-pen {
  color: var(--on-band-muted);
}

.ro-pen {
  display: flex;
  align-items: center;
}

.swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  margin-right: 7px;
  border-radius: 2px;
  background: var(--swatch);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.55);
}

.view-controls {
  position: absolute;
  right: 12px;
  bottom: 12px;
  display: flex;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--rule);
  border-radius: 8px;
  background: var(--surface);
  box-shadow: 0 2px 8px rgba(17, 26, 45, 0.1);
}

.view-controls .btn {
  border-color: transparent;
  background: transparent;
}

.view-controls .btn:hover {
  background: var(--surface-hover);
}

.studio.view-off .view-controls {
  display: none;
}

.view-off {
  display: grid;
  place-content: center;
  height: 100%;
  max-width: 46ch;
  margin: 0 auto;
  padding: 24px;
  color: var(--ink);
  text-align: left;
}

.view-off strong {
  font-size: 17px;
}

.view-off p {
  margin: 8px 0 0;
  color: var(--ink-2);
}

.view3d.is-off {
  background: var(--surface-sunk);
}

/* ---------- Challenge strip ------------------------------------------------- */

.challenge-strip {
  display: grid;
  gap: 8px;
  padding: 12px 16px 14px;
  border-bottom: 1px solid var(--rule);
  background: var(--surface-sunk);
}

.challenge-strip[hidden] {
  display: none;
}

.ch-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-left: -10px;
}

.ch-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 9px;
  border-radius: 11px;
  background: var(--surface);
  box-shadow: inset 0 0 0 1px var(--rule);
  color: var(--ink-2);
  font: 600 12px/1.2 var(--font-ui);
}

.ch-badge[data-passed="true"] {
  background: var(--success-soft);
  box-shadow: none;
  color: var(--success);
}

.ch-task {
  max-width: 62ch;
  margin: 0;
  font-size: 15px;
  line-height: 1.45;
}

.ch-hint summary {
  width: fit-content;
  color: var(--line-strong);
  font-size: 13.5px;
  font-weight: 500;
  cursor: pointer;
  border-radius: var(--radius-s);
}

.ch-hint p {
  max-width: 62ch;
  margin: 6px 0 0;
  color: var(--ink-2);
  font-size: 14px;
}

.ch-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
}

.btn-check {
  border-color: var(--band);
  background: var(--band);
  color: var(--on-band);
  font-weight: 600;
}

.btn-check:hover {
  background: var(--band-raised);
}

:root[data-theme="dark"] .btn-check {
  border-color: var(--rule-strong);
  background: var(--band-raised);
}

.ch-result {
  display: flex;
  flex-basis: 100%;
  align-items: flex-start;
  gap: 6px;
  margin: 0;
  font-size: 14px;
  line-height: 1.4;
}

.ch-result:empty {
  display: none;
}

.ch-result .icon {
  margin-top: 1px;
}

.ch-result[data-tone="pass"] {
  color: var(--success);
  font-weight: 500;
}

.ch-result[data-tone="fail"] {
  color: var(--error-ink);
}

/* ---------- Pages ------------------------------------------------------------ */

.page {
  overflow: auto;
}

.page-inner {
  width: 100%;
  max-width: 980px;
  margin: 0 auto;
  padding: 36px 24px 72px;
}

.page-head h1 {
  margin: 0 0 10px;
  font: 600 30px/1.15 var(--font-ui);
  letter-spacing: -0.015em;
}

.page-head p {
  max-width: 66ch;
  margin: 0 0 10px;
  color: var(--ink-2);
  font-size: 16px;
}

.progress-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 16px;
  margin-top: 18px !important;
}

.progress-count {
  color: var(--ink);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* Progress drawn as a line with stations. */
.progress-track {
  position: relative;
  display: inline-flex;
  gap: 18px;
  padding: 0 2px;
}

.progress-track::before {
  content: "";
  position: absolute;
  left: 6px;
  right: 6px;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  background: var(--rule-strong);
}

.progress-track span {
  position: relative;
  width: 12px;
  height: 12px;
  border: 2px solid var(--rule-strong);
  border-radius: 50%;
  background: var(--ground);
}

.progress-track span.is-done {
  border-color: var(--line-2d);
  background: var(--line-2d);
}

.ch-list {
  margin: 28px 0 0;
  padding: 0;
  border-top: 1px solid var(--rule);
  list-style: none;
}

.ch-row {
  position: relative;
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr) auto;
  align-items: center;
  gap: 20px;
  padding: 16px 12px;
  border-bottom: 1px solid var(--rule);
  transition: background-color 150ms var(--ease-out);
}

.ch-row:hover {
  background: var(--surface-hover);
}

.ch-row:focus-within {
  background: var(--surface-hover);
}

.ch-thumb {
  display: grid;
  place-items: center;
  width: 96px;
  height: 96px;
  border: 1px solid var(--rule);
  border-radius: 8px;
  background: var(--paper);
  color: #3f4a61;
}

.thumb-start {
  fill: var(--here);
  stroke: #17223b;
  stroke-width: 1.5;
}

.ch-body h2 {
  margin: 0 0 4px;
  font: 600 18px/1.3 var(--font-ui);
}

.ch-body a {
  color: var(--ink);
  text-decoration: none;
  border-radius: var(--radius-s);
}

.ch-body a::after {
  content: "";
  position: absolute;
  inset: 0;
}

.ch-body a:focus-visible {
  outline: none;
}

.ch-row:has(a:focus-visible) {
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}

.ch-body p {
  max-width: 62ch;
  margin: 0;
  color: var(--ink-2);
  font-size: 14.5px;
  line-height: 1.45;
}

.ch-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}

.ch-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--ink-2);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.ch-status.is-done {
  color: var(--success);
}

/* ---------- Reference (Read) -------------------------------------------------- */

.docs {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 48px;
  width: 100%;
  max-width: 1140px;
  margin: 0 auto;
  padding: 36px 24px 96px;
}

.docs-toc {
  position: sticky;
  top: 24px;
  align-self: start;
  font-size: 14px;
}

.toc-title {
  margin: 0 0 8px;
  padding: 0 10px;
  color: var(--ink-3);
  font-weight: 600;
}

.docs-toc ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

.docs-toc a {
  display: block;
  padding: 6px 10px;
  border-radius: var(--radius);
  color: var(--ink-2);
  text-decoration: none;
}

.docs-toc a:hover {
  background: var(--surface-hover);
  color: var(--ink);
}

.docs-body {
  max-width: 74ch;
  font-size: 16px;
  line-height: 1.6;
}

.docs-body h1 {
  margin: 0 0 12px;
  font: 600 34px/1.15 var(--font-ui);
  letter-spacing: -0.02em;
}

.docs-body .lead {
  margin: 0 0 16px;
  color: var(--ink-2);
  font-size: 17px;
  line-height: 1.55;
}

.doc-section {
  margin-top: 56px;
  scroll-margin-top: 24px;
}

.doc-section h2 {
  margin: 0 0 10px;
  font: 600 24px/1.25 var(--font-ui);
  letter-spacing: -0.01em;
}

.doc-section h2:focus {
  outline: none;
}

.doc-section p {
  margin: 0 0 14px;
}

.doc-section ul {
  margin: 0 0 16px;
  padding-left: 22px;
}

.doc-section li {
  margin: 6px 0;
}

.cmd {
  padding: 22px 0 8px;
  border-top: 1px solid var(--rule);
  scroll-margin-top: 24px;
}

.cmd h3 {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px 10px;
  margin: 0 0 6px;
  font: 600 17px/1.3 var(--font-ui);
}

.cmd h3 > code {
  font-size: 18px;
  font-weight: 400;
  color: var(--code-cmd);
}

.aliases {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
}

.aliases code {
  padding: 1px 7px;
  border-radius: var(--radius-s);
  background: var(--surface-sunk);
  box-shadow: inset 0 0 0 1px var(--rule);
  color: var(--ink-2);
  font-size: 13px;
  font-weight: 400;
}

.aliases-en code {
  color: var(--ink-3);
}

.cmd-arg {
  color: var(--ink-2);
  font-size: 14.5px;
}

.cmd-arg span {
  color: var(--ink);
  font-weight: 600;
}

.doc-example {
  display: grid;
  justify-items: start;
  gap: 8px;
  margin: 8px 0 18px;
}

.code-block {
  width: 100%;
  margin: 0;
  padding: 12px 16px;
  overflow: auto;
  border: 1px solid var(--rule);
  border-radius: 8px;
  background: var(--surface);
  font: 400 14px/22px var(--font-code);
  font-variant-ligatures: none;
}

.code-block code {
  font-size: inherit;
}

.table-wrap {
  overflow-x: auto;
}

table.limits,
table.cheat {
  width: 100%;
  margin: 0 0 16px;
  border-collapse: collapse;
  font-size: 15px;
}

table.limits th,
table.limits td,
table.cheat th,
table.cheat td {
  padding: 10px 12px 10px 0;
  border-bottom: 1px solid var(--rule);
  text-align: left;
  vertical-align: top;
}

table.limits th {
  width: 42%;
  font-weight: 500;
}

table.cheat thead th {
  color: var(--ink-3);
  font-size: 13px;
  font-weight: 600;
}

table.cheat code {
  display: inline-block;
  margin: 1px 2px 1px 0;
  color: var(--code-cmd);
}

/* ---------- Menus and toasts ------------------------------------------------- */

.menu {
  position: relative;
}

.menu-pop {
  position: fixed;
  z-index: 50;
  min-width: 290px;
  max-width: min(380px, calc(100vw - 16px));
  overflow: auto;
  padding: 6px;
  border: 1px solid var(--rule);
  border-radius: var(--radius-l);
  background: var(--surface);
  box-shadow: var(--shadow-pop);
}

.menu-pop[hidden] {
  display: none;
}

.menu-group {
  padding: 10px 10px 4px;
  color: var(--ink-3);
  font-size: 12.5px;
  font-weight: 600;
}

.menu-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 10px;
  border-radius: var(--radius);
  cursor: pointer;
}

.menu-item:hover,
.menu-item:focus {
  outline: none;
  background: var(--surface-hover);
}

.menu-item:focus-visible {
  box-shadow: inset 0 0 0 2px var(--focus);
}

.menu-item[aria-disabled="true"] {
  opacity: 0.5;
  cursor: not-allowed;
}

.menu-item .bullet {
  margin-top: 1px;
}

.menu-item .icon {
  margin-top: 1px;
  color: var(--ink-2);
}

.menu-text {
  display: grid;
  gap: 1px;
}

.menu-label {
  font-size: 14.5px;
  font-weight: 500;
}

.menu-detail {
  color: var(--ink-2);
  font-size: 12.5px;
  line-height: 1.35;
}

.toast-region {
  position: fixed;
  left: 16px;
  bottom: 16px;
  z-index: 60;
}

.toast {
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: min(560px, calc(100vw - 32px));
  padding: 9px 8px 9px 14px;
  border-radius: 8px;
  background: var(--band);
  box-shadow: var(--shadow-pop);
  color: var(--on-band);
  font-size: 14px;
  line-height: 1.4;
  animation: toast-in 220ms var(--ease-out);
}

:root[data-theme="dark"] .toast {
  background: var(--band-raised);
}

.toast :focus-visible {
  outline-color: var(--on-band);
}

.toast-close {
  display: inline-grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--on-band-muted);
  cursor: pointer;
}

.toast-close:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--on-band);
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .toast {
    animation: none;
  }

  * {
    transition: none !important;
  }
}

/* ---------- Responsive ----------------------------------------------------------- */

@media (max-width: 1180px) {
  .speed-value {
    display: none;
  }

  .work {
    grid-template-columns: minmax(320px, 1fr) minmax(0, 1fr);
  }

  .code-hint {
    display: none;
  }
}

@media (max-width: 980px) {
  .tool-end .btn-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }
}

@media (max-width: 759px) {
  :root {
    --band-h: 52px;
  }

  .band {
    gap: 10px;
    padding: 0 8px 0 12px;
  }

  .wordmark span {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
  }

  .main-nav a {
    height: 34px;
    padding: 0 9px;
    font-size: 14px;
  }

  .main-nav a[aria-current="page"]::after {
    left: 9px;
    right: 9px;
    bottom: -9px;
  }

  .nav-count,
  .nav-long {
    display: none;
  }

  .nav-short {
    display: inline !important;
  }

  .studio {
    min-height: 0;
  }

  .toolrow {
    gap: 6px 10px;
    padding: 6px 10px;
  }

  .toolrow .btn:not(.btn-primary) .btn-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  .toolrow .btn {
    height: 40px;
    min-width: 40px;
    padding: 0 10px;
  }

  .speed-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
  }

  .speed input {
    width: 96px;
  }

  .pane-switch {
    display: grid;
    grid-template-columns: 1fr 1fr;
    background: var(--surface);
    border-bottom: 1px solid var(--rule);
  }

  .pane-switch [role="tab"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    height: 42px;
    border: 0;
    background: transparent;
    color: var(--ink-2);
    font: 500 14.5px/1 var(--font-ui);
    cursor: pointer;
  }

  .pane-switch [aria-selected="true"] {
    color: var(--ink);
    box-shadow: inset 0 -3px 0 var(--line);
  }

  .pane-switch :focus-visible {
    outline-offset: -3px;
  }

  .work {
    grid-template-columns: minmax(0, 1fr);
  }

  .work[data-pane="code"] .view-pane,
  .work[data-pane="view"] .code-pane {
    display: none;
  }

  .code-pane {
    border-right: 0;
  }

  .editor {
    --code-size: 16px;
    --code-lh: 24px;
  }

  .status-band {
    font-size: 13.5px;
  }

  .readout {
    top: 8px;
    left: 8px;
    font-size: 12px;
  }

  .view-controls {
    right: 8px;
    bottom: 8px;
  }

  .view-controls .btn {
    width: 44px;
    height: 44px;
  }

  .page-inner {
    padding: 24px 16px 56px;
  }

  .page-head h1 {
    font-size: 26px;
  }

  .ch-row {
    grid-template-columns: 72px minmax(0, 1fr);
    gap: 14px;
    align-items: start;
    padding: 14px 4px;
  }

  .ch-thumb {
    width: 72px;
    height: 72px;
  }

  .ch-thumb svg {
    width: 64px;
    height: 64px;
  }

  .ch-meta {
    grid-column: 2;
    flex-direction: row;
    align-items: center;
    margin-top: -6px;
  }

  .docs {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
    padding: 20px 16px 72px;
  }

  .docs-toc {
    position: static;
  }

  .docs-toc ol {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
  }

  .docs-toc a {
    padding: 5px 10px;
    border: 1px solid var(--rule);
    background: var(--surface);
    font-size: 13.5px;
  }

  .docs-body h1 {
    font-size: 28px;
  }

  .doc-section {
    margin-top: 40px;
  }

  .toast-region {
    left: 8px;
    right: 8px;
    bottom: 8px;
  }
}

.nav-short {
  display: none;
}

@media (max-width: 380px) {
  .mode-switch [role="radio"] {
    width: 30px;
  }

  .main-nav a {
    padding: 0 7px;
  }
}

toolu_011inHx6G7xU7pQuFwsRHWas.content:
/* ---------- Base ---------------------------------------------------------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
}

body {
  background: var(--ground);
  color: var(--ink);
  font: 400 15px/1.5 var(--font-ui);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

* {
  scrollbar-color: var(--rule-strong) transparent;
  scrollbar-width: thin;
}

::selection {
  background: var(--code-sel);
  color: inherit;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

a {
  color: var(--line-strong);
  text-underline-offset: 0.18em;
  text-decoration-thickness: 1px;
}

kbd {
  font: 500 0.85em/1 var(--font-code);
  padding: 2px 6px;
  border: 1px solid var(--rule-strong);
  border-bottom-width: 2px;
  border-radius: var(--radius-s);
  background: var(--surface);
  color: var(--ink);
  white-space: nowrap;
}

code {
  font-family: var(--font-code);
  font-size: 0.94em;
}

.icon {
  flex: none;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

#app {
  min-height: 100dvh;
  display: grid;
  grid-template-rows: auto 1fr;
}

main {
  min-height: 0;
  display: grid;
}

main:focus {
  outline: none;
}

.route[hidden] {
  display: none !important;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  z-index: 100;
  padding: 8px 14px;
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  font-weight: 600;
  box-shadow: var(--shadow-pop);
}

.skip-link:focus {
  top: 8px;
}

/* ---------- Band (the station sign) ----------------------------------------- */

.band {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 20px;
  height: var(--band-h);
  padding: 0 16px;
  background: var(--band);
  color: var(--on-band);
}

.band :focus-visible {
  outline-color: var(--on-band);
}

.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--on-band);
  font: 600 19px/1 var(--font-ui);
  letter-spacing: -0.01em;
  text-decoration: none;
  border-radius: var(--radius);
}

.wordmark .mark {
  flex: none;
}

.mode-switch {
  display: inline-flex;
  gap: 6px;
}

.mode-switch [role="radio"] {
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 30px;
  padding: 0;
  border: 1.5px solid rgba(255, 255, 255, 0.28);
  border-radius: 5px;
  background: transparent;
  color: var(--on-band-muted);
  font: 700 13px/1 var(--font-ui);
  letter-spacing: 0.02em;
  cursor: pointer;
  transition:
    background-color 160ms var(--ease-out),
    border-color 160ms var(--ease-out),
    color 160ms var(--ease-out);
}

.mode-switch [role="radio"]:hover {
  border-color: var(--on-band);
  color: var(--on-band);
}

.mode-switch [data-mode="2d"][aria-checked="true"] {
  background: var(--line-2d);
  border-color: var(--line-2d);
  color: var(--on-line);
}

.mode-switch [data-mode="3d"][aria-checked="true"] {
  background: var(--line-3d);
  border-color: var(--line-3d);
  color: var(--on-line);
}

.band:not([data-route="studio"]) .mode-switch {
  visibility: hidden;
}

.main-nav {
  display: flex;
  gap: 2px;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.main-nav a {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 12px;
  border-radius: var(--radius);
  color: var(--on-band-muted);
  font: 500 15px/1 var(--font-ui);
  text-decoration: none;
  white-space: nowrap;
}

.main-nav a:hover {
  color: var(--on-band);
  background: var(--band-raised);
}

.main-nav a[aria-current="page"] {
  color: var(--on-band);
}

.main-nav a[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: -10px;
  height: 3px;
  border-radius: 2px 2px 0 0;
  background: var(--on-band);
}

.nav-count {
  padding: 2px 6px;
  border-radius: 9px;
  background: var(--band-raised);
  color: var(--on-band-muted);
  font: 500 12px/1.2 var(--font-ui);
  font-variant-numeric: tabular-nums;
}

.theme-toggle {
  margin-left: auto;
}

/* ---------- Buttons ------------------------------------------------------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 36px;
  padding: 0 13px;
  border: 1px solid var(--rule-strong);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  font: 500 14px/1 var(--font-ui);
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
  transition:
    background-color 150ms var(--ease-out),
    border-color 150ms var(--ease-out),
    color 150ms var(--ease-out);
}

.btn:hover {
  background: var(--surface-hover);
}

.btn:active {
  background: var(--rule);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  background: var(--surface);
}

.btn-primary {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--on-line);
  font-weight: 600;
}

.btn-primary:hover {
  background: color-mix(in srgb, var(--primary) 86%, var(--ink));
}

.btn-primary:active {
  background: color-mix(in srgb, var(--primary) 76%, var(--ink));
}

.btn-quiet {
  border-color: transparent;
  background: transparent;
}

.btn-icon {
  width: 36px;
  padding: 0;
}

.btn-small {
  height: 30px;
  padding: 0 10px;
  font-size: 13px;
}

.btn-on-band {
  border-color: transparent;
  background: transparent;
  color: var(--on-band);
}

.btn-on-band:hover {
  background: var(--band-raised);
}

.btn-on-dark {
  border-color: rgba(255, 255, 255, 0.35);
  background: transparent;
  color: var(--on-band);
}

.btn-on-dark:hover {
  background: var(--band-raised);
}

.bullet {
  display: inline-grid;
  place-items: center;
  min-width: 28px;
  height: 22px;
  padding: 0 5px;
  border-radius: 4px;
  background: var(--line);
  color: var(--on-line);
  font: 700 12px/1 var(--font-ui);
  letter-spacing: 0.02em;
}

.bullet-2d {
  background: var(--line-2d);
}

.bullet-3d {
  background: var(--line-3d);
}

/* ---------- Studio layout ----------------------------------------------- */

.studio {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  height: calc(100dvh - var(--band-h));
  min-height: 420px;
}

.toolrow {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 16px;
  padding: 8px 16px;
  background: var(--surface);
  border-bottom: 1px solid var(--rule);
}

.tool-group {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tool-end {
  margin-left: auto;
  gap: 2px;
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--ink-2);
  font-size: 13px;
}

.speed-label {
  font-weight: 500;
}

.speed input {
  width: 120px;
  accent-color: var(--line-strong);
}

.speed-value {
  min-width: 7.5em;
  color: var(--ink);
  font-weight: 500;
}

.pane-switch {
  display: none;
}

.work {
  display: grid;
  grid-template-columns: minmax(340px, 42fr) minmax(0, 58fr);
  min-height: 0;
}

.code-pane {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  min-width: 0;
  min-height: 0;
  background: var(--surface);
  border-right: 1px solid var(--rule);
}

.code-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 9px 16px;
  border-bottom: 1px solid var(--rule);
}

.code-title {
  margin: 0;
  overflow: hidden;
  font: 600 15px/1.3 var(--font-ui);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.code-hint {
  margin-left: auto;
  color: var(--ink-3);
  font-size: 12.5px;
  white-space: nowrap;
}

.editor-host {
  display: grid;
  min-height: 0;
}

/* ---------- Editor ------------------------------------------------------------ */

.editor {
  --code-size: 14px;
  --code-lh: 22px;
  --pad: 12px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  min-height: 0;
  font: 400 var(--code-size) / var(--code-lh) var(--font-code);
  font-variant-ligatures: none;
}

.editor-gutter {
  position: relative;
  overflow: hidden;
  padding-top: var(--pad);
  background: var(--surface-sunk);
  border-right: 1px solid var(--rule);
  user-select: none;
}

.g-row {
  display: grid;
  grid-template-columns: 20px auto;
  align-items: center;
  height: var(--code-lh);
  padding-right: 10px;
}

.g-num {
  min-width: 2.4ch;
  color: var(--ink-3);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.g-route {
  position: relative;
  height: 100%;
}

.on-route .g-route::before {
  content: "";
  position: absolute;
  left: 9px;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--rule-strong);
}

.editor.has-visits .on-route .g-route::before {
  background: var(--line);
}

.route-start .g-route::before {
  top: 50%;
}

.route-end .g-route::before {
  bottom: 50%;
}

.route-start.route-end .g-route::before {
  display: none;
}

.g-station {
  position: absolute;
  z-index: 1;
  left: 5px;
  top: 50%;
  width: 10px;
  height: 10px;
  margin-top: -5px;
  border: 2px solid var(--rule-strong);
  border-radius: 50%;
  background: var(--surface);
}

.g-station.is-visited {
  border-color: var(--line);
  background: var(--line);
}

.g-station.is-here {
  left: 3px;
  width: 14px;
  height: 14px;
  margin-top: -7px;
  border: 3px solid var(--band);
  background: var(--here);
  box-shadow: 0 0 0 2px var(--surface-sunk);
}

.g-station.is-error {
  left: 3px;
  width: 14px;
  height: 4px;
  margin-top: -2px;
  border: 0;
  border-radius: 2px;
  background: var(--error);
}

.editor-body {
  position: relative;
  overflow: hidden;
  min-height: 0;
}

.editor-body:focus-within {
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--focus) 55%, transparent);
}

.editor textarea {
  position: absolute;
  inset: 0;
  z-index: 2;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: var(--pad) 16px;
  border: 0;
  outline: none;
  resize: none;
  overflow: auto;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  font: inherit;
  font-variant-ligatures: none;
  white-space: pre;
  tab-size: 2;
  -webkit-text-fill-color: transparent;
}

.editor textarea::selection {
  background: color-mix(in srgb, var(--focus) 26%, transparent);
  -webkit-text-fill-color: transparent;
}

.editor-layer {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}

.editor-hl {
  position: relative;
  z-index: 1;
  margin: 0;
  padding: var(--pad) 16px;
  color: var(--ink);
  font: inherit;
  font-variant-ligatures: none;
  white-space: pre;
  tab-size: 2;
}

.editor-marks {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.here-band {
  position: absolute;
  top: 0;
  left: 0;
  width: 400vw;
  background: var(--here-soft);
}

.tok-cmd {
  color: var(--code-cmd);
}

.tok-ctl {
  color: var(--code-ctl);
}

.tok-num {
  color: var(--code-num);
}

.tok-name {
  color: var(--code-name);
}

.tok-proc {
  color: var(--code-proc);
  text-decoration: underline dotted 1px;
  text-underline-offset: 4px;
}

.tok-str {
  color: var(--code-str);
}

.tok-str[style] {
  background-image: linear-gradient(var(--swatch), var(--swatch));
  background-repeat: no-repeat;
  background-position: 0 100%;
  background-size: 100% 3px;
}

.tok-cmt {
  color: var(--code-cmt);
}

.tok-br,
.tok-op {
  color: var(--code-br);
}

.tok-bad,
.is-error {
  background-color: var(--error-soft);
  text-decoration: underline wavy var(--error) 1.5px;
  text-decoration-skip-ink: none;
  text-underline-offset: 4px;
}

.tok-mark {
  display: inline-block;
  width: 3px;
  height: 1.15em;
  margin-left: 1px;
  vertical-align: -0.2em;
  border-radius: 1px;
  background: var(--error);
}

.inlay {
  margin-left: 2ch;
  padding: 1px 7px;
  border-radius: 9px;
  background: var(--surface-sunk);
  box-shadow: inset 0 0 0 1px var(--rule);
  color: var(--ink-2);
  font: 500 11.5px/1 var(--font-ui);
  font-variant-numeric: tabular-nums;
  vertical-align: 1px;
}

.error-bubble {
  position: absolute;
  z-index: 3;
  max-width: min(460px, 86vw);
  padding: 7px 11px;
  border: 1px solid color-mix(in srgb, var(--error) 55%, transparent);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow-pop);
  color: var(--error-ink);
  font: 400 13px/1.45 var(--font-ui);
  white-space: normal;
}

.error-bubble::before {
  content: "";
  position: absolute;
  top: -6px;
  left: var(--arrow, 14px);
  width: 10px;
  height: 10px;
  border-top: 1px solid color-mix(in srgb, var(--error) 55%, transparent);
  border-left: 1px solid color-mix(in srgb, var(--error) 55%, transparent);
  background: var(--surface);
  transform: rotate(45deg);
}

/* ---------- Status band ---------------------------------------------------- */

.status-band {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 48px;
  padding: 9px 16px;
  border-top: 1px solid var(--rule);
  background: var(--surface-sunk);
  font-size: 14px;
  line-height: 1.4;
}

.status-band::before {
  content: "";
  flex: none;
  width: 12px;
  height: 12px;
  border: 2px solid var(--rule-strong);
  border-radius: 50%;
  background: var(--surface);
}

.status-band[data-tone="running"]::before,
.status-band[data-tone="paused"]::before {
  border: 3px solid var(--band);
  background: var(--here);
}

.status-band[data-tone="done"]::before {
  border-color: var(--line);
  background: var(--line);
}

.status-band[data-tone="error"] {
  background: var(--error-soft);
  color: var(--error-ink);
}

.status-band[data-tone="error"]::before {
  width: 14px;
  height: 4px;
  border: 0;
  border-radius: 2px;
  background: var(--error);
}

.status-text {
  flex: 1;
  min-width: 0;
  margin: 0;
}

.status-text b {
  font-weight: 600;
}

.status-action {
  flex: none;
}

/* ---------- Drawing view --------------------------------------------------- */

.view-pane {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--paper);
}

.view-host,
.view2d,
.view3d {
  position: absolute;
  inset: 0;
}

.view2d canvas,
.view3d canvas {
  display: block;
  touch-action: none;
  cursor: grab;
}

.view2d.is-dragging canvas {
  cursor: grabbing;
}

.view2d canvas:focus-visible,
.view3d canvas:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: -4px;
}

.readout {
  position: absolute;
  top: 12px;
  left: 12px;
  display: grid;
  gap: 2px;
  max-width: calc(100% - 24px);
  padding: 8px 12px 9px;
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--band) 94%, transparent);
  color: var(--on-band);
  font: 400 12.5px/1.35 var(--font-ui);
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}

.ro-pos {
  font-weight: 600;
  font-size: 13.5px;
}

.ro-dir,
.ro-pen {
  color: var(--on-band-muted);
}

.ro-pen {
  display: flex;
  align-items: center;
}

.swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  margin-right: 7px;
  border-radius: 2px;
  background: var(--swatch);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.55);
}

.view-controls {
  position: absolute;
  right: 12px;
  bottom: 12px;
  display: flex;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--rule);
  border-radius: 8px;
  background: var(--surface);
  box-shadow: 0 2px 8px rgba(17, 26, 45, 0.1);
}

.view-controls .btn {
  border-color: transparent;
  background: transparent;
}

.view-controls .btn:hover {
  background: var(--surface-hover);
}

.studio.view-off .view-controls {
  display: none;
}

.view-off {
  display: grid;
  place-content: center;
  height: 100%;
  max-width: 46ch;
  margin: 0 auto;
  padding: 24px;
  color: var(--ink);
  text-align: left;
}

.view-off strong {
  font-size: 17px;
}

.view-off p {
  margin: 8px 0 0;
  color: var(--ink-2);
}

.view3d.is-off {
  background: var(--surface-sunk);
}

/* ---------- Challenge strip ------------------------------------------------- */

.challenge-strip {
  display: grid;
  gap: 8px;
  padding: 12px 16px 14px;
  border-bottom: 1px solid var(--rule);
  background: var(--surface-sunk);
}

.challenge-strip[hidden] {
  display: none;
}

.ch-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-left: -10px;
}

.ch-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 9px;
  border-radius: 11px;
  background: var(--surface);
  box-shadow: inset 0 0 0 1px var(--rule);
  color: var(--ink-2);
  font: 600 12px/1.2 var(--font-ui);
}

.ch-badge[data-passed="true"] {
  background: var(--success-soft);
  box-shadow: none;
  color: var(--success);
}

.ch-task {
  max-width: 62ch;
  margin: 0;
  font-size: 15px;
  line-height: 1.45;
}

.ch-hint summary {
  width: fit-content;
  color: var(--line-strong);
  font-size: 13.5px;
  font-weight: 500;
  cursor: pointer;
  border-radius: var(--radius-s);
}

.ch-hint p {
  max-width: 62ch;
  margin: 6px 0 0;
  color: var(--ink-2);
  font-size: 14px;
}

.ch-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
}

.btn-check {
  border-color: var(--band);
  background: var(--band);
  color: var(--on-band);
  font-weight: 600;
}

.btn-check:hover {
  background: var(--band-raised);
}

:root[data-theme="dark"] .btn-check {
  border-color: var(--rule-strong);
  background: var(--band-raised);
}

.ch-result {
  display: flex;
  flex-basis: 100%;
  align-items: flex-start;
  gap: 6px;
  margin: 0;
  font-size: 14px;
  line-height: 1.4;
}

.ch-result:empty {
  display: none;
}

.ch-result .icon {
  margin-top: 1px;
}

.ch-result[data-tone="pass"] {
  color: var(--success);
  font-weight: 500;
}

.ch-result[data-tone="fail"] {
  color: var(--error-ink);
}

/* ---------- Pages ------------------------------------------------------------ */

.page {
  overflow: auto;
}

.page-inner {
  width: 100%;
  max-width: 980px;
  margin: 0 auto;
  padding: 36px 24px 72px;
}

.page-head h1 {
  margin: 0 0 10px;
  font: 600 30px/1.15 var(--font-ui);
  letter-spacing: -0.015em;
}

.page-head p {
  max-width: 66ch;
  margin: 0 0 10px;
  color: var(--ink-2);
  font-size: 16px;
}

.progress-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 16px;
  margin-top: 18px !important;
}

.progress-count {
  color: var(--ink);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* Progress drawn as a line with stations. */
.progress-track {
  position: relative;
  display: inline-flex;
  gap: 18px;
  padding: 0 2px;
}

.progress-track::before {
  content: "";
  position: absolute;
  left: 6px;
  right: 6px;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  background: var(--rule-strong);
}

.progress-track span {
  position: relative;
  width: 12px;
  height: 12px;
  border: 2px solid var(--rule-strong);
  border-radius: 50%;
  background: var(--ground);
}

.progress-track span.is-done {
  border-color: var(--line-2d);
  background: var(--line-2d);
}

.ch-list {
  margin: 28px 0 0;
  padding: 0;
  border-top: 1px solid var(--rule);
  list-style: none;
}

.ch-row {
  position: relative;
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr) auto;
  align-items: center;
  gap: 20px;
  padding: 16px 12px;
  border-bottom: 1px solid var(--rule);
  transition: background-color 150ms var(--ease-out);
}

.ch-row:hover {
  background: var(--surface-hover);
}

.ch-row:focus-within {
  background: var(--surface-hover);
}

.ch-thumb {
  display: grid;
  place-items: center;
  width: 96px;
  height: 96px;
  border: 1px solid var(--rule);
  border-radius: 8px;
  background: var(--paper);
  color: #3f4a61;
}

.thumb-start {
  fill: var(--here);
  stroke: #17223b;
  stroke-width: 1.5;
}

.ch-body h2 {
  margin: 0 0 4px;
  font: 600 18px/1.3 var(--font-ui);
}

.ch-body a {
  color: var(--ink);
  text-decoration: none;
  border-radius: var(--radius-s);
}

.ch-body a::after {
  content: "";
  position: absolute;
  inset: 0;
}

.ch-body a:focus-visible {
  outline: none;
}

.ch-row:has(a:focus-visible) {
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}

.ch-body p {
  max-width: 62ch;
  margin: 0;
  color: var(--ink-2);
  font-size: 14.5px;
  line-height: 1.45;
}

.ch-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}

.ch-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--ink-2);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.ch-status.is-done {
  color: var(--success);
}

/* ---------- Reference (Read) -------------------------------------------------- */

.docs {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 48px;
  width: 100%;
  max-width: 1140px;
  margin: 0 auto;
  padding: 36px 24px 96px;
}

.docs-toc {
  position: sticky;
  top: 24px;
  align-self: start;
  font-size: 14px;
}

.toc-title {
  margin: 0 0 8px;
  padding: 0 10px;
  color: var(--ink-3);
  font-weight: 600;
}

.docs-toc ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

.docs-toc a {
  display: block;
  padding: 6px 10px;
  border-radius: var(--radius);
  color: var(--ink-2);
  text-decoration: none;
}

.docs-toc a:hover {
  background: var(--surface-hover);
  color: var(--ink);
}

.docs-body {
  max-width: 74ch;
  font-size: 16px;
  line-height: 1.6;
}

.docs-body h1 {
  margin: 0 0 12px;
  font: 600 34px/1.15 var(--font-ui);
  letter-spacing: -0.02em;
}

.docs-body .lead {
  margin: 0 0 16px;
  color: var(--ink-2);
  font-size: 17px;
  line-height: 1.55;
}

.doc-section {
  margin-top: 56px;
  scroll-margin-top: 24px;
}

.doc-section h2 {
  margin: 0 0 10px;
  font: 600 24px/1.25 var(--font-ui);
  letter-spacing: -0.01em;
}

.doc-section h2:focus {
  outline: none;
}

.doc-section p {
  margin: 0 0 14px;
}

.doc-section ul {
  margin: 0 0 16px;
  padding-left: 22px;
}

.doc-section li {
  margin: 6px 0;
}

.cmd {
  padding: 22px 0 8px;
  border-top: 1px solid var(--rule);
  scroll-margin-top: 24px;
}

.cmd h3 {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px 10px;
  margin: 0 0 6px;
  font: 600 17px/1.3 var(--font-ui);
}

.cmd h3 > code {
  font-size: 18px;
  font-weight: 400;
  color: var(--code-cmd);
}

.aliases {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
}

.aliases code {
  padding: 1px 7px;
  border-radius: var(--radius-s);
  background: var(--surface-sunk);
  box-shadow: inset 0 0 0 1px var(--rule);
  color: var(--ink-2);
  font-size: 13px;
  font-weight: 400;
}

.aliases-en code {
  color: var(--ink-3);
}

.cmd-arg {
  color: var(--ink-2);
  font-size: 14.5px;
}

.cmd-arg span {
  color: var(--ink);
  font-weight: 600;
}

.doc-example {
  display: grid;
  justify-items: start;
  gap: 8px;
  margin: 8px 0 18px;
}

.code-block {
  width: 100%;
  margin: 0;
  padding: 12px 16px;
  overflow: auto;
  border: 1px solid var(--rule);
  border-radius: 8px;
  background: var(--surface);
  font: 400 14px/22px var(--font-code);
  font-variant-ligatures: none;
}

.code-block code {
  font-size: inherit;
}

.table-wrap {
  overflow-x: auto;
}

table.limits,
table.cheat {
  width: 100%;
  margin: 0 0 16px;
  border-collapse: collapse;
  font-size: 15px;
}

table.limits th,
table.limits td,
table.cheat th,
table.cheat td {
  padding: 10px 12px 10px 0;
  border-bottom: 1px solid var(--rule);
  text-align: left;
  vertical-align: top;
}

table.limits th {
  width: 42%;
  font-weight: 500;
}

table.cheat thead th {
  color: var(--ink-3);
  font-size: 13px;
  font-weight: 600;
}

table.cheat code {
  display: inline-block;
  margin: 1px 2px 1px 0;
  color: var(--code-cmd);
}

/* ---------- Menus and toasts ------------------------------------------------- */

.menu {
  position: relative;
}

.menu-pop {
  position: fixed;
  z-index: 50;
  min-width: 290px;
  max-width: min(380px, calc(100vw - 16px));
  overflow: auto;
  padding: 6px;
  border: 1px solid var(--rule);
  border-radius: var(--radius-l);
  background: var(--surface);
  box-shadow: var(--shadow-pop);
}

.menu-pop[hidden] {
  display: none;
}

.menu-group {
  padding: 10px 10px 4px;
  color: var(--ink-3);
  font-size: 12.5px;
  font-weight: 600;
}

.menu-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 10px;
  border-radius: var(--radius);
  cursor: pointer;
}

.menu-item:hover,
.menu-item:focus {
  outline: none;
  background: var(--surface-hover);
}

.menu-item:focus-visible {
  box-shadow: inset 0 0 0 2px var(--focus);
}

.menu-item[aria-disabled="true"] {
  opacity: 0.5;
  cursor: not-allowed;
}

.menu-item .bullet {
  margin-top: 1px;
}

.menu-item .icon {
  margin-top: 1px;
  color: var(--ink-2);
}

.menu-text {
  display: grid;
  gap: 1px;
}

.menu-label {
  font-size: 14.5px;
  font-weight: 500;
}

.menu-detail {
  color: var(--ink-2);
  font-size: 12.5px;
  line-height: 1.35;
}

.toast-region {
  position: fixed;
  left: 16px;
  bottom: 16px;
  z-index: 60;
}

.toast {
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: min(560px, calc(100vw - 32px));
  padding: 9px 8px 9px 14px;
  border-radius: 8px;
  background: var(--band);
  box-shadow: var(--shadow-pop);
  color: var(--on-band);
  font-size: 14px;
  line-height: 1.4;
  animation: toast-in 220ms var(--ease-out);
}

:root[data-theme="dark"] .toast {
  background: var(--band-raised);
}

.toast :focus-visible {
  outline-color: var(--on-band);
}

.toast-close {
  display: inline-grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--on-band-muted);
  cursor: pointer;
}

.toast-close:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--on-band);
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .toast {
    animation: none;
  }

  * {
    transition: none !important;
  }
}

/* ---------- Responsive ----------------------------------------------------------- */

@media (max-width: 1180px) {
  .speed-value {
    display: none;
  }

  .work {
    grid-template-columns: minmax(320px, 1fr) minmax(0, 1fr);
  }

  .code-hint {
    display: none;
  }
}

@media (max-width: 980px) {
  .tool-end .btn-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }
}

@media (max-width: 759px) {
  :root {
    --band-h: 52px;
  }

  .band {
    gap: 10px;
    padding: 0 8px 0 12px;
  }

  .wordmark span {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
  }

  .main-nav a {
    height: 34px;
    padding: 0 9px;
    font-size: 14px;
  }

  .main-nav a[aria-current="page"]::after {
    left: 9px;
    right: 9px;
    bottom: -9px;
  }

  .nav-count,
  .nav-long {
    display: none;
  }

  .nav-short {
    display: inline !important;
  }

  .studio {
    min-height: 0;
  }

  .toolrow {
    gap: 6px 10px;
    padding: 6px 10px;
  }

  .toolrow .btn:not(.btn-primary) .btn-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  .toolrow .btn {
    height: 40px;
    min-width: 40px;
    padding: 0 10px;
  }

  .speed-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
  }

  .speed input {
    width: 96px;
  }

  .pane-switch {
    display: grid;
    grid-template-columns: 1fr 1fr;
    background: var(--surface);
    border-bottom: 1px solid var(--rule);
  }

  .pane-switch [role="tab"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    height: 42px;
    border: 0;
    background: transparent;
    color: var(--ink-2);
    font: 500 14.5px/1 var(--font-ui);
    cursor: pointer;
  }

  .pane-switch [aria-selected="true"] {
    color: var(--ink);
    box-shadow: inset 0 -3px 0 var(--line);
  }

  .pane-switch :focus-visible {
    outline-offset: -3px;
  }

  .work {
    grid-template-columns: minmax(0, 1fr);
  }

  .work[data-pane="code"] .view-pane,
  .work[data-pane="view"] .code-pane {
    display: none;
  }

  .code-pane {
    border-right: 0;
  }

  .editor {
    --code-size: 16px;
    --code-lh: 24px;
  }

  .status-band {
    font-size: 13.5px;
  }

  .readout {
    top: 8px;
    left: 8px;
    font-size: 12px;
  }

  .view-controls {
    right: 8px;
    bottom: 8px;
  }

  .view-controls .btn {
    width: 44px;
    height: 44px;
  }

  .page-inner {
    padding: 24px 16px 56px;
  }

  .page-head h1 {
    font-size: 26px;
  }

  .ch-row {
    grid-template-columns: 72px minmax(0, 1fr);
    gap: 14px;
    align-items: start;
    padding: 14px 4px;
  }

  .ch-thumb {
    width: 72px;
    height: 72px;
  }

  .ch-thumb svg {
    width: 64px;
    height: 64px;
  }

  .ch-meta {
    grid-column: 2;
    flex-direction: row;
    align-items: center;
    margin-top: -6px;
  }

  .docs {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
    padding: 20px 16px 72px;
  }

  .docs-toc {
    position: static;
  }

  .docs-toc ol {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
  }

  .docs-toc a {
    padding: 5px 10px;
    border: 1px solid var(--rule);
    background: var(--surface);
    font-size: 13.5px;
  }

  .docs-body h1 {
    font-size: 28px;
  }

  .doc-section {
    margin-top: 40px;
  }

  .toast-region {
    left: 8px;
    right: 8px;
    bottom: 8px;
  }
}

.nav-short {
  display: none;
}

@media (max-width: 380px) {
  .mode-switch [role="radio"] {
    width: 30px;
  }

  .main-nav a {
    padding: 0 7px;
  }
}

tool_use_result.content:
/* ---------- Base ---------------------------------------------------------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
}

body {
  background: var(--ground);
  color: var(--ink);
  font: 400 15px/1.5 var(--font-ui);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

* {
  scrollbar-color: var(--rule-strong) transparent;
  scrollbar-width: thin;
}

::selection {
  background: var(--code-sel);
  color: inherit;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

a {
  color: var(--line-strong);
  text-underline-offset: 0.18em;
  text-decoration-thickness: 1px;
}

kbd {
  font: 500 0.85em/1 var(--font-code);
  padding: 2px 6px;
  border: 1px solid var(--rule-strong);
  border-bottom-width: 2px;
  border-radius: var(--radius-s);
  background: var(--surface);
  color: var(--ink);
  white-space: nowrap;
}

code {
  font-family: var(--font-code);
  font-size: 0.94em;
}

.icon {
  flex: none;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

#app {
  min-height: 100dvh;
  display: grid;
  grid-template-rows: auto 1fr;
}

main {
  min-height: 0;
  display: grid;
}

main:focus {
  outline: none;
}

.route[hidden] {
  display: none !important;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  z-index: 100;
  padding: 8px 14px;
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  font-weight: 600;
  box-shadow: var(--shadow-pop);
}

.skip-link:focus {
  top: 8px;
}

/* ---------- Band (the station sign) ----------------------------------------- */

.band {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 20px;
  height: var(--band-h);
  padding: 0 16px;
  background: var(--band);
  color: var(--on-band);
}

.band :focus-visible {
  outline-color: var(--on-band);
}

.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--on-band);
  font: 600 19px/1 var(--font-ui);
  letter-spacing: -0.01em;
  text-decoration: none;
  border-radius: var(--radius);
}

.wordmark .mark {
  flex: none;
}

.mode-switch {
  display: inline-flex;
  gap: 6px;
}

.mode-switch [role="radio"] {
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 30px;
  padding: 0;
  border: 1.5px solid rgba(255, 255, 255, 0.28);
  border-radius: 5px;
  background: transparent;
  color: var(--on-band-muted);
  font: 700 13px/1 var(--font-ui);
  letter-spacing: 0.02em;
  cursor: pointer;
  transition:
    background-color 160ms var(--ease-out),
    border-color 160ms var(--ease-out),
    color 160ms var(--ease-out);
}

.mode-switch [role="radio"]:hover {
  border-color: var(--on-band);
  color: var(--on-band);
}

.mode-switch [data-mode="2d"][aria-checked="true"] {
  background: var(--line-2d);
  border-color: var(--line-2d);
  color: var(--on-line);
}

.mode-switch [data-mode="3d"][aria-checked="true"] {
  background: var(--line-3d);
  border-color: var(--line-3d);
  color: var(--on-line);
}

.band:not([data-route="studio"]) .mode-switch {
  visibility: hidden;
}

.main-nav {
  display: flex;
  gap: 2px;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.main-nav a {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 12px;
  border-radius: var(--radius);
  color: var(--on-band-muted);
  font: 500 15px/1 var(--font-ui);
  text-decoration: none;
  white-space: nowrap;
}

.main-nav a:hover {
  color: var(--on-band);
  background: var(--band-raised);
}

.main-nav a[aria-current="page"] {
  color: var(--on-band);
}

.main-nav a[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: -10px;
  height: 3px;
  border-radius: 2px 2px 0 0;
  background: var(--on-band);
}

.nav-count {
  padding: 2px 6px;
  border-radius: 9px;
  background: var(--band-raised);
  color: var(--on-band-muted);
  font: 500 12px/1.2 var(--font-ui);
  font-variant-numeric: tabular-nums;
}

.theme-toggle {
  margin-left: auto;
}

/* ---------- Buttons ------------------------------------------------------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 36px;
  padding: 0 13px;
  border: 1px solid var(--rule-strong);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  font: 500 14px/1 var(--font-ui);
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
  transition:
    background-color 150ms var(--ease-out),
    border-color 150ms var(--ease-out),
    color 150ms var(--ease-out);
}

.btn:hover {
  background: var(--surface-hover);
}

.btn:active {
  background: var(--rule);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  background: var(--surface);
}

.btn-primary {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--on-line);
  font-weight: 600;
}

.btn-primary:hover {
  background: color-mix(in srgb, var(--primary) 86%, var(--ink));
}

.btn-primary:active {
  background: color-mix(in srgb, var(--primary) 76%, var(--ink));
}

.btn-quiet {
  border-color: transparent;
  background: transparent;
}

.btn-icon {
  width: 36px;
  padding: 0;
}

.btn-small {
  height: 30px;
  padding: 0 10px;
  font-size: 13px;
}

.btn-on-band {
  border-color: transparent;
  background: transparent;
  color: var(--on-band);
}

.btn-on-band:hover {
  background: var(--band-raised);
}

.btn-on-dark {
  border-color: rgba(255, 255, 255, 0.35);
  background: transparent;
  color: var(--on-band);
}

.btn-on-dark:hover {
  background: var(--band-raised);
}

.bullet {
  display: inline-grid;
  place-items: center;
  min-width: 28px;
  height: 22px;
  padding: 0 5px;
  border-radius: 4px;
  background: var(--line);
  color: var(--on-line);
  font: 700 12px/1 var(--font-ui);
  letter-spacing: 0.02em;
}

.bullet-2d {
  background: var(--line-2d);
}

.bullet-3d {
  background: var(--line-3d);
}

/* ---------- Studio layout ----------------------------------------------- */

.studio {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  height: calc(100dvh - var(--band-h));
  min-height: 420px;
}

.toolrow {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 16px;
  padding: 8px 16px;
  background: var(--surface);
  border-bottom: 1px solid var(--rule);
}

.tool-group {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tool-end {
  margin-left: auto;
  gap: 2px;
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--ink-2);
  font-size: 13px;
}

.speed-label {
  font-weight: 500;
}

.speed input {
  width: 120px;
  accent-color: var(--line-strong);
}

.speed-value {
  min-width: 7.5em;
  color: var(--ink);
  font-weight: 500;
}

.pane-switch {
  display: none;
}

.work {
  display: grid;
  grid-template-columns: minmax(340px, 42fr) minmax(0, 58fr);
  min-height: 0;
}

.code-pane {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  min-width: 0;
  min-height: 0;
  background: var(--surface);
  border-right: 1px solid var(--rule);
}

.code-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 9px 16px;
  border-bottom: 1px solid var(--rule);
}

.code-title {
  margin: 0;
  overflow: hidden;
  font: 600 15px/1.3 var(--font-ui);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.code-hint {
  margin-left: auto;
  color: var(--ink-3);
  font-size: 12.5px;
  white-space: nowrap;
}

.editor-host {
  display: grid;
  min-height: 0;
}

/* ---------- Editor ------------------------------------------------------------ */

.editor {
  --code-size: 14px;
  --code-lh: 22px;
  --pad: 12px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  min-height: 0;
  font: 400 var(--code-size) / var(--code-lh) var(--font-code);
  font-variant-ligatures: none;
}

.editor-gutter {
  position: relative;
  overflow: hidden;
  padding-top: var(--pad);
  background: var(--surface-sunk);
  border-right: 1px solid var(--rule);
  user-select: none;
}

.g-row {
  display: grid;
  grid-template-columns: 20px auto;
  align-items: center;
  height: var(--code-lh);
  padding-right: 10px;
}

.g-num {
  min-width: 2.4ch;
  color: var(--ink-3);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.g-route {
  position: relative;
  height: 100%;
}

.on-route .g-route::before {
  content: "";
  position: absolute;
  left: 9px;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--rule-strong);
}

.editor.has-visits .on-route .g-route::before {
  background: var(--line);
}

.route-start .g-route::before {
  top: 50%;
}

.route-end .g-route::before {
  bottom: 50%;
}

.route-start.route-end .g-route::before {
  display: none;
}

.g-station {
  position: absolute;
  z-index: 1;
  left: 5px;
  top: 50%;
  width: 10px;
  height: 10px;
  margin-top: -5px;
  border: 2px solid var(--rule-strong);
  border-radius: 50%;
  background: var(--surface);
}

.g-station.is-visited {
  border-color: var(--line);
  background: var(--line);
}

.g-station.is-here {
  left: 3px;
  width: 14px;
  height: 14px;
  margin-top: -7px;
  border: 3px solid var(--band);
  background: var(--here);
  box-shadow: 0 0 0 2px var(--surface-sunk);
}

.g-station.is-error {
  left: 3px;
  width: 14px;
  height: 4px;
  margin-top: -2px;
  border: 0;
  border-radius: 2px;
  background: var(--error);
}

.editor-body {
  position: relative;
  overflow: hidden;
  min-height: 0;
}

.editor-body:focus-within {
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--focus) 55%, transparent);
}

.editor textarea {
  position: absolute;
  inset: 0;
  z-index: 2;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: var(--pad) 16px;
  border: 0;
  outline: none;
  resize: none;
  overflow: auto;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  font: inherit;
  font-variant-ligatures: none;
  white-space: pre;
  tab-size: 2;
  -webkit-text-fill-color: transparent;
}

.editor textarea::selection {
  background: color-mix(in srgb, var(--focus) 26%, transparent);
  -webkit-text-fill-color: transparent;
}

.editor-layer {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}

.editor-hl {
  position: relative;
  z-index: 1;
  margin: 0;
  padding: var(--pad) 16px;
  color: var(--ink);
  font: inherit;
  font-variant-ligatures: none;
  white-space: pre;
  tab-size: 2;
}

.editor-marks {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.here-band {
  position: absolute;
  top: 0;
  left: 0;
  width: 400vw;
  background: var(--here-soft);
}

.tok-cmd {
  color: var(--code-cmd);
}

.tok-ctl {
  color: var(--code-ctl);
}

.tok-num {
  color: var(--code-num);
}

.tok-name {
  color: var(--code-name);
}

.tok-proc {
  color: var(--code-proc);
  text-decoration: underline dotted 1px;
  text-underline-offset: 4px;
}

.tok-str {
  color: var(--code-str);
}

.tok-str[style] {
  background-image: linear-gradient(var(--swatch), var(--swatch));
  background-repeat: no-repeat;
  background-position: 0 100%;
  background-size: 100% 3px;
}

.tok-cmt {
  color: var(--code-cmt);
}

.tok-br,
.tok-op {
  color: var(--code-br);
}

.tok-bad,
.is-error {
  background-color: var(--error-soft);
  text-decoration: underline wavy var(--error) 1.5px;
  text-decoration-skip-ink: none;
  text-underline-offset: 4px;
}

.tok-mark {
  display: inline-block;
  width: 3px;
  height: 1.15em;
  margin-left: 1px;
  vertical-align: -0.2em;
  border-radius: 1px;
  background: var(--error);
}

.inlay {
  margin-left: 2ch;
  padding: 1px 7px;
  border-radius: 9px;
  background: var(--surface-sunk);
  box-shadow: inset 0 0 0 1px var(--rule);
  color: var(--ink-2);
  font: 500 11.5px/1 var(--font-ui);
  font-variant-numeric: tabular-nums;
  vertical-align: 1px;
}

.error-bubble {
  position: absolute;
  z-index: 3;
  max-width: min(460px, 86vw);
  padding: 7px 11px;
  border: 1px solid color-mix(in srgb, var(--error) 55%, transparent);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow-pop);
  color: var(--error-ink);
  font: 400 13px/1.45 var(--font-ui);
  white-space: normal;
}

.error-bubble::before {
  content: "";
  position: absolute;
  top: -6px;
  left: var(--arrow, 14px);
  width: 10px;
  height: 10px;
  border-top: 1px solid color-mix(in srgb, var(--error) 55%, transparent);
  border-left: 1px solid color-mix(in srgb, var(--error) 55%, transparent);
  background: var(--surface);
  transform: rotate(45deg);
}

/* ---------- Status band ---------------------------------------------------- */

.status-band {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 48px;
  padding: 9px 16px;
  border-top: 1px solid var(--rule);
  background: var(--surface-sunk);
  font-size: 14px;
  line-height: 1.4;
}

.status-band::before {
  content: "";
  flex: none;
  width: 12px;
  height: 12px;
  border: 2px solid var(--rule-strong);
  border-radius: 50%;
  background: var(--surface);
}

.status-band[data-tone="running"]::before,
.status-band[data-tone="paused"]::before {
  border: 3px solid var(--band);
  background: var(--here);
}

.status-band[data-tone="done"]::before {
  border-color: var(--line);
  background: var(--line);
}

.status-band[data-tone="error"] {
  background: var(--error-soft);
  color: var(--error-ink);
}

.status-band[data-tone="error"]::before {
  width: 14px;
  height: 4px;
  border: 0;
  border-radius: 2px;
  background: var(--error);
}

.status-text {
  flex: 1;
  min-width: 0;
  margin: 0;
}

.status-text b {
  font-weight: 600;
}

.status-action {
  flex: none;
}

/* ---------- Drawing view --------------------------------------------------- */

.view-pane {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--paper);
}

.view-host,
.view2d,
.view3d {
  position: absolute;
  inset: 0;
}

.view2d canvas,
.view3d canvas {
  display: block;
  touch-action: none;
  cursor: grab;
}

.view2d.is-dragging canvas {
  cursor: grabbing;
}

.view2d canvas:focus-visible,
.view3d canvas:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: -4px;
}

.readout {
  position: absolute;
  top: 12px;
  left: 12px;
  display: grid;
  gap: 2px;
  max-width: calc(100% - 24px);
  padding: 8px 12px 9px;
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--band) 94%, transparent);
  color: var(--on-band);
  font: 400 12.5px/1.35 var(--font-ui);
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}

.ro-pos {
  font-weight: 600;
  font-size: 13.5px;
}

.ro-dir,
.ro-pen {
  color: var(--on-band-muted);
}

.ro-pen {
  display: flex;
  align-items: center;
}

.swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  margin-right: 7px;
  border-radius: 2px;
  background: var(--swatch);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.55);
}

.view-controls {
  position: absolute;
  right: 12px;
  bottom: 12px;
  display: flex;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--rule);
  border-radius: 8px;
  background: var(--surface);
  box-shadow: 0 2px 8px rgba(17, 26, 45, 0.1);
}

.view-controls .btn {
  border-color: transparent;
  background: transparent;
}

.view-controls .btn:hover {
  background: var(--surface-hover);
}

.studio.view-off .view-controls {
  display: none;
}

.view-off {
  display: grid;
  place-content: center;
  height: 100%;
  max-width: 46ch;
  margin: 0 auto;
  padding: 24px;
  color: var(--ink);
  text-align: left;
}

.view-off strong {
  font-size: 17px;
}

.view-off p {
  margin: 8px 0 0;
  color: var(--ink-2);
}

.view3d.is-off {
  background: var(--surface-sunk);
}

/* ---------- Challenge strip ------------------------------------------------- */

.challenge-strip {
  display: grid;
  gap: 8px;
  padding: 12px 16px 14px;
  border-bottom: 1px solid var(--rule);
  background: var(--surface-sunk);
}

.challenge-strip[hidden] {
  display: none;
}

.ch-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-left: -10px;
}

.ch-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 9px;
  border-radius: 11px;
  background: var(--surface);
  box-shadow: inset 0 0 0 1px var(--rule);
  color: var(--ink-2);
  font: 600 12px/1.2 var(--font-ui);
}

.ch-badge[data-passed="true"] {
  background: var(--success-soft);
  box-shadow: none;
  color: var(--success);
}

.ch-task {
  max-width: 62ch;
  margin: 0;
  font-size: 15px;
  line-height: 1.45;
}

.ch-hint summary {
  width: fit-content;
  color: var(--line-strong);
  font-size: 13.5px;
  font-weight: 500;
  cursor: pointer;
  border-radius: var(--radius-s);
}

.ch-hint p {
  max-width: 62ch;
  margin: 6px 0 0;
  color: var(--ink-2);
  font-size: 14px;
}

.ch-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
}

.btn-check {
  border-color: var(--band);
  background: var(--band);
  color: var(--on-band);
  font-weight: 600;
}

.btn-check:hover {
  background: var(--band-raised);
}

:root[data-theme="dark"] .btn-check {
  border-color: var(--rule-strong);
  background: var(--band-raised);
}

.ch-result {
  display: flex;
  flex-basis: 100%;
  align-items: flex-start;
  gap: 6px;
  margin: 0;
  font-size: 14px;
  line-height: 1.4;
}

.ch-result:empty {
  display: none;
}

.ch-result .icon {
  margin-top: 1px;
}

.ch-result[data-tone="pass"] {
  color: var(--success);
  font-weight: 500;
}

.ch-result[data-tone="fail"] {
  color: var(--error-ink);
}

/* ---------- Pages ------------------------------------------------------------ */

.page {
  overflow: auto;
}

.page-inner {
  width: 100%;
  max-width: 980px;
  margin: 0 auto;
  padding: 36px 24px 72px;
}

.page-head h1 {
  margin: 0 0 10px;
  font: 600 30px/1.15 var(--font-ui);
  letter-spacing: -0.015em;
}

.page-head p {
  max-width: 66ch;
  margin: 0 0 10px;
  color: var(--ink-2);
  font-size: 16px;
}

.progress-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 16px;
  margin-top: 18px !important;
}

.progress-count {
  color: var(--ink);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* Progress drawn as a line with stations. */
.progress-track {
  position: relative;
  display: inline-flex;
  gap: 18px;
  padding: 0 2px;
}

.progress-track::before {
  content: "";
  position: absolute;
  left: 6px;
  right: 6px;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  background: var(--rule-strong);
}

.progress-track span {
  position: relative;
  width: 12px;
  height: 12px;
  border: 2px solid var(--rule-strong);
  border-radius: 50%;
  background: var(--ground);
}

.progress-track span.is-done {
  border-color: var(--line-2d);
  background: var(--line-2d);
}

.ch-list {
  margin: 28px 0 0;
  padding: 0;
  border-top: 1px solid var(--rule);
  list-style: none;
}

.ch-row {
  position: relative;
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr) auto;
  align-items: center;
  gap: 20px;
  padding: 16px 12px;
  border-bottom: 1px solid var(--rule);
  transition: background-color 150ms var(--ease-out);
}

.ch-row:hover {
  background: var(--surface-hover);
}

.ch-row:focus-within {
  background: var(--surface-hover);
}

.ch-thumb {
  display: grid;
  place-items: center;
  width: 96px;
  height: 96px;
  border: 1px solid var(--rule);
  border-radius: 8px;
  background: var(--paper);
  color: #3f4a61;
}

.thumb-start {
  fill: var(--here);
  stroke: #17223b;
  stroke-width: 1.5;
}

.ch-body h2 {
  margin: 0 0 4px;
  font: 600 18px/1.3 var(--font-ui);
}

.ch-body a {
  color: var(--ink);
  text-decoration: none;
  border-radius: var(--radius-s);
}

.ch-body a::after {
  content: "";
  position: absolute;
  inset: 0;
}

.ch-body a:focus-visible {
  outline: none;
}

.ch-row:has(a:focus-visible) {
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}

.ch-body p {
  max-width: 62ch;
  margin: 0;
  color: var(--ink-2);
  font-size: 14.5px;
  line-height: 1.45;
}

.ch-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}

.ch-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--ink-2);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.ch-status.is-done {
  color: var(--success);
}

/* ---------- Reference (Read) -------------------------------------------------- */

.docs {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 48px;
  width: 100%;
  max-width: 1140px;
  margin: 0 auto;
  padding: 36px 24px 96px;
}

.docs-toc {
  position: sticky;
  top: 24px;
  align-self: start;
  font-size: 14px;
}

.toc-title {
  margin: 0 0 8px;
  padding: 0 10px;
  color: var(--ink-3);
  font-weight: 600;
}

.docs-toc ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

.docs-toc a {
  display: block;
  padding: 6px 10px;
  border-radius: var(--radius);
  color: var(--ink-2);
  text-decoration: none;
}

.docs-toc a:hover {
  background: var(--surface-hover);
  color: var(--ink);
}

.docs-body {
  max-width: 74ch;
  font-size: 16px;
  line-height: 1.6;
}

.docs-body h1 {
  margin: 0 0 12px;
  font: 600 34px/1.15 var(--font-ui);
  letter-spacing: -0.02em;
}

.docs-body .lead {
  margin: 0 0 16px;
  color: var(--ink-2);
  font-size: 17px;
  line-height: 1.55;
}

.doc-section {
  margin-top: 56px;
  scroll-margin-top: 24px;
}

.doc-section h2 {
  margin: 0 0 10px;
  font: 600 24px/1.25 var(--font-ui);
  letter-spacing: -0.01em;
}

.doc-section h2:focus {
  outline: none;
}

.doc-section p {
  margin: 0 0 14px;
}

.doc-section ul {
  margin: 0 0 16px;
  padding-left: 22px;
}

.doc-section li {
  margin: 6px 0;
}

.cmd {
  padding: 22px 0 8px;
  border-top: 1px solid var(--rule);
  scroll-margin-top: 24px;
}

.cmd h3 {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px 10px;
  margin: 0 0 6px;
  font: 600 17px/1.3 var(--font-ui);
}

.cmd h3 > code {
  font-size: 18px;
  font-weight: 400;
  color: var(--code-cmd);
}

.aliases {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
}

.aliases code {
  padding: 1px 7px;
  border-radius: var(--radius-s);
  background: var(--surface-sunk);
  box-shadow: inset 0 0 0 1px var(--rule);
  color: var(--ink-2);
  font-size: 13px;
  font-weight: 400;
}

.aliases-en code {
  color: var(--ink-3);
}

.cmd-arg {
  color: var(--ink-2);
  font-size: 14.5px;
}

.cmd-arg span {
  color: var(--ink);
  font-weight: 600;
}

.doc-example {
  display: grid;
  justify-items: start;
  gap: 8px;
  margin: 8px 0 18px;
}

.code-block {
  width: 100%;
  margin: 0;
  padding: 12px 16px;
  overflow: auto;
  border: 1px solid var(--rule);
  border-radius: 8px;
  background: var(--surface);
  font: 400 14px/22px var(--font-code);
  font-variant-ligatures: none;
}

.code-block code {
  font-size: inherit;
}

.table-wrap {
  overflow-x: auto;
}

table.limits,
table.cheat {
  width: 100%;
  margin: 0 0 16px;
  border-collapse: collapse;
  font-size: 15px;
}

table.limits th,
table.limits td,
table.cheat th,
table.cheat td {
  padding: 10px 12px 10px 0;
  border-bottom: 1px solid var(--rule);
  text-align: left;
  vertical-align: top;
}

table.limits th {
  width: 42%;
  font-weight: 500;
}

table.cheat thead th {
  color: var(--ink-3);
  font-size: 13px;
  font-weight: 600;
}

table.cheat code {
  display: inline-block;
  margin: 1px 2px 1px 0;
  color: var(--code-cmd);
}

/* ---------- Menus and toasts ------------------------------------------------- */

.menu {
  position: relative;
}

.menu-pop {
  position: fixed;
  z-index: 50;
  min-width: 290px;
  max-width: min(380px, calc(100vw - 16px));
  overflow: auto;
  padding: 6px;
  border: 1px solid var(--rule);
  border-radius: var(--radius-l);
  background: var(--surface);
  box-shadow: var(--shadow-pop);
}

.menu-pop[hidden] {
  display: none;
}

.menu-group {
  padding: 10px 10px 4px;
  color: var(--ink-3);
  font-size: 12.5px;
  font-weight: 600;
}

.menu-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 10px;
  border-radius: var(--radius);
  cursor: pointer;
}

.menu-item:hover,
.menu-item:focus {
  outline: none;
  background: var(--surface-hover);
}

.menu-item:focus-visible {
  box-shadow: inset 0 0 0 2px var(--focus);
}

.menu-item[aria-disabled="true"] {
  opacity: 0.5;
  cursor: not-allowed;
}

.menu-item .bullet {
  margin-top: 1px;
}

.menu-item .icon {
  margin-top: 1px;
  color: var(--ink-2);
}

.menu-text {
  display: grid;
  gap: 1px;
}

.menu-label {
  font-size: 14.5px;
  font-weight: 500;
}

.menu-detail {
  color: var(--ink-2);
  font-size: 12.5px;
  line-height: 1.35;
}

.toast-region {
  position: fixed;
  left: 16px;
  bottom: 16px;
  z-index: 60;
}

.toast {
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: min(560px, calc(100vw - 32px));
  padding: 9px 8px 9px 14px;
  border-radius: 8px;
  background: var(--band);
  box-shadow: var(--shadow-pop);
  color: var(--on-band);
  font-size: 14px;
  line-height: 1.4;
  animation: toast-in 220ms var(--ease-out);
}

:root[data-theme="dark"] .toast {
  background: var(--band-raised);
}

.toast :focus-visible {
  outline-color: var(--on-band);
}

.toast-close {
  display: inline-grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--on-band-muted);
  cursor: pointer;
}

.toast-close:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--on-band);
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .toast {
    animation: none;
  }

  * {
    transition: none !important;
  }
}

/* ---------- Responsive ----------------------------------------------------------- */

@media (max-width: 1180px) {
  .speed-value {
    display: none;
  }

  .work {
    grid-template-columns: minmax(320px, 1fr) minmax(0, 1fr);
  }

  .code-hint {
    display: none;
  }
}

@media (max-width: 980px) {
  .tool-end .btn-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }
}

@media (max-width: 759px) {
  :root {
    --band-h: 52px;
  }

  .band {
    gap: 10px;
    padding: 0 8px 0 12px;
  }

  .wordmark span {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
  }

  .main-nav a {
    height: 34px;
    padding: 0 9px;
    font-size: 14px;
  }

  .main-nav a[aria-current="page"]::after {
    left: 9px;
    right: 9px;
    bottom: -9px;
  }

  .nav-count,
  .nav-long {
    display: none;
  }

  .nav-short {
    display: inline !important;
  }

  .studio {
    min-height: 0;
  }

  .toolrow {
    gap: 6px 10px;
    padding: 6px 10px;
  }

  .toolrow .btn:not(.btn-primary) .btn-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  .toolrow .btn {
    height: 40px;
    min-width: 40px;
    padding: 0 10px;
  }

  .speed-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
  }

  .speed input {
    width: 96px;
  }

  .pane-switch {
    display: grid;
    grid-template-columns: 1fr 1fr;
    background: var(--surface);
    border-bottom: 1px solid var(--rule);
  }

  .pane-switch [role="tab"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    height: 42px;
    border: 0;
    background: transparent;
    color: var(--ink-2);
    font: 500 14.5px/1 var(--font-ui);
    cursor: pointer;
  }

  .pane-switch [aria-selected="true"] {
    color: var(--ink);
    box-shadow: inset 0 -3px 0 var(--line);
  }

  .pane-switch :focus-visible {
    outline-offset: -3px;
  }

  .work {
    grid-template-columns: minmax(0, 1fr);
  }

  .work[data-pane="code"] .view-pane,
  .work[data-pane="view"] .code-pane {
    display: none;
  }

  .code-pane {
    border-right: 0;
  }

  .editor {
    --code-size: 16px;
    --code-lh: 24px;
  }

  .status-band {
    font-size: 13.5px;
  }

  .readout {
    top: 8px;
    left: 8px;
    font-size: 12px;
  }

  .view-controls {
    right: 8px;
    bottom: 8px;
  }

  .view-controls .btn {
    width: 44px;
    height: 44px;
  }

  .page-inner {
    padding: 24px 16px 56px;
  }

  .page-head h1 {
    font-size: 26px;
  }

  .ch-row {
    grid-template-columns: 72px minmax(0, 1fr);
    gap: 14px;
    align-items: start;
    padding: 14px 4px;
  }

  .ch-thumb {
    width: 72px;
    height: 72px;
  }

  .ch-thumb svg {
    width: 64px;
    height: 64px;
  }

  .ch-meta {
    grid-column: 2;
    flex-direction: row;
    align-items: center;
    margin-top: -6px;
  }

  .docs {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
    padding: 20px 16px 72px;
  }

  .docs-toc {
    position: static;
  }

  .docs-toc ol {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
  }

  .docs-toc a {
    padding: 5px 10px;
    border: 1px solid var(--rule);
    background: var(--surface);
    font-size: 13.5px;
  }

  .docs-body h1 {
    font-size: 28px;
  }

  .doc-section {
    margin-top: 40px;
  }

  .toast-region {
    left: 8px;
    right: 8px;
    bottom: 8px;
  }
}

.nav-short {
  display: none;
}

@media (max-width: 380px) {
  .mode-switch [role="radio"] {
    width: 30px;
  }

  .main-nav a {
    padding: 0 7px;
  }
}

