};
const renderReadout = (s: ControllerState) => {
  const t = s.turtle;
  const az = ((Math.atan2(t.heading[0], t.heading[1]) * 180) / Math.PI + 360) % 360;
  const parts = [`x ${fmt(t.pos[0])}`, `y ${fmt(t.pos[1])}`];
  if (mode === "3d") parts.push(`z ${fmt(t.pos[2])}`);
  let dir = `kierunek ${fmt(az)}°`;
  if (mode === "3d") dir += ` · nachylenie ${fmt((Math.asin(Math.max(-1, Math.min(1, t.heading[2]))) * 180) / Math.PI)}°`;
  readout.innerHTML = `<span class="ro-pos">${parts.join(" · ")}</span><span class="ro-dir">${dir}</span><span class="ro-pen"><span class="swatch" style="--swatch:${t.color}"></span>${t.penDown ? "pisak w dół" : "pisak w górze"} · ${t.width} · ${segs(s.segments.length)}</span>`;
};

const renderButtons = (s: ControllerState) => {
  const pause = btn("pause");
  const paused = s.status === "paused";
  pause.innerHTML = `${icon(paused ? "play" : "pause")}<span class="btn-label">${paused ? "Wznów" : "Pauza"}</span>`;
  pause.disabled = s.status !== "running" && !paused;
  pause.title = `${paused ? "Wznów" : "Pauza"} (${deps.keyLabel("Ctrl+.")})`;
  btn("reset").disabled = s.status === "idle";
  el.dataset.status = s.status;
};

let lastStatus = "";
controller.subscribe((s) => {
  const v = view();
  v.setSegments(s.segments);
  v.setTurtle(s.turtle);
  if (s.status === "running" || s.status === "paused" || s.status === "done") v.follow();
  const settled = s.status !== "running";
  editor.setCurrent(s.status === "running" || s.status === "paused" ? s.current : null);
  if (settled || s.status !== lastStatus) {
    editor.setVisits(s.status === "idle" || s.status === "stopped" ? null : s.visits);
    editor.setError(s.status === "error" ? s.error : null);
  }
  if (s.status !== lastStatus || s.status === "running" || s.status === "paused" || s.status === "error") renderStatus(s);
  renderReadout(s);
  renderButtons(s);
  lastStatus = s.status;
});

// ---- Editing -------------------------------------------------------------
editor.onInput((value) => {
  if (challenge) progress.saveSource(challenge.id, value);
  else workspace.edit(value);
  const before = controller.state.status;
  controller.sourceEdited();
  if (before === "error" || before === "done") {
    setStatus("idle", `Program zmieniony. Uruchom go (<kbd>${deps.keyLabel("Ctrl+Enter")}</kbd>), żeby zobaczyć nowy rysunek.`);
  }
  renderHead();
  if (challenge) setChallengeResult(null);
});

// ---- Actions -------------------------------------------------------------
const isPhone = () => window.matchMedia?.("(max-width: 759px)").matches ?? false;
const showPane = (pane: "code" | "view") => {
  work.dataset.pane = pane;
  $("#tab-code").setAttribute("aria-selected", String(pane === "code"));
  $("#tab-view").setAttribute("aria-selected", String(pane === "view"));
  $("#tab-code").tabIndex = pane === "code" ? 0 : -1;
  $("#tab-view").tabIndex = pane === "view" ? 0 : -1;
  if (pane === "view") view().render();
};
$("#tab-code").addEventListener("click", () => showPane("code"));
$("#tab-view").addEventListener("click", () => showPane("view"));
$(".pane-switch").addEventListener("keydown", (e) => {
  if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
    const next = work.dataset.pane === "code" ? "view" : "code";
    showPane(next);
    $(`#tab-${next}`).focus();
  }
});

const run = () => {
  const v = view();
  v.release();
  // Frame the finished drawing before animating it, so the view stays still.
  const preview = interpret(editor.value, mode);
  if (preview.segments.length) {
    v.setSegments(preview.segments);
    v.fit();
  }
  controller.run(editor.value, mode);
  if (isPhone() && controller.state.status !== "error") showPane("view");
};
const step = () => {
  controller.step(editor.value, mode);
};
const togglePause = () => {
  if (controller.state.status === "running") controller.pause();
  else if (controller.state.status === "paused") controller.resume();
};
const reset = () => {
  controller.reset();
  view().release();
};
btn("run").addEventListener("click", run);
btn("step").addEventListener("click", step);
btn("pause").addEventListener("click", togglePause);
btn("reset").addEventListener("click", reset);

el.querySelector(".view-controls")!.addEventListener("click", (e) => {
  const b = (e.target as HTMLElement).closest<HTMLElement>("[data-view]");
  if (!b) return;
  const v = view();
  ({ in: () => v.zoomBy(1.25), out: () => v.zoomBy(0.8), fit: () => v.fit(), reset: () => v.resetView() })[b.dataset.view as "in"]();
});

// ---- Files and sharing ---------------------------------------------------
const download = (blob: Blob, name: string) => {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
};
function downloadProgram() {
  const name = programFileName(programTitle() === "Szkic" ? "program" : programTitle(), mode);
  download(new Blob([editor.value], { type: "text/plain;charset=utf-8" }), name);
  toaster.show(`Pobrano plik ${name}.`);
}
async function exportPng() {
  view().render();
  const blob = await view().toPNG();
  if (!blob) {
    toaster.show("Nie udało się zapisać rysunku jako PNG.");
    return;
  }
  const name = `${slug(programTitle() === "Szkic" ? "rysunek" : programTitle()) || "rysunek"}-${mode}.png`;
  download(blob, name);
  toaster.show(`Zapisano rysunek: ${name}.`);
}
